	@Override
	protected void shutDown()
	{
		if (monsterIcons != null)
		{
			monsterIcons.shutdown();
			monsterIcons = null;
		}
		if (bankOverlay != null)
		{
			overlayManager.remove(bankOverlay);
			bankOverlay = null;
		}
		bankHighlight = null;
		bankFilter = null;
		layoutManager.removeLayout(BANK_TAG);
		removeBankTagTab();
		tagManager.unregisterTag(BANK_TAG);
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		if (optimizerService != null)
		{
			optimizerService.shutdown();
			optimizerService = null;
		}
		data = null;
		ledger = null;
		exclusions = null;
		protectOnly = null;
		manualOwned = null;
		mobProfiles = null;
		dwmsLink = null;
		stashUnits = null;
		stashChartSeen = false;
		requirementProfile = null;
		realLevels = null;
		boostedLevels = null;
		prayerUnlocks = null;
		dirtySources.clear();
		pendingScans.clear();
		log.info("Loadout Lab stopped");
	}

