	/**
	 * Fire-and-forget: ask DWMS for its tracked storages (see DwmsLink).
	 * Nothing is posted when the plugin is absent or disabled; a missing
	 * reply (a DWMS predating 2.11.5) just means its storages do not
	 * count until it updates.
	 */
	private void requestDwmsStorages()
	{
		if (!config.useDwmsData() || !dwmsPresent())
		{
			return;
		}
		eventBus.post(new PluginMessage(
			DwmsLink.DWMS_NAMESPACE, DwmsLink.REQUEST_NAME, DwmsLink.request()));
	}

	/**
	 * Client thread: answer a storages-request with the ledger's per-source
	 * snapshots plus the manual stored-elsewhere list (quantity 1 each, the
	 * same way the optimizer counts them). Fire-and-forget like the DWMS
	 * side: no reply while the stores are down (plugin shutting down).
	 */
	private void respondWithStorages(String target)
	{
		CollectionLedger currentLedger = ledger;
		ManualOwnedStore manual = manualOwned;
		if (currentLedger == null || manual == null)
		{
			return;
		}
		// Canonicalization needs the item cache; before the login screen
		// exists, ship raw ids rather than crash (DWMS guards the same way).
		IntUnaryOperator canonicalize =
			client.getGameState().getState() >= GameState.LOGIN_SCREEN.getState()
				? itemManager::canonicalize
				: IntUnaryOperator.identity();
		List<Map<String, Object>> storages = new ArrayList<>();
		for (CollectionLedger.Source source : CollectionLedger.Source.values())
		{
			Map<String, Object> entry = StoragesApi.storage(
				"collection", source.key(), -1L, currentLedger.snapshot(source), canonicalize);
			if (entry != null)
			{
				storages.add(entry);
			}
		}
		Map<Integer, Integer> manualItems = new HashMap<>();
		for (int itemId : manual.snapshot())
		{
			manualItems.put(itemId, 1);
		}
		Map<String, Object> manualEntry = StoragesApi.storage(
			"manual", "manualOwned", -1L, manualItems, canonicalize);
		if (manualEntry != null)
		{
			storages.add(manualEntry);
		}
		eventBus.post(new PluginMessage(StoragesApi.NAMESPACE, StoragesApi.RESPONSE_NAME,
			StoragesApi.response(target, storages)));
	}

	/** Check ALL same-named plugins - a hub copy and a sideloaded dev copy
	 * can coexist and the first match may be the disabled loser. */
	private boolean dwmsPresent()
	{
		for (Plugin p : pluginManager.getPlugins())
		{
			if (DWMS_PLUGIN_NAME.equals(p.getName()) && pluginManager.isPluginEnabled(p))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The real account as a replayable fixture: written next to the usage
	 * log on every query, so any in-game result can be reproduced headless
	 * (./gradlew query) or attached to a bug report. Local only.
	 */
	private void exportProfile(PlayerProfile profile)
	{
		Thread writer = new Thread(() ->
		{
			try
			{
				Path file = new File(RuneLite.RUNELITE_DIR,
					"loadout-lab/profile.json").toPath();
				Files.createDirectories(file.getParent());
				Files.writeString(file, profile.toJson());
			}
			catch (Exception ex)
			{
				log.warn("could not export the player profile", ex);
			}
		}, "loadout-lab-profile-export");
		writer.setDaemon(true);
		writer.start();
	}

	/** Panel hook: set (or clear, with null) the bank-highlighted item ids. */
	private void setBankHighlight(Set<Integer> itemIds)
	{
		if (itemIds == null || itemIds.isEmpty() || data == null)
		{
			bankHighlight = null;
			return;
		}
		Set<Integer> expanded = new HashSet<>();
		for (int id : itemIds)
		{
			expanded.addAll(data.equivalentIds(id));
		}
		bankHighlight = expanded;
	}

	/** Panel hook: filter the open bank to these ids via a virtual tag, and -
	 * when {@code layout} is non-null - arrange the set in the bank in the
	 * equipment + inventory shape (a bank-tag layout position array). */
	private void setBankFilter(Set<Integer> itemIds, int[] layout)
	{
		if (itemIds == null || itemIds.isEmpty() || data == null)
		{
			bankFilter = null;
			clientThread.invokeLater(() ->
			{
				if (BANK_TAG.equals(bankTagsService.getActiveTag()))
				{
					bankTagsService.closeBankTag();
				}
				layoutManager.removeLayout(BANK_TAG);
				removeBankTagTab();
				tagManager.unregisterTag(BANK_TAG);
				if (BANK_TAG.equals(configManager.getConfiguration("banktags", "tab")))
				{
					configManager.setConfiguration("banktags", "tab", "");
				}
			});
			return;
		}
		Set<Integer> expanded = new HashSet<>();
		for (int id : itemIds)
		{
			expanded.addAll(data.equivalentIds(id));
		}
		bankFilter = expanded;
		clientThread.invokeLater(() ->
		{
			tagManager.registerTag(BANK_TAG, itemId ->
			{
				Set<Integer> ids = bankFilter;
				return ids != null && ids.contains(itemId);
			});
			if (layout != null)
			{
				layoutManager.saveLayout(new Layout(BANK_TAG, layout));
				ensureBankTagTab();
				bankTagsService.openBankTag(BANK_TAG, 0);
			}
			else
			{
				layoutManager.removeLayout(BANK_TAG);
				removeBankTagTab();
				bankTagsService.openBankTag(BANK_TAG,
					BankTagsService.OPTION_NO_LAYOUT);
			}
		});
	}

	/** The hub "Bank Tag Layouts" plugin's config coordinates - kept only to
	 * clean up the layout its auto-enable wrote for our tag before the
	 * real-tab fix below existed. */
	private static final String BTL_GROUP = "banktaglayouts";
	private static final String BTL_LAYOUT_KEY = "layout_" + BANK_TAG;
	/** The filter tab's icon in the bank's tag strip (rune scimitar). */
	private static final int BANK_TAB_ICON = 1333;

	private boolean bankTagLayoutsActive()
	{
		for (Plugin p : pluginManager.getPlugins())
		{
			if ("Bank Tag Layouts".equals(p.getName()) && pluginManager.isPluginEnabled(p))
			{
				return true;
			}
		}
		return false;
	}

	/** With Bank Tag Layouts running, our tag must exist as a REAL tag tab
	 * while the filter is on: BTL only defers to the core bank-tags layout
	 * for a tab it can find (isVanillaLayoutEnabled = a TagTab AND a core
	 * layout), and with "layout enabled by default" on it auto-enables its
	 * own flat layout over any purely virtual tag every bank rebuild
	 * (field-found 2026-07-20: the cross rendered flat under it; a config
	 * mirror lost the write war). Inventory Setups escapes via a hardcoded
	 * _invsetup_ prefix exemption; a real tab is the road for everyone else.
	 *
	 * IN-MEMORY ONLY - deliberately no TabManager.save(): save() rewrites
	 * the user's whole tagtabs config from the in-memory list, which would
	 * WIPE their real tabs if the list isn't loaded yet. BTL's find() and
	 * the tab strip both read the live list, so persistence buys nothing;
	 * the bank-build hook below re-adds it whenever core reloads the list. */
	private void ensureBankTagTab()
	{
		if (!bankTagLayoutsActive())
		{
			log.debug("bank tab: Bank Tag Layouts not active, skipping");
			return;
		}
		if (tabManager.find(BANK_TAG) != null)
		{
			log.debug("bank tab: already present");
			return;
		}
		TagTab tab = new TagTab();
		tab.setTag(BANK_TAG);
		tab.setIconItemId(BANK_TAB_ICON);
		tabManager.add(tab);
		log.debug("bank tab: added (find now = {})", tabManager.find(BANK_TAG) != null);
	}

	private void removeBankTagTab()
	{
		if (tabManager.find(BANK_TAG) != null)
		{
			tabManager.remove(BANK_TAG);
		}
	}

	/** Re-assert the real tab on every bank build while the filter is on.
	 * Two hooks because BTL applies its layout at PostFired(BANKMAIN_BUILD,
	 * priority -1): the PostFired hook at -0.5 slots BETWEEN core's handlers
	 * (0) and BTL's apply (-1) - the decisive ordering on the first build
	 * after a bank open, where core's BANKMAIN_INIT reload has just wiped
	 * the in-memory list. The FINISHBUILDING hook covers rebuild variants.
	 * (Priority-after-core precedent: Inventory Setups.) */

	@Subscribe(priority = -1)
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING
			|| !BANK_TAG.equals(bankTagsService.getActiveTag()))
		{
			return;
		}
		if (bankFilter == null)
		{
			// A remembered-tab ghost: our tag is open with no filter
			// registered - it shows an empty bank (field bug 2026-07-21).
			log.debug("bank tab: ghost tag open with no filter - closing");
			bankTagsService.closeBankTag();
			return;
		}
		log.debug("bank tab: FINISHBUILDING prefired, ensuring tab");
		ensureBankTagTab();
	}

	@Subscribe(priority = -0.5f)
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_BUILD
			&& bankFilter != null
			&& BANK_TAG.equals(bankTagsService.getActiveTag()))
		{
			log.debug("bank tab: BANKMAIN_BUILD postfired, ensuring tab");
			ensureBankTagTab();
		}
	}

	/** Roster mirror of compute: same client-thread staging, then
	 * ONE shared set per style across the mobs (bestPerStyleAcross). The
	 * FIRST mob anchors per-mob state (exclusions, pins, pinned spell) in
	 * v1 - roster-wide per-mob preferences come later. */

	public void computeRoster(List<MonsterStats> mobs, boolean f2pOnly, boolean onSlayerTask, boolean inWilderness, String spellbookLock, int maxTradeables, int riskBudgetGp, boolean antifirePotion, int deathCharge, boolean specWeapon, Map<CombatStyle, String> boostPicks, Map<CombatStyle, String> prayerPicks, int upgradeBudgetGp, int maxSwaps, Runnable onDone)
	{
		clientThread.invokeLater(() ->
		{
			long stagingStart = System.nanoTime();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				snapshotProfileIfNeeded();
			}
			if (config.useDwmsData())
			{
				requestDwmsStorages();
			}
			RequirementProfile profile = requirementProfile != null
				? requirementProfile : RequirementProfile.MAXED;
			PlayerLevels live = boostedLevels != null ? boostedLevels : PlayerLevels.MAXED;
			PlayerLevels real = realLevels != null ? realLevels : PlayerLevels.MAXED;
			pushPanelCastState(live);
			Map<Integer, Integer> mergedOwned = ownedItems();
			OwnedItems owned = new OwnedItems(mergedOwned, ledger.bankKnown());
			int fingerprint = owned.presenceFingerprint();
			PrayerUnlocks unlocks = prayerUnlocks != null
				? prayerUnlocks : PrayerUnlocks.ALL;
			MonsterStats anchor = mobs.get(0);
			long stagingMs = (System.nanoTime() - stagingStart) / 1_000_000;
			if (stagingMs > 10)
			{
				log.debug("perf: compute staging took {}ms on the client thread", stagingMs);
			}
			optimizerService.bestPerStyleAcross(mobs, real, live, unlocks, profile, owned, fingerprint, f2pOnly,
				onSlayerTask, spellbookLock, globalExcludedByStyle(), maxTradeables, riskBudgetGp, antifirePotion, deathCharge, specWeapon, boostPicks, prayerPicks,
				inWilderness, dreams.snapshot(), upgradeBudgetGp, maxSwaps, perMobExclusions(mobs),
				perMobSims(mobs), pinnedByStyle(anchor.getId()), resolvedPinnedSpell(anchor.getId()),
				mobProfiles.pinnedSpec(anchor.getId()),
				protectOnly.snapshot(),
				roster -> SwingUtilities.invokeLater(() ->
				{
					// EDT-only page assembly: it reads the ledger, profile
					// and config stores the client thread writes (deadlock
					// report 2026-08-12 - the callback thread had been
					// building pages under their locks).
					CommandEngine engine = commandEngine;
					if (engine != null)
					{
						engine.onRosterResults(roster.mobs, roster.perMob);
						refreshHostedView();
					}
					onDone.run();
				}));
		});
	}

	public void compute(MonsterStats monster, boolean f2pOnly, boolean onSlayerTask, boolean inWilderness, String spellbookLock, int maxTradeables, int riskBudgetGp, boolean antifirePotion, int deathCharge, boolean specWeapon, Map<CombatStyle, String> boostPicks, Map<CombatStyle, String> prayerPicks, int upgradeBudgetGp, int maxSwaps, Runnable onDone)
	{
		clientThread.invokeLater(() ->
		{
			long stagingStart = System.nanoTime();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				snapshotProfileIfNeeded();
			}
			// DWMS saves on its own cadence (ConfigSync/shutdown); a per-query
			// re-read keeps imported storages as fresh as they can be. The
			// PluginMessage re-request refreshes the live snapshot the same
			// way (its reply lands after this compute - one-query lag, and
			// DWMS-tracked storages change rarely).
			if (config.useDwmsData())
			{
				requestDwmsStorages();
			}
			RequirementProfile profile = requirementProfile != null
				? requirementProfile : RequirementProfile.MAXED;
			PlayerLevels live = boostedLevels != null ? boostedLevels : PlayerLevels.MAXED;
			PlayerLevels real = realLevels != null ? realLevels : PlayerLevels.MAXED;
			pushPanelCastState(live);
			// One merge, shared by the optimizer request and the export - this
			// runs on the client thread, where every merge is a frame tax.
			Map<Integer, Integer> mergedOwned = ownedItems();
			OwnedItems owned = new OwnedItems(mergedOwned, ledger.bankKnown());
			// The optimizer cache keys on ownership PRESENCE, not quantities
			// - firing an arrow must not re-pay a full compute.
			int fingerprint = owned.presenceFingerprint();
			PrayerUnlocks unlocks = prayerUnlocks != null
				? prayerUnlocks : PrayerUnlocks.ALL;
			exportProfile(new PlayerProfile(
				real, live, unlocks, profile, mergedOwned, ledger.bankKnown(),
				ownedBySources()));
			long stagingMs = (System.nanoTime() - stagingStart) / 1_000_000;
			if (stagingMs > 10)
			{
				log.debug("perf: compute staging took {}ms on the client thread", stagingMs);
			}
			optimizerService.bestPerStyle(monster, real, live, unlocks, profile, owned, fingerprint, f2pOnly,
				onSlayerTask, spellbookLock, excludedByStyle(monster.getId()), maxTradeables, riskBudgetGp, antifirePotion, deathCharge, specWeapon, boostPicks, prayerPicks,
				inWilderness, dreamsWithMobSims(monster), upgradeBudgetGp, maxSwaps,
				pinnedByStyle(monster.getId()), resolvedPinnedSpell(monster.getId()),
				mobProfiles.pinnedSpec(monster.getId()),
				protectOnly.snapshot(),
				results -> SwingUtilities.invokeLater(() ->
				{
					CommandEngine engine = commandEngine;
					if (engine != null)
					{
						engine.onResults(monster, results);
						refreshHostedView();
					}
					onDone.run();
				}));
		});
	}

	/** The one-surface mount: Core's single nav slot hosts the
	 * model-driven surface. */
	private void refreshHostedView()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (navButton == null || companionHost == null || internalSurface == null)
			{
				return; // still loading
			}
			try
			{
				companionHost.mount(internalSurface.asFunction().apply(
					companionLink == null ? null : companionLink.lastPage()));
			}
			catch (RuntimeException ex)
			{
				log.warn("renderer failed; keeping the previous content", ex);
			}
		});
	}

	/** One-time retirement of "stored elsewhere" (2026-08-12): the
	 * concept collapsed into sims - both meant "count this as owned" -
	 * so any manual entries convert to sims once and the old store is
	 * emptied. Native STASH/POH/cargo/looting-bag scanning and the DWMS
	 * import are untouched; only the MANUAL list retires. */
	private void migrateStoredToSims()
	{
		if (manualOwned == null || dreams == null)
		{
			return;
		}
		Set<Integer> stored = new HashSet<>(manualOwned.snapshot());
		if (stored.isEmpty())
		{
			return;
		}
		for (int id : stored)
		{
			if (!dreams.isDreamed(id))
			{
				dreams.toggle(id);
			}
		}
		manualOwned.clear();
		log.info("Loadout Lab: migrated {} 'stored elsewhere' items into sims", stored.size());
	}

	/** VarbitID.SPELLBOOK values -> the contract's book names. */
	private static String spellbookName(int varbit)
	{
		switch (varbit)
		{
			case 1: return "ancient";
			case 2: return "lunar";
			case 3: return "arceuus";
			default: return "standard";
		}
	}

	/** The book plate reacts LIVE to a spellbook swap (classic field
	 * bug 2026-07-21: the chip stayed red after swapping). */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() != VarbitID.SPELLBOOK)
		{
			return;
		}
		CommandEngine engine = commandEngine;
		if (engine != null)
		{
			engine.setLiveSpellbook(spellbookName(event.getValue()));
		}
	}

	/** The classic provenance memo (rebuilt only when ownership moves):
	 * an item's primary storage NAME when a fetch trip is needed, "" at
	 * hand - the source dots key off it. */
	private volatile ItemLocations cachedLocations;
	private volatile int cachedLocationsFingerprint;

	private String primaryLocationOf(int itemId)
	{
		if (ledger == null || manualOwned == null || dwmsLink == null)
		{
			return "";
		}
		int fingerprint = ownedFingerprint();
		ItemLocations found = cachedLocations;
		if (found == null || cachedLocationsFingerprint != fingerprint)
		{
			found = new ItemLocations(ownedBySources(), data == null ? null : data::equivalentIds);
			cachedLocations = found;
			cachedLocationsFingerprint = fingerprint;
		}
		String where = found.primary(itemId);
		return where == null ? "" : where;
	}

	/** Client-thread only. Quest scan is the expensive part - done once per login. */
	private void snapshotProfileIfNeeded()
	{
		if (requirementProfile != null && boostedLevels != null && realLevels != null)
		{
			return;
		}
		Map<Skill, Integer> real = new EnumMap<>(Skill.class);
		Map<Skill, Integer> boosted = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			real.put(skill, client.getRealSkillLevel(skill));
			boosted.put(skill, client.getBoostedSkillLevel(skill));
		}
		// Canary: real Hitpoints can never be below 10. A sub-10 read means
		// the client stats were not populated yet (login race) - skip the
		// snapshot so the next compute retries, instead of poisoning every
		// number this session (field report: all magic at 0.06 dps).
		if (real.getOrDefault(Skill.HITPOINTS, 0) < 10)
		{
			log.debug("skill snapshot looked uninitialized, retrying on next compute");
			return;
		}
		// Stronger canary: stats stream in Skill-ordinal order at login, so a
		// fast first search can catch attack/str/def/hp populated while
		// ranged/prayer/magic still read 1 - and the HP check above passes.
		// The client's own total level is authoritative: a partial snapshot
		// always sums BELOW it (field report: ranged/magic/prayer poisoned
		// at 1 -> blisterwood-stake ranged picks and Wind Strike autocasts).
		int summed = 0;
		for (int level : real.values())
		{
			summed += level;
		}
		if (summed < client.getTotalLevel())
		{
			log.debug("skill snapshot partial ({} < total {}), retrying on next compute",
				summed, client.getTotalLevel());
			return;
		}
		Set<String> quests = new HashSet<>();
		for (Quest quest : Quest.values())
		{
			if (quest.getState(client) == QuestState.FINISHED)
			{
				quests.add(quest.name());
			}
		}
		requirementProfile = new RequirementProfile(real, quests);
		realLevels = PlayerLevels.from(real);
		boostedLevels = PlayerLevels.from(boosted);
		// Unlock-gated prayers: King's Ransom for Piety/Chivalry; scroll
		// unlock varbits for Rigour/Augury (CoX) and Deadeye/Mystic Vigour.
		prayerUnlocks = new PrayerUnlocks(
			quests.contains(Quest.KINGS_RANSOM.name()),
			client.getVarbitValue(5451) == 1,
			client.getVarbitValue(5452) == 1,
			client.getVarbitValue(16097) == 1,
			client.getVarbitValue(16098) == 1);
		snapshotAccount = client.getAccountHash();
	}

	// ------------------------------------------------------------------

	/**
	 * Persistence scope: world type PLUS the account hash - two accounts
	 * on standard worlds must never share a scanned bank (field report:
	 * switching characters showed the previous character's gear).
	 */
	/** Point every per-character store at the current account. ONE place, so a
	 *  store added later cannot be wired into two of the three call sites and
	 *  silently stay global on the third - which is how the exclude/sim lists
	 *  ended up shared across characters (field report 2026-08-25). */
	private void loadAllScopes()
	{
		String scope = worldScope();
		if (scope == null)
		{
			// LOGGED_IN fires before getAccountHash() is populated. Reloading
			// now would swap every store onto a hash-less bucket and drop
			// whatever the player just added (field report 2026-08-26); the
			// stores keep the last known character until the hash arrives.
			return;
		}
		if (ledger != null) { ledger.loadScope(scope); }
		if (manualOwned != null) { manualOwned.loadScope(scope); }
		if (exclusions != null) { exclusions.loadScope(scope); }
		if (dreams != null) { dreams.loadScope(scope); }
		if (protectOnly != null) { protectOnly.loadScope(scope); }
		if (alwaysFilter != null) { alwaysFilter.loadScope(scope); }
		if (mobProfiles != null) { mobProfiles.loadScope(scope); }
		if (supplyDefaults != null) { supplyDefaults.loadScope(scope); }
	}

	private String worldScope()
	{
		long account = client.getAccountHash();
		if (account == -1)
		{
			return null;
		}
		String world = client.getWorldType().contains(WorldType.SEASONAL) ? "seasonal" : "std";
		return world + "." + account;
	}

	/** True only when logged in to a non-members world - the F2P filter default. */
	private boolean onF2pWorld()
	{
		return client.getGameState() == GameState.LOGGED_IN
			&& !client.getWorldType().contains(WorldType.MEMBERS);
	}

	/** Bundled sidebar icon (see scripts/generate_icons.py), drawn fallback if absent. */
	private static BufferedImage loadSidebarIcon()
	{
		try
		{
			return ImageUtil.loadImageResource(LoadoutLabPlugin.class, "icon.png");
		}
		catch (RuntimeException e)
		{
			log.warn("Bundled icon.png missing or unreadable; using drawn fallback", e);
			return drawIcon();
		}
	}

	/** Fallback sidebar icon drawn at runtime. */
	private static BufferedImage drawIcon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setColor(new Color(45, 45, 55));
		g.fillRoundRect(0, 0, 16, 16, 4, 4);
		g.setColor(new Color(140, 200, 140));
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
		g.drawString("LL", 2, 12);
		g.dispose();
		return img;
	}

	@Provides
	LoadoutLabConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LoadoutLabConfig.class);
	}
}

package com.loadoutlab;


/** The build-stamped plugin version (processResources writes
 * version.properties; VersionStampTest pins it to the hub manifest).
 * Neutral home - the report builder, seam hello and UIs all read it. */
public final class PluginVersion
{
	/** Bumped with every release (VersionStampTest pins it to build.gradle):
	 * hub builds ship the resource unexpanded, so this is what players see. */
	public static final String FALLBACK = "0.5.3";
	public static final String VERSION = load();

	public static String stamp(String properties)
	{
		java.util.regex.Matcher m = java.util.regex.Pattern.compile("version=(\\S+)").matcher(properties);
		return m.find() && !m.group(1).contains("${") ? m.group(1) : FALLBACK;
	}

	private PluginVersion()
	{
	}

	private static String load()
	{
		try (java.io.InputStream in = PluginVersion.class.getResourceAsStream(
			"/com/loadoutlab/version.properties"))
		{
			return stamp(new String(in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8));
		}
		catch (Exception ex)
		{
			return "unknown";
		}
	}
}

package com.loadoutlab;

import com.google.gson.*;
import com.loadoutlab.data.*;
import com.loadoutlab.engine.*;
import java.io.IOException;
import java.util.*;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.LinkBrowser;
import okhttp3.*;

/**
 * One-click "open this exact setup in the official wiki calculator":
 * builds the calculator's ImportableData shape from a shown result, POSTs
 * it to the wiki's shortlink service (the same endpoint the calculator's
 * own Share button uses - the ONLY way a full setup can ride a URL), and
 * opens {@code ?id=<shortlink>}. Strictly user-initiated; shapes verified
 * against weirdgloop/osrs-dps-calc source 2026-07-23 (IMPORT_VERSION 10).
 */
@Slf4j
public class WikiCalcLink
{
	static final String SHORTLINK_API = "https://tools.runescape.wiki/osrs-dps/shortlink";
	static final String CALC_URL = "https://tools.runescape.wiki/osrs-dps/?id=";

	/** Their Prayer enum ordinals by the tier names our labels use, and
	 * their Potion enum ordinals by OUR boost labels (the calculator has
	 * no divine variants - identical numbers - so divines map to the
	 * base). Data-driven from wiki_calc_ids.json (a token-free resource).
	 * Fail SOFT like AssumeIcons: this class is constructed in startUp, so
	 * a static-init throw would kill the whole plugin over a share button;
	 * WikiCalcLinkTest pins the exact ordinals loudly instead. */
	private static final Map<String, Integer> PRAYER_IDS = new LinkedHashMap<>();
	private static final Map<String, int[]> POTION_IDS = new LinkedHashMap<>();

	static
	{
		JsonObject root = JsonResources.object("/com/loadoutlab/data/wiki_calc_ids.json");
		JsonResources.stringIntMap(root, "prayerIds", PRAYER_IDS);
		if (root != null && root.has("potionIds"))
		{
			for (Map.Entry<String, JsonElement> e
				: root.getAsJsonObject("potionIds").entrySet())
			{
				JsonArray ordinals = e.getValue().getAsJsonArray();
				int[] ids = new int[ordinals.size()];
				for (int i = 0; i < ids.length; i++)
				{
					ids[i] = ordinals.get(i).getAsInt();
				}
				POTION_IDS.put(e.getKey(), ids);
			}
		}
	}

	private final OkHttpClient http;
	private final Gson gson;

	public WikiCalcLink(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	/** POST the setup to the shortlink service, then open the calculator
	 * on the returned id. Fire-and-forget; failures only log. */
	public void open(MonsterStats mob, DpsResult shown, int dartId, String assumes,
		PlayerLevels real, PlayerLevels live, boolean onSlayerTask, boolean inWilderness)
	{
		Map<String, Object> data = payload(mob, shown, dartId, assumes,
			real, live, onSlayerTask, inWilderness);
		Request request = new Request.Builder()
			.url(SHORTLINK_API)
			.post(RequestBody.create(MediaType.parse("application/json"), gson.toJson(data)))
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("wiki calc shortlink failed", e);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (!r.isSuccessful() || r.body() == null)
					{
						log.warn("wiki calc shortlink HTTP {}", r.code());
						return;
					}
					JsonObject body = gson.fromJson(r.body().string(), JsonObject.class);
					if (body == null || !body.has("data"))
					{
						log.warn("wiki calc shortlink: unexpected response shape");
						return;
					}
					LinkBrowser.browse(CALC_URL + body.get("data").getAsString());
				}
			}
		});
	}

	/** The ImportableData document, built pure for testability. */
	static Map<String, Object> payload(MonsterStats mob, DpsResult shown, int dartId,
		String assumes, PlayerLevels real, PlayerLevels live,
		boolean onSlayerTask, boolean inWilderness)
	{
		List<Integer> prayers = new ArrayList<>();
		BoostProfile boost = null;
		List<Integer> potions = new ArrayList<>();
		for (String token : (assumes == null ? "" : assumes).split(" \\+ "))
		{
			Integer prayerId = PRAYER_IDS.get(token);
			if (prayerId != null)
			{
				prayers.add(prayerId);
				continue;
			}
			int[] potionIds = POTION_IDS.get(token);
			if (potionIds != null)
			{
				for (int id : potionIds)
				{
					potions.add(id);
				}
			}
			for (BoostProfile profile : BoostProfile.values())
			{
				if (profile.toString().equals(token))
				{
					boost = profile;
				}
			}
		}

		Map<String, Object> equipment = new LinkedHashMap<>();
		GearItem quiverAmmo = shown.getLoadout().getQuiverAmmo();
		for (GearSlot slot : GearSlot.values())
		{
			GearItem worn = shown.getLoadout().get(slot);
			// The calc has no quiver concept: the bolts the quiver carries
			// must ride the AMMO slot or their side prices an empty
			// crossbow (field report 2026-08-21). The displaced blessing
			// only carries prayer bonus - nothing the dps math reads.
			if (slot == GearSlot.AMMO && quiverAmmo != null)
			{
				worn = quiverAmmo;
			}
			int id = worn != null ? worn.getId() : -1;
			if (id > 0)
			{
				// Plain maps/lists ONLY in this document: gson's map adapter
				// reflects the runtime type, and the JDK's private
				// Collections$*/ImmutableCollections classes throw
				// InaccessibleObjectException under the module system
				// (field-found 2026-07-23 - the button silently died).
				Map<String, Object> idMap = new LinkedHashMap<>();
				idMap.put("id", id);
				if (slot == GearSlot.WEAPON && dartId > 0)
				{
					// The blowpipe's dart rides the WEAPON's itemVars -
					// never the ammo slot (their own harness note: an
					// ammo-slot dart is a hand-thrown weapon; and the
					// blessing usually occupies ammo anyway, so the dart
					// silently vanished - field report 2026-08-21: cow
					// showed a dartless max 20 vs our dragon-dart 28).
					Map<String, Object> vars = new LinkedHashMap<>();
					vars.put("blowpipeDartId", dartId);
					idMap.put("itemVars", vars);
				}
				equipment.put(slot.getJsonName(), idMap);
			}
		}

		Map<String, Object> loadout = new LinkedHashMap<>();
		loadout.put("name", "Loadout Lab");
		loadout.put("skills", skillsMap(real));
		loadout.put("boosts", boostsMap(boost, real, live));
		loadout.put("equipment", equipment);
		loadout.put("prayers", prayers);
		Map<String, Object> buffs = new LinkedHashMap<>();
		buffs.put("potions", potions);
		buffs.put("onSlayerTask", onSlayerTask);
		buffs.put("inWilderness", inWilderness);
		GearItem soulWeapon = shown.getLoadout().getWeapon();
		if (soulWeapon != null && soulWeapon.getNameLower().contains("soulreaper"))
		{
			// Our sustained model prices the 5-stack steady state - the
			// calc must open there too or it prices ZERO stacks (field
			// 2026-08-21: Jad BiS -23%).
			buffs.put("soulreaperStacks", 5);
		}
		loadout.put("buffs", buffs);
		Map<String, String> style = styleOf(shown.getAttackType());
		String spell = shown.getSpellName();
		if (style != null && "Autocast".equals(style.get("stance"))
			&& (spell == null || spell.isEmpty()))
		{
			// A powered staff: its attackType wears the "magic: <name>"
			// prefix like an autocast, but their POWERED_STAFF category
			// has no Autocast stance - the import fell back to LONGRANGE,
			// 5 ticks (field report 2026-08-21: trident vs cow showed
			// exactly 4/5 of our dps). A real autocast always carries a
			// spell name; a powered staff never does.
			style.put("stance", "Accurate");
		}
		if (style != null)
		{
			loadout.put("style", style);
		}
		if (spell != null && !spell.isEmpty())
		{
			Map<String, Object> spellMap = new LinkedHashMap<>();
			spellMap.put("name", spell);
			loadout.put("spell", spellMap);
		}

		Map<String, Object> monster = new LinkedHashMap<>();
		// profileId: a group's synthetic phase variant maps back to the
		// real row - the calculator only knows real npc ids.
		monster.put("id", mob.profileId());
		// The RAW wiki version - their import keys on exact strings
		// from the shared weirdgloop data ("Post-quest, Awake") and
		// silently falls back to the FIRST same-id row on a miss
		// (field 2026-08-21: the post-quest Duke opened as Awakened,
		// def 316 vs 275 - a -24% phantom). Our display labels are
		// normalized and must never travel.
		monster.put("version", mob.getWikiVersion());
		Map<String, Object> inputs = new LinkedHashMap<>();
		inputs.put("defenceReductions", new LinkedHashMap<>());
		if (mob.getToaInvocationLevel() > 0)
		{
			// The card's Invocation chip - the calculator must open at the
			// same raid level or the cross-check numbers cannot match.
			inputs.put("toaInvocationLevel", mob.getToaInvocationLevel());
		}
		monster.put("inputs", inputs);

		Map<String, Object> data = new LinkedHashMap<>();
		data.put("serializationVersion", 10);
		List<Map<String, Object>> loadouts = new ArrayList<>();
		loadouts.add(loadout);
		data.put("loadouts", loadouts);
		data.put("selectedLoadout", 0);
		data.put("monster", monster);
		return data;
	}

	/** Their PlayerSkills shape. Mining/herblore are not tracked here -
	 * 99 keeps the rare pickaxe-dependent checks permissive. */
	private static Map<String, Integer> skillsMap(PlayerLevels levels)
	{
		Map<String, Integer> skills = new LinkedHashMap<>();
		skills.put("atk", levels.getAttack());
		skills.put("str", levels.getStrength());
		skills.put("def", levels.getDefence());
		skills.put("hp", levels.getHitpoints());
		skills.put("ranged", levels.getRanged());
		skills.put("magic", levels.getMagic());
		skills.put("prayer", levels.getPrayer());
		skills.put("mining", 99);
		skills.put("herblore", 99);
		return skills;
	}

	/** The per-skill boost DELTAS the calculator adds to the base skills -
	 * computed from our own boost model so the math matches exactly. */
	private static Map<String, Integer> boostsMap(BoostProfile boost,
		PlayerLevels real, PlayerLevels live)
	{
		PlayerLevels boosted = boost == null ? real : boost.apply(real, live);
		Map<String, Integer> deltas = new LinkedHashMap<>();
		deltas.put("atk", boosted.getAttack() - real.getAttack());
		deltas.put("str", boosted.getStrength() - real.getStrength());
		deltas.put("def", boosted.getDefence() - real.getDefence());
		deltas.put("hp", 0);
		deltas.put("ranged", boosted.getRanged() - real.getRanged());
		deltas.put("magic", boosted.getMagic() - real.getMagic());
		deltas.put("prayer", 0);
		deltas.put("mining", 0);
		deltas.put("herblore", 0);
		return deltas;
	}

	/** Their PlayerCombatStyle {type, stance} from our attack-type strings:
	 * "slash (aggressive)", "ranged rapid - dragon dart", "magic: Fire
	 * Surge". The style NAME is omitted - the calculator's math reads only
	 * type and stance. */
	static Map<String, String> styleOf(String attackType)
	{
		if (attackType == null || attackType.isEmpty())
		{
			return null;
		}
		Map<String, String> style = new LinkedHashMap<>();
		if (attackType.startsWith("magic"))
		{
			style.put("type", "magic");
			style.put("stance", attackType.startsWith("magic:") ? "Autocast" : "Accurate");
			return style;
		}
		if (attackType.startsWith("ranged"))
		{
			style.put("type", "ranged");
			style.put("stance", attackType.contains("rapid") ? "Rapid" : "Accurate");
			return style;
		}
		int cut = attackType.indexOf(" (");
		style.put("type", cut < 0 ? attackType : attackType.substring(0, cut));
		String stance = cut < 0 ? "aggressive"
			: attackType.substring(cut + 2, attackType.indexOf(')', cut));
		style.put("stance", Character.toUpperCase(stance.charAt(0)) + stance.substring(1));
		return style;
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.*;
import java.util.Map;
import net.runelite.client.config.ConfigManager;

/**
 * The GLOBAL always-filter list (the grey member of the exclude/sim/filter
 * trio, field spec 2026-07-20): items that join EVERY filtered bank view -
 * teleport capes, boss teles, whatever the player always wants at hand.
 * Names are captured at add time (id resolution later needs the client
 * thread), matching the mob-profile filter items.
 */
public class AlwaysFilterStore
{
	static final String CONFIG_GROUP = "loadoutlab";
	static final String KEY = "alwaysFilterItems";

	/** Per-character scope ("std"/"seasonal" plus ".<accountHash>"). Global
	 * before 0.4.1, which is why a main and a test account shared this list. */
	private String worldScope;

	private String key()
	{
		return ScopedKeys.key(worldScope, KEY);
	}

	public synchronized void loadScope(String scope)
	{
		this.worldScope = scope;
		load();
	}

	private final ConfigManager configManager;
	private final Gson gson;
	private final Map<Integer, String> items = new LinkedHashMap<>();

	public AlwaysFilterStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
		load();
	}

	/** Re-read from config - the active RuneLite profile may have changed. */
	public synchronized void clear()
	{
		items.clear();
		save();
	}

	public synchronized void reload()
	{
		load();
	}

	private void load()
	{
		items.clear();
		String json = ScopedKeys.read(configManager, CONFIG_GROUP, worldScope, KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}
		try
		{
			Map<Integer, String> stored = gson.fromJson(json,
				new TypeToken<Map<Integer, String>>(){}.getType());
			if (stored != null)
			{
				items.putAll(stored);
			}
		}
		catch (RuntimeException ex)
		{
			// Corrupt entry: start fresh rather than failing the plugin.
		}
	}

	public synchronized Map<Integer, String> all()
	{
		return Collections.unmodifiableMap(new LinkedHashMap<>(items));
	}

	public synchronized void add(int itemId, String name)
	{
		items.put(itemId, name == null ? ("item " + itemId) : name);
		save();
	}

	public synchronized void remove(int itemId)
	{
		items.remove(itemId);
		save();
	}

	private void save()
	{
		if (items.isEmpty())
		{
			configManager.unsetConfiguration(CONFIG_GROUP, key());
			return;
		}
		configManager.setConfiguration(CONFIG_GROUP, key(), gson.toJson(items));
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.*;
import java.util.Map;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;

/**
 * The persistent "what I own" ledger - Loadout Lab's first differentiator.
 *
 * <p>Container snapshots (equipment, inventory, bank, looting bag), each
 * replaced wholesale when its container is seen, merged on demand into one
 * itemId → quantity view. Persisted through RuneLite's ConfigManager so the
 * ledger survives sessions: your bank from LAST visit still counts today,
 * no re-scan required (unlike per-session scanners).
 *
 * <p>Scoping: RuneLite config profiles already isolate the backing
 * .properties per profile; on top of that, keys carry a world-type prefix so
 * a leagues/seasonal login never pollutes the standard-world ledger.
 *
 * <p>Write discipline (learned on goal-planner): saves are per-snapshot and
 * only when that snapshot actually changed - callers coalesce container
 * events per tick before calling {@link #update}.
 *
 * <p>Item ids are stored RAW. Variant canonicalization (degraded/charged
 * forms mapping to the engine's canonical gear ids via equipment aliases)
 * happens at query time once the data pipeline vendors the alias table.
 */
public class CollectionLedger
{
	static final String CONFIG_GROUP = "loadoutlab";
	private static final TypeToken<Map<Integer, Integer>> MAP_TYPE = new TypeToken<Map<Integer, Integer>>() {};

	/** Ledger sources, each persisted under its own key. */
	public enum Source
	{
		EQUIPMENT("equipment", net.runelite.api.InventoryID.EQUIPMENT.getId()),
		INVENTORY("inventory", net.runelite.api.InventoryID.INVENTORY.getId()),
		BANK("bank", net.runelite.api.InventoryID.BANK.getId()),
		/** Seen when the bag is opened or checked; vital for UIM accounts.
		 * The classic InventoryID enum lacks the newer containers; the
		 * gameval ids are the authoritative modern constants. */
		LOOTING_BAG("lootingBag", InventoryID.LOOTING_BAG),
		/** POH costume storage: one shared container covering the armour
		 * case, wardrobes, treasure chest, and cape rack, seen when a
		 * costume storage interface is opened. */
		POH_COSTUMES("pohCostumes", InventoryID.POH_COSTUMES),
		/** Not container-backed: filled units' default items, read from
		 * the STASH chart (see LoadoutLabPlugin.scanStashChart). The -1
		 * container sentinel makes the per-tick drain's null-container
		 * check clear a stray dirty flag, and keeps STASH out of the
		 * {@link #forContainer} reverse lookup. */
		STASH("stash", -1),
		/** Sailing boat cargo holds, one container per boat slot. */
		CARGO_HOLD_1("cargoHold1", InventoryID.SAILING_BOAT_1_CARGOHOLD),
		CARGO_HOLD_2("cargoHold2", InventoryID.SAILING_BOAT_2_CARGOHOLD),
		CARGO_HOLD_3("cargoHold3", InventoryID.SAILING_BOAT_3_CARGOHOLD),
		CARGO_HOLD_4("cargoHold4", InventoryID.SAILING_BOAT_4_CARGOHOLD),
		CARGO_HOLD_5("cargoHold5", InventoryID.SAILING_BOAT_5_CARGOHOLD);

		private final String key;
		private final int containerId;

		Source(String key, int containerId)
		{
			this.key = key;
			this.containerId = containerId;
		}

		/** The item-container id this source is scanned from, or -1 when
		 * the source is not container-backed (STASH). */
		public int containerId()
		{
			return containerId;
		}

		/**
		 * Reverse lookup: the source scanned from {@code containerId}, or
		 * null when no source uses it. Callers pass an UNMASKED container
		 * id (the 0x8000 modified-container bit already stripped).
		 */
		public static Source forContainer(int containerId)
		{
			// Guard the STASH sentinel: without it, -1 would resolve to
			// STASH instead of "no such container".
			if (containerId < 0)
			{
				return null;
			}
			for (Source s : values())
			{
				if (s.containerId == containerId)
				{
					return s;
				}
			}
			return null;
		}

		/** The persisted config-key segment; also the storage name in the
		 * storages-response PluginMessage (see StoragesApi). */
		public String key()
		{
			return key;
		}
	}

	private final ConfigManager configManager;
	private final Gson gson;

	/** "std" or "seasonal" - set on login before any update/load. */
	private String worldScope = "std";

	private final Map<Source, Map<Integer, Integer>> snapshots = new HashMap<>();

	/** Cached fingerprint of the merged view; recomputed lazily. */
	private transient Integer fingerprint;

	public CollectionLedger(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
		for (Source s : Source.values())
		{
			snapshots.put(s, new HashMap<>());
		}
	}

	/**
	 * Point the ledger at a world scope ("std" or "seasonal") and load that
	 * scope's persisted snapshots, replacing in-memory state.
	 */
	public void loadScope(String scope)
	{
		this.worldScope = scope;
		for (Source s : Source.values())
		{
			Map<Integer, Integer> loaded = null;
			// One-time adoption of pre-account-scoping data ("std.*"): the
			// FIRST character to load it takes it and the legacy entry is
			// removed. Copying instead of moving is what let a second account
			// open on the main's scanned bank (field report 2026-08-26).
			int dot = scope.indexOf('.');
			String legacy = (dot > 0 ? scope.substring(0, dot) : scope) + ".collection." + s.key;
			String json = ScopedKeys.adopt(configManager, CONFIG_GROUP, key(s), legacy);
			if (json != null && !json.isEmpty())
			{
				try
				{
					loaded = gson.fromJson(json, MAP_TYPE.getType());
				}
				catch (RuntimeException e)
				{
					// Corrupt entry: start that snapshot fresh rather than failing.
					loaded = null;
				}
			}
			snapshots.put(s, loaded != null ? loaded : new HashMap<>());
		}
		fingerprint = null;
	}

	/**
	 * Replace one source's snapshot. Persists only when the content actually
	 * changed; returns true in that case (callers use it to invalidate caches).
	 */
	public boolean update(Source source, Map<Integer, Integer> items)
	{
		Map<Integer, Integer> next = new HashMap<>(items);
		if (next.equals(snapshots.get(source)))
		{
			return false;
		}
		snapshots.put(source, next);
		configManager.setConfiguration(CONFIG_GROUP, key(source), gson.toJson(next, MAP_TYPE.getType()));
		fingerprint = null;
		return true;
	}

	/** One source's current snapshot, read-only (itemId → quantity). */
	public Map<Integer, Integer> snapshot(Source source)
	{
		return Collections.unmodifiableMap(snapshots.get(source));
	}

	/** Merged itemId → total quantity across all sources. */
	public Map<Integer, Integer> owned()
	{
		Map<Integer, Integer> merged = new HashMap<>();
		for (Map<Integer, Integer> snap : snapshots.values())
		{
			for (Map.Entry<Integer, Integer> e : snap.entrySet())
			{
				merged.merge(e.getKey(), e.getValue(), Integer::sum);
			}
		}
		return merged;
	}

	/** True once a bank snapshot exists (this session or any previous one). */
	public boolean bankKnown()
	{
		return !snapshots.get(Source.BANK).isEmpty();
	}

	/**
	 * Stable fingerprint of the merged view - the optimizer cache key
	 * component. Changes iff ownership actually changed.
	 */
	public int fingerprint()
	{
		if (fingerprint == null)
		{
			fingerprint = owned().hashCode();
		}
		return fingerprint;
	}

	private String key(Source s)
	{
		return worldScope + ".collection." + s.key;
	}
}

