package com.loadoutlab.collection;

import net.runelite.client.config.ConfigManager;

/**
 * Per-character config keys, plus the one-time adoption of the pre-0.4.1
 * unscoped entry.
 *
 * <p>Field report 2026-08-26: on an install upgraded from 0.4.0 the alt still
 * showed the main's exclude list. The first cut fell back to the unscoped key
 * whenever the scoped one was empty, which is true for EVERY new character -
 * so every character adopted the main's list. Adoption has to happen once and
 * then stop, which means MOVING the entry into the first character that loads
 * it rather than copying it.
 */
final class ScopedKeys
{
	private ScopedKeys()
	{
	}

	/** A scope with no account hash behaves as the pre-0.4.1 bucket, so edits
	 * made before login are adopted by the first character instead of landing
	 * in a key nothing reads. */
	static String key(String scope, String legacyKey)
	{
		return scope == null || scope.isEmpty() ? legacyKey : scope + "." + legacyKey;
	}

	/** Stored JSON for this scope, adopting the legacy entry once. */
	static String read(ConfigManager configManager, String group, String scope, String legacyKey)
	{
		return adopt(configManager, group, key(scope, legacyKey), legacyKey);
	}

	/** As {@link #read}, for a store whose legacy key is not simply the
	 * scoped key without its prefix. */
	static String adopt(ConfigManager configManager, String group, String key, String legacyKey)
	{
		String json = configManager.getConfiguration(group, key);
		if (json != null && !json.isEmpty())
		{
			return json;
		}
		if (key.equals(legacyKey))
		{
			return null;
		}
		String legacy = configManager.getConfiguration(group, legacyKey);
		if (legacy == null || legacy.isEmpty())
		{
			return null;
		}
		// A move, not a copy: the second character must find nothing here.
		configManager.setConfiguration(group, key, legacy);
		configManager.unsetConfiguration(group, legacyKey);
		return legacy;
	}
}

package com.loadoutlab.collection;

import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;

/**
 * Loadout Lab's half of the bidirectional storages contract: other
 * plugins can ask US for the owned-gear ledger the same way we ask
 * Dude, Where's My Stuff - identical request/response shape, each
 * plugin under its own namespace (reciprocity decided 2026-07-11;
 * the config keys in the README's "Data sharing" section stay as the
 * works-while-disabled fallback).
 *
 * <p>Request: namespace "loadoutlab", name "storages-request", data
 * {"source": requesting plugin's display name (required)}. Response:
 * name "storages-response" with "source" ("Loadout Lab"), "target"
 * (the requester's source echoed), "version" (1), and "storages" -
 * one entry per non-empty source with "category", "name",
 * "lastUpdated" (-1; the ledger keeps no timestamps) and "items"
 * ({"id": canonical item id, "quantity": Long}).
 *
 * <p>This class is the pure, testable part; the plugin gathers the
 * snapshots and posts on the client thread (ids canonicalize there).
 */
public final class StoragesApi
{
	public static final String NAMESPACE = "loadoutlab";
	public static final String REQUEST_NAME = "storages-request";
	public static final String RESPONSE_NAME = "storages-response";
	static final int VERSION = 1;
	static final String SOURCE = "Loadout Lab";

	private StoragesApi()
	{
	}

	/** The validated requester name from a storages-request payload,
	 * or null when the request carries no usable source. */
	public static String requester(Map<String, Object> data)
	{
		if (data == null)
		{
			return null;
		}
		Object source = data.get("source");
		return source instanceof String && !((String) source).isEmpty() ? (String) source : null;
	}

	/**
	 * One storage entry for the response: items canonicalized (variants
	 * that collapse to one id sum), non-positive entries dropped.
	 * Returns null when nothing survives - empty storages are omitted,
	 * matching the DWMS side of the contract.
	 */
	public static Map<String, Object> storage(String category, String name, long lastUpdated,
		Map<Integer, Integer> items, IntUnaryOperator canonicalize)
	{
		Map<Integer, Long> canonical = new LinkedHashMap<>();
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			if (e.getKey() <= 0 || e.getValue() <= 0)
			{
				continue;
			}
			canonical.merge(canonicalize.applyAsInt(e.getKey()), (long) e.getValue(), Long::sum);
		}
		if (canonical.isEmpty())
		{
			return null;
		}
		List<Map<String, Object>> itemList = new ArrayList<>(canonical.size());
		for (Map.Entry<Integer, Long> e : canonical.entrySet())
		{
			Map<String, Object> item = new HashMap<>();
			item.put("id", e.getKey());
			item.put("quantity", e.getValue());
			itemList.add(item);
		}
		Map<String, Object> entry = new HashMap<>();
		entry.put("category", category);
		entry.put("name", name);
		entry.put("lastUpdated", lastUpdated);
		entry.put("items", itemList);
		return entry;
	}

	/** The response envelope addressed back to the requester. */
	public static Map<String, Object> response(String target, List<Map<String, Object>> storages)
	{
		Map<String, Object> data = new HashMap<>();
		data.put("source", SOURCE);
		data.put("target", target);
		data.put("version", VERSION);
		data.put("storages", storages);
		return data;
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.client.config.ConfigManager;

/**
 * The GLOBAL trip-supply defaults, set from the grey filter chip's menu
 * (field direction 2026-07-20: "set from the button instead of the panel").
 * Every category defaults to DETECT_BEST - always on - so only categories
 * the player changed are persisted; clearing back to Detect best removes
 * the entry.
 */
public class SupplyDefaultsStore
{
	static final String CONFIG_GROUP = "loadoutlab";
	static final String KEY = "supplyDefaults";

	/** Per-character scope ("std"/"seasonal" plus ".<accountHash>"). Global
	 * before 0.4.1, which is why a main and a test account shared this list. */
	private String worldScope;

	private String key()
	{
		return ScopedKeys.key(worldScope, KEY);
	}

	public synchronized void loadScope(String scope)
	{
		this.worldScope = scope;
		load();
	}
	public static final String DETECT_BEST = "DETECT_BEST";

	private final ConfigManager configManager;
	private final Gson gson;
	private final Map<String, String> choices = new LinkedHashMap<>();

	public SupplyDefaultsStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
		load();
	}

	/** Re-read from config - the active RuneLite profile may have changed. */
	public synchronized void clear()
	{
		choices.clear();
		save();
	}

	public synchronized void reload()
	{
		load();
	}

	private void load()
	{
		choices.clear();
		String json = ScopedKeys.read(configManager, CONFIG_GROUP, worldScope, KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}
		try
		{
			Map<String, String> stored = gson.fromJson(json,
				new TypeToken<Map<String, String>>(){}.getType());
			if (stored != null)
			{
				choices.putAll(stored);
			}
		}
		catch (RuntimeException ex)
		{
			// Corrupt entry: start fresh rather than failing the plugin.
		}
	}

	/** The category's default: DETECT_BEST (always on) unless changed. */
	public synchronized String choice(String category)
	{
		return choices.getOrDefault(category, DETECT_BEST);
	}

	public synchronized void setChoice(String category, String choice)
	{
		if (choice == null || choice.isEmpty() || DETECT_BEST.equals(choice))
		{
			choices.remove(category);
		}
		else
		{
			choices.put(category, choice);
		}
		save();
	}

	private void save()
	{
		if (choices.isEmpty())
		{
			configManager.unsetConfiguration(CONFIG_GROUP, key());
			return;
		}
		configManager.setConfiguration(CONFIG_GROUP, key(), gson.toJson(choices));
	}
}

package com.loadoutlab.command;

import java.util.*;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

/**
 * In-memory undo / redo stack for {@link Command} entries.
 *
 * <p>Standard semantics:
 * <ul>
 *   <li>{@link #execute(Command)} runs the command and pushes onto the
 *       undo stack. Any pending redo entries are cleared (forking history).
 *   <li>{@link #undo()} pops the most recent undo entry, calls
 *       {@code revert()}, and pushes onto the redo stack. If revert returns
 *       false the entry is dropped without being pushed onto redo.
 *   <li>{@link #redo()} pops the most recent redo entry, calls
 *       {@code apply()}, and pushes back onto the undo stack. If apply
 *       returns false the entry is dropped.
 * </ul>
 *
 * <p>The undo stack is bounded - once it exceeds {@link #CAP} entries, the
 * oldest entries are dropped (the redo stack is implicitly bounded by what
 * the user has undone). Both stacks are session-only; they are never
 * persisted. Cleared wholesale on config-profile change, since entries
 * captured against another profile's stores would corrupt this one.
 *
 * <p>Not thread-safe - all calls must come from the EDT (or whichever
 * single thread owns the plugin's panel hooks).
 *
 * <p>Ported from goal planner's command module - keep in lockstep.
 */
@Slf4j
public class CommandHistory
{
	public static final int CAP = 50;

	private final Deque<Command> undoStack = new ArrayDeque<>();
	private final Deque<Command> redoStack = new ArrayDeque<>();

	/** When non-null, execute() appends to this buffer instead of
	 *  pushing to undoStack. endCompound() collapses the buffer into a single
	 *  CompositeCommand and pushes it. */
	private List<Command> compoundBuffer = null;
	private String compoundDescription = null;
	/** Nesting depth counter for begin/endCompound. Without ref-counting,
	 *  an inner endCompound prematurely closes the outer compound. */
	private int compoundDepth = 0;

	/**
	 * Run a command and push it onto the undo stack on success.
	 * Forking behavior: any pending redo entries are cleared.
	 *
	 * @return whatever {@link Command#apply()} returned
	 */
	public boolean execute(Command cmd)
	{
		boolean ok;
		try
		{
			ok = cmd.apply();
		}
		catch (Exception ex)
		{
			log.warn("Command apply threw, dropping: {}", cmd.getDescription(), ex);
			return false;
		}
		if (!ok) return false;
		if (compoundBuffer != null)
		{
			compoundBuffer.add(cmd);
		}
		else
		{
			undoStack.push(cmd);
			redoStack.clear();
			trim();
		}
		return true;
	}

	/**
	 * Begin a compound command. Subsequent {@link #execute} calls collect
	 * into a buffer instead of pushing individually. {@link #endCompound}
	 * collapses the buffer into a single undo entry with the given
	 * description. Nested compounds are ref-counted: only the outermost
	 * end actually closes the buffer.
	 */
	public void beginCompound(String description)
	{
		compoundDepth++;
		if (compoundBuffer != null) return; // already in a compound - just bump the depth
		compoundBuffer = new ArrayList<>();
		compoundDescription = description;
	}

	/** True when a compound is active (between begin/endCompound). */
	public boolean isInCompound()
	{
		return compoundBuffer != null;
	}

	/**
	 * Close the current compound, wrap its commands in a CompositeCommand,
	 * and push it onto the undo stack as a single entry. No-op if no
	 * compound is active or if the buffer is empty.
	 */
	public void endCompound()
	{
		if (compoundDepth > 0) compoundDepth--;
		if (compoundDepth > 0) return; // still inside a nested compound
		if (compoundBuffer == null) return;
		List<Command> buf = compoundBuffer;
		String desc = compoundDescription;
		compoundBuffer = null;
		compoundDescription = null;
		if (buf.isEmpty()) return;
		undoStack.push(new CompositeCommand(buf, desc));
		redoStack.clear();
		trim();
	}

	/**
	 * Pop the most recent undo entry and revert it. On success the entry
	 * moves to the redo stack. On failure the entry is dropped - fail-open.
	 *
	 * @return true if an entry was reverted, false if the stack was empty
	 *         or the revert failed
	 */
	public boolean undo()
	{
		if (undoStack.isEmpty()) return false;
		Command cmd = undoStack.pop();
		boolean ok;
		try
		{
			ok = cmd.revert();
		}
		catch (Exception ex)
		{
			log.warn("Command revert threw, dropping: {}", cmd.getDescription(), ex);
			return false;
		}
		if (!ok)
		{
			log.warn("Command revert returned false, dropping: {}", cmd.getDescription());
			return false;
		}
		redoStack.push(cmd);
		return true;
	}

	/**
	 * Pop the most recent redo entry and re-apply it. On success the entry
	 * moves back to the undo stack. On failure the entry is dropped.
	 */
	public boolean redo()
	{
		if (redoStack.isEmpty()) return false;
		Command cmd = redoStack.pop();
		boolean ok;
		try
		{
			ok = cmd.apply();
		}
		catch (Exception ex)
		{
			log.warn("Command re-apply threw, dropping: {}", cmd.getDescription(), ex);
			return false;
		}
		if (!ok)
		{
			log.warn("Command re-apply returned false, dropping: {}", cmd.getDescription());
			return false;
		}
		undoStack.push(cmd);
		return true;
	}

	public boolean canUndo() { return !undoStack.isEmpty(); }
	public boolean canRedo() { return !redoStack.isEmpty(); }

	/** Description of the next undo target, or null if the stack is empty. */
	public String peekUndoDescription()
	{
		return undoStack.isEmpty() ? null : undoStack.peek().getDescription();
	}

	/** Where BACK lands: the step BELOW the top (the top produced the
	 * CURRENT state - naming it read as "back goes to where you already
	 * are", field bug 2026-07-23). Null once back would reach the
	 * unrecorded start. */
	public String peekUndoTarget()
	{
		Iterator<Command> it = undoStack.iterator();
		if (!it.hasNext())
		{
			return null;
		}
		it.next();
		return it.hasNext() ? it.next().getDescription() : null;
	}

	/** Description of the next redo target, or null if the stack is empty. */
	public String peekRedoDescription()
	{
		return redoStack.isEmpty() ? null : redoStack.peek().getDescription();
	}

	/** Wipe both stacks. */
	public void clear()
	{
		undoStack.clear();
		redoStack.clear();
	}

	private void trim()
	{
		while (undoStack.size() > CAP)
		{
			undoStack.pollLast();
		}
	}

	int undoSize() { return undoStack.size(); }
	int redoSize() { return redoStack.size(); }
}

package com.loadoutlab.command;

import com.loadoutlab.collection.ExclusionStore;
import com.loadoutlab.collection.MonsterProfileStore;
import com.loadoutlab.data.GearSlot;
import java.util.Map;
import java.util.function.*;

/**
 * Factories building a reversible {@link Command} for every deliberate user
 * mutation of Loadout Lab's persistent stores. Each command captures the
 * before-state it needs to revert AT CONSTRUCTION (per the Command
 * contract), so build the command at the moment of the user's action and
 * hand it straight to {@link CommandHistory#execute}.
 *
 * <p>Toggles use set-to-target semantics rather than blind re-toggling:
 * apply drives the flag to the captured target, revert drives it back -
 * idempotent even if something else moved the flag in between.
 *
 * <p>Item labels are passed in by the caller (the plugin adapters resolve
 * them from the gear corpus) so this layer stays free of data-service
 * dependencies and trivially testable.
 */
public final class Commands
{
	private Commands()
	{
	}

	/** A Command from two lambdas plus a label - the shape every factory returns. */
	static Command of(String description, BooleanSupplier apply, BooleanSupplier revert)
	{
		return new Command()
		{
			@Override public boolean apply() { return apply.getAsBoolean(); }
			@Override public boolean revert() { return revert.getAsBoolean(); }
			@Override public String getDescription() { return description; }
		};
	}

	// ---- global item-flag toggles ------------------------------------

	public static Command toggleExclusion(ExclusionStore store, int itemId, String label)
	{
		return toggleFlag(store::isExcluded, store::toggle, itemId, "Exclude ", "Include ", label);
	}




	/**
	 * Shared body for the four global item-flag toggles. The stores each name
	 * their state predicate differently (isExcluded/isDreamed/...), so the
	 * caller hands it in as a method reference alongside the store's flip
	 * method; the public factories keep their concrete store types so call
	 * sites are unaffected. {@code toggle} returns a boolean that is
	 * deliberately discarded - set-to-target semantics only care about the
	 * resulting state.
	 */
	private static Command toggleFlag(IntPredicate isOn, IntConsumer toggle, int itemId,
		String onPrefix, String offPrefix, String label)
	{
		boolean turnOn = !isOn.test(itemId);
		return of((turnOn ? onPrefix : offPrefix) + label,
			() -> setFlag(isOn, toggle, itemId, turnOn),
			() -> setFlag(isOn, toggle, itemId, !turnOn));
	}

	/** Drives the flag to {@code want}, flipping only when it is not already there. */
	static boolean setFlag(IntPredicate isOn, IntConsumer toggle, int itemId, boolean want)
	{
		if (isOn.test(itemId) != want)
		{
			toggle.accept(itemId);
		}
		return true;
	}

	// ---- per-monster profile mutations --------------------------------

	public static Command pin(MonsterProfileStore store, int monsterId, String scope,
		GearSlot slot, int itemId, String label)
	{
		Integer prior = priorPin(store, monsterId, scope, slot);
		return of("Pin " + label,
			() -> { store.pin(monsterId, scope, slot, itemId); return true; },
			() ->
			{
				if (prior == null)
				{
					store.unpin(monsterId, scope, slot);
				}
				else
				{
					store.pin(monsterId, scope, slot, prior);
				}
				return true;
			});
	}

	public static Command unpin(MonsterProfileStore store, int monsterId, String scope,
		GearSlot slot, String label)
	{
		Integer prior = priorPin(store, monsterId, scope, slot);
		return of("Unpin " + label,
			() ->
			{
				if (prior == null)
				{
					return false; // nothing pinned - no-op
				}
				store.unpin(monsterId, scope, slot);
				return true;
			},
			() ->
			{
				if (prior != null)
				{
					store.pin(monsterId, scope, slot, prior);
				}
				return true;
			});
	}

	private static Integer priorPin(MonsterProfileStore store, int monsterId, String scope, GearSlot slot)
	{
		return store.allPins(monsterId).getOrDefault(scope, Map.of()).get(slot);
	}

	public static Command setNote(MonsterProfileStore store, int monsterId, String note)
	{
		String before = store.note(monsterId);
		String after = note == null ? "" : note;
		return of("Edit note",
			() ->
			{
				if (after.equals(before == null ? "" : before))
				{
					return false; // unchanged text - no-op
				}
				store.setNote(monsterId, after);
				return true;
			},
			() -> { store.setNote(monsterId, before); return true; });
	}

	public static Command setPinnedSpell(MonsterProfileStore store, int monsterId, String spellName)
	{
		String before = store.pinnedSpell(monsterId);
		String after = spellName == null ? "" : spellName;
		return of(after.isEmpty() ? "Clear pinned spell" : "Pin spell " + after,
			() ->
			{
				if (after.equals(before == null ? "" : before))
				{
					return false;
				}
				store.setPinnedSpell(monsterId, after);
				return true;
			},
			() -> { store.setPinnedSpell(monsterId, before); return true; });
	}

	public static Command setPinnedSpec(MonsterProfileStore store, int monsterId,
		int itemId, String label)
	{
		int before = store.pinnedSpec(monsterId);
		return of(itemId <= 0 ? "Unpin spec weapon" : "Pin spec " + label,
			() ->
			{
				if (itemId == before)
				{
					return false;
				}
				store.setPinnedSpec(monsterId, itemId);
				return true;
			},
			() -> { store.setPinnedSpec(monsterId, before); return true; });
	}

	public static Command excludeForMob(MonsterProfileStore store, int monsterId, String scope,
		int itemId, String label)
	{
		return of("Exclude here: " + label,
			() -> { store.exclude(monsterId, scope, itemId); return true; },
			() -> { store.removeMobExclusion(monsterId, scope, itemId); return true; });
	}

	public static Command removeMobExclusion(MonsterProfileStore store, int monsterId, String scope,
		int itemId, String label)
	{
		return of("Allow here: " + label,
			() -> { store.removeMobExclusion(monsterId, scope, itemId); return true; },
			() -> { store.exclude(monsterId, scope, itemId); return true; });
	}

	public static Command simForMob(MonsterProfileStore store, int monsterId,
		int itemId, String label)
	{
		return of("Sim here: " + label,
			() -> { store.addSim(monsterId, itemId, label); return true; },
			() -> { store.removeMobSim(monsterId, itemId); return true; });
	}

	public static Command removeMobSim(MonsterProfileStore store, int monsterId,
		int itemId, String label)
	{
		return of("Unsim here: " + label,
			() -> { store.removeMobSim(monsterId, itemId); return true; },
			() -> { store.addSim(monsterId, itemId, label); return true; });
	}

	public static Command addFilterItem(MonsterProfileStore store, int monsterId, String scope,
		int itemId, String name)
	{
		return of("Add trip supply " + name,
			() -> { store.addFilterItem(monsterId, scope, itemId, name); return true; },
			() -> { store.removeMobFilter(monsterId, scope, itemId); return true; });
	}

	public static Command removeFilterItem(MonsterProfileStore store, int monsterId, String scope,
		int itemId)
	{
		// Capture the persisted display name so undo can restore it intact.
		String name = store.allFilterItems(monsterId)
			.getOrDefault(scope, Map.of())
			.getOrDefault(itemId, "item " + itemId);
		return of("Remove trip supply " + name,
			() -> { store.removeMobFilter(monsterId, scope, itemId); return true; },
			() -> { store.addFilterItem(monsterId, scope, itemId, name); return true; });
	}
}

package com.loadoutlab.command;

import java.util.List;

/**
 * A single Command that wraps an ordered list of sub-commands so they
 * appear as one entry in undo/redo history.
 *
 * <p>Apply runs sub-commands in order; revert runs them in reverse order.
 * If any sub-command fails, the composite returns false but does NOT roll
 * back the partially-applied prefix - the {@link CommandHistory}
 * fail-open contract handles this by dropping the entry from history,
 * leaving the partial state in place.
 *
 * <p>Ported from goal planner's command module - keep in lockstep.
 */
public final class CompositeCommand implements Command
{
	private final List<Command> children;
	private final String description;

	public CompositeCommand(List<Command> children, String description)
	{
		this.children = children;
		this.description = description != null ? description : "Compound action";
	}

	@Override
	public boolean apply()
	{
		boolean any = false;
		for (Command c : children)
		{
			if (c.apply()) any = true;
		}
		return any;
	}

	@Override
	public boolean revert()
	{
		boolean any = false;
		for (int i = children.size() - 1; i >= 0; i--)
		{
			if (children.get(i).revert()) any = true;
		}
		return any;
	}

	@Override
	public String getDescription()
	{
		return description;
	}
}

package com.loadoutlab.data;

import com.google.gson.JsonObject;
import com.loadoutlab.data.JsonResources;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.SpriteID;

/**
 * Icon lookups for the compact "assumes" rows: prayer names to prayer-book
 * sprites, boost labels to potion/heart item ids, and spell names to
 * spellbook sprites - so the panel can show a small icon instead of a
 * sentence. Names must match PrayerBonuses / BoostProfile / SpellStats
 * exactly; unmapped names fall back to plain text.
 */
public final class AssumeIcons
{
	/** Generated by scripts/gen_assume_icons.py; drift-guarded by
	 * AssumeIconsDriftTest, which re-reflects the SpriteID constants at
	 * build time so an upstream renumbering goes red instead of quietly
	 * painting the wrong icon. */
	private static final String RESOURCE = "/com/loadoutlab/data/assume_icons.json";

	private static final Map<String, Integer> PRAYERS = new HashMap<>();
	private static final Map<String, Integer> BOOST_ITEMS = new HashMap<>();
	private static final Map<String, Integer> SPELLS = new HashMap<>();

	static
	{
		// Fail-soft on purpose: these are decoration, and an unmapped name
		// already has a plain-text fallback below.
		JsonObject root = JsonResources.object(RESOURCE);
		JsonResources.stringIntMap(root, "prayers", PRAYERS);
		JsonResources.stringIntMap(root, "boostItems", BOOST_ITEMS);
		JsonResources.stringIntMap(root, "spells", SPELLS);
	}

	private AssumeIcons()
	{
	}

	/** Prayer-book sprite id for this prayer name, or -1. A compound
	 * picker label ("Ultimate Strength + Incredible Reflexes") wears its
	 * LEAD prayer's icon (field ask 2026-08-20: no letter fallbacks). */
	public static int prayerSprite(String name)
	{
		Integer exact = PRAYERS.get(name);
		if (exact != null)
		{
			return exact;
		}
		int plus = name == null ? -1 : name.indexOf(" + ");
		if (plus > 0)
		{
			return PRAYERS.getOrDefault(name.substring(0, plus), -1);
		}
		return -1;
	}

	/** Skill icon for a combat style - melee wears the Attack icon. Sprites,
	 * never font glyphs (Tahoe tofu rule); tooltips carry the words. */
	public static int styleSprite(com.loadoutlab.engine.CombatStyle style)
	{
		switch (style)
		{
			case RANGED:
				return SpriteID.Staticons.RANGED;
			case MAGIC:
				return SpriteID.Staticons.MAGIC;
			default:
				return SpriteID.Staticons.ATTACK;
		}
	}

	/** Item id whose icon represents this boost label, or -1. */
	public static int boostItem(String label)
	{
		return BOOST_ITEMS.getOrDefault(label, -1);
	}

	/** Spellbook sprite id for this spell name, or -1. */
	public static int spellSprite(String name)
	{
		return SPELLS.getOrDefault(name, -1);
	}
}

