package com.loadoutlab.engine;
import lombok.Getter;
import java.util.List;
import java.util.Collections;

public final class DpsResult
{
	@Getter
	private final Loadout loadout;
	@Getter
	private final double dps;
	@Getter
	private final double accuracy;
	@Getter
	private final double expectedHit;
	@Getter
	private final int maxHit;
	@Getter
	private final int attackSpeed;
	@Getter
	private final String attackType;
	@Getter
	private final long attackRoll;
	@Getter
	private final long defenceRoll;
	@Getter
	private final int purchaseCost;
	private final String spellName;
	/** Conditional bonuses the calculator actually counted for this set
	 * (salve, wilderness weapon, crystal set...) - user assurance that
	 * the situational math is happening. */
	@Getter
	private final List<String> countedBonuses;
	/** True when the optimizer could not satisfy a dragonfire shield
	 * constraint (no protective shield in the pool) and fell back to the
	 * unconstrained set - the panel must say "assumes a super antifire". */
	@Getter
	private final boolean antifireAssumed;

	public DpsResult(
		Loadout loadout,
		double dps,
		double accuracy,
		double expectedHit,
		int maxHit,
		int attackSpeed,
		String attackType,
		long attackRoll,
		long defenceRoll)
	{
		this(loadout, dps, accuracy, expectedHit, maxHit, attackSpeed, attackType, attackRoll, defenceRoll, loadout == null ? 0 : loadout.getCost(), "");
	}

	public DpsResult(
		Loadout loadout,
		double dps,
		double accuracy,
		double expectedHit,
		int maxHit,
		int attackSpeed,
		String attackType,
		long attackRoll,
		long defenceRoll,
		int purchaseCost,
		String spellName)
	{
		this(loadout, dps, accuracy, expectedHit, maxHit, attackSpeed, attackType,
			attackRoll, defenceRoll, purchaseCost, spellName, Collections.emptyList(), false);
	}

	private DpsResult(
		Loadout loadout,
		double dps,
		double accuracy,
		double expectedHit,
		int maxHit,
		int attackSpeed,
		String attackType,
		long attackRoll,
		long defenceRoll,
		int purchaseCost,
		String spellName,
		List<String> countedBonuses,
		boolean antifireAssumed)
	{
		this.loadout = loadout;
		this.dps = dps;
		this.accuracy = accuracy;
		this.expectedHit = expectedHit;
		this.maxHit = maxHit;
		this.attackSpeed = attackSpeed;
		this.attackType = attackType;
		this.attackRoll = attackRoll;
		this.defenceRoll = defenceRoll;
		this.purchaseCost = Math.max(0, purchaseCost);
		this.spellName = spellName == null ? "" : spellName;
		this.countedBonuses = countedBonuses == null
			? Collections.emptyList() : countedBonuses;
		this.antifireAssumed = antifireAssumed;
	}

	public DpsResult withCountedBonuses(List<String> bonuses)
	{
		return new DpsResult(loadout, dps, accuracy, expectedHit, maxHit, attackSpeed,
			attackType, attackRoll, defenceRoll, purchaseCost, spellName,
			List.copyOf(bonuses), antifireAssumed);
	}

	public DpsResult withAntifireAssumed(boolean assumed)
	{
		return new DpsResult(loadout, dps, accuracy, expectedHit, maxHit, attackSpeed,
			attackType, attackRoll, defenceRoll, purchaseCost, spellName,
			countedBonuses, assumed);
	}

	/**
	 * The higher-dps of two nullable results; the first wins ties. The
	 * one comparison rule for "keep the better candidate" - previously
	 * duplicated by DpsCalculator and LoadoutOptimizer.
	 */
	static DpsResult better(DpsResult first, DpsResult second)
	{
		if (second == null)
		{
			return first;
		}
		if (first == null || second.getDps() > first.getDps())
		{
			return second;
		}
		return first;
	}

	public DpsResult withPurchaseCost(int purchaseCost)
	{
		return new DpsResult(loadout, dps, accuracy, expectedHit, maxHit, attackSpeed,
			attackType, attackRoll, defenceRoll, purchaseCost, spellName, countedBonuses,
			antifireAssumed);
	}

	/** Copy with a reshaped hit model - the per-monster overrides in
	 * DpsCalculator.calculate() (Zulrah cap, vent one-shot, nibbler trio,
	 * Salarin flat, Verac proc) change only these four numbers. */
	DpsResult withHitModel(double dps, double accuracy, double expectedHit, int maxHit)
	{
		return new DpsResult(loadout, dps, accuracy, expectedHit, maxHit, attackSpeed,
			attackType, attackRoll, defenceRoll, purchaseCost, spellName, countedBonuses,
			antifireAssumed);
	}

	/** The autocast spell, or null for powered staves / non-magic - the
	 * calculator passes "" internally for the powered path, which made
	 * null-keyed consumers (the panel's built-in-spell line) miss. */
	public String getSpellName()
	{
		return spellName == null || spellName.isEmpty() ? null : spellName;
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.MonsterStats;
import java.util.Set;

/**
 * Dragonfire: monsters whose wiki style list contains "Dragonfire"
 * (regular/metal/brutal/lava dragons, KBD, Vorkath, Elvarg - baby
 * dragons correctly lack it) need anti-dragon protection. By default
 * the set must provide it via a shield (which also rules out two-
 * handed weapons); the antifire-potion toggle assumes a super
 * antifire instead and lifts the constraint.
 */
public final class DragonfireRules
{
	/** Antifire potion dose ids per tier - the Detect scan and the
	 * consumable chips share them (relocated from the classic panel). */
	public static final int[] SUPER_ANTIFIRE_IDS = {
		21978, 21981, 21984, 21987, 22209, 22212, 22215, 22218};
	public static final int[] REGULAR_ANTIFIRE_IDS = {
		2452, 2454, 2456, 2458, 11951, 11953, 11955, 11957};

	private static final Set<String> PROTECTIVE_SHIELDS = Set.of(
		"anti-dragon shield",
		"dragonfire shield",
		"dragonfire ward",
		"ancient wyvern shield");

	private DragonfireRules()
	{
	}

	public static boolean breathesFire(MonsterStats monster)
	{
		if (monster == null)
		{
			return false;
		}
		for (String style : monster.getOffence().getStyles())
		{
			if ("dragonfire".equalsIgnoreCase(style))
			{
				return true;
			}
		}
		return false;
	}

	public static boolean isProtectiveShield(GearItem item)
	{
		return item != null
			&& PROTECTIVE_SHIELDS.contains(item.getNameLower());
	}

	/** Must this request's sets carry a dragonfire shield? */
	public static boolean shieldRequired(OptimizationRequest request)
	{
		return breathesFire(request.getMonster()) && !request.isAntifirePotion();
	}
}

package com.loadoutlab.engine;

/**
 * External DPS the worn set doesn't produce: the thrall's flat tier dps,
 * folded into the SHOWN numbers only (matching the official calculator's
 * thrall toggle) - never a ranking input. Wiki-verified 2026-07-21:
 * thralls attack every 4 ticks (2.4s), always deal a successful 0..max
 * roll ignoring armour - max 1/2/3 by spell tier (Magic 38/57/76) =
 * 0.208/0.416/0.625 dps, requiring the Arceuus book and the book of the
 * dead wielded or carried. (Vengeance modeling deferred - roadmap.)
 */
public final class ExtraDps
{
	public static final int BOOK_OF_THE_DEAD = 25818;

	private ExtraDps()
	{
	}

	/** The best thrall tier's flat dps at this Magic level (0 below 38). */
	public static double thrallDps(int magicLevel)
	{
		if (magicLevel >= 76)
		{
			return 0.625;
		}
		if (magicLevel >= 57)
		{
			return 0.416;
		}
		if (magicLevel >= 38)
		{
			return 0.208;
		}
		return 0;
	}

	/** The tier name the Magic level reaches, or null below 38. */
	public static String thrallTier(int magicLevel)
	{
		if (magicLevel >= 76)
		{
			return "Greater";
		}
		if (magicLevel >= 57)
		{
			return "Superior";
		}
		if (magicLevel >= 38)
		{
			return "Lesser";
		}
		return null;
	}

}

