package com.loadoutlab.engine;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.JsonResources;
import java.util.*;
import java.util.Map;
import java.util.Set;

/** Weapon/ammo compatibility. The id tables (arrow/bolt tiers, javelins,
 * fixed weapon-ammo pairs) live in ranged_ammo.json - hub token cap. */
public final class RangedAmmo
{
	private static final int DORGESHUUN_CROSSBOW = 8880;
	private static final Map<Integer, Integer> ARROW_TIER_BY_WEAPON = new HashMap<>();
	private static final Map<Integer, Integer> BOLT_TIER_BY_WEAPON = new HashMap<>();
	private static final Map<Integer, Integer> ARROW_TIER_BY_AMMO = new HashMap<>();
	private static final Map<Integer, Integer> BOLT_TIER_BY_AMMO = new HashMap<>();
	private static final Set<Integer> JAVELIN_AMMO = new HashSet<>();
	private static final Set<Integer> JAVELIN_WEAPONS = new HashSet<>();
	private static final Map<Integer, Set<Integer>> PAIRS = new HashMap<>();
	private static final Set<Integer> DORGESHUUN_EXTRA_BOLTS = new HashSet<>();

	static
	{
		JsonObject root = JsonResources.object("/com/loadoutlab/data/ranged_ammo.json");
		JsonResources.intMap(root, "arrowTierByWeapon", ARROW_TIER_BY_WEAPON);
		JsonResources.intMap(root, "boltTierByWeapon", BOLT_TIER_BY_WEAPON);
		JsonResources.intMap(root, "arrowTierByAmmo", ARROW_TIER_BY_AMMO);
		JsonResources.intMap(root, "boltTierByAmmo", BOLT_TIER_BY_AMMO);
		JsonResources.ints(root, "javelinAmmo", JAVELIN_AMMO);
		JsonResources.ints(root, "javelinWeapons", JAVELIN_WEAPONS);
		JsonResources.ints(root, "dorgeshuunExtraBolts", DORGESHUUN_EXTRA_BOLTS);
		if (root != null)
		{
			for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("pairs").entrySet())
			{
				Set<Integer> ammo = new HashSet<>();
				for (JsonElement a : e.getValue().getAsJsonArray())
				{
					ammo.add(a.getAsInt());
				}
				PAIRS.put(Integer.parseInt(e.getKey()), ammo);
			}
		}
	}

	private RangedAmmo()
	{
	}

	public static boolean compatible(GearItem ammo, GearItem weapon)
	{
		if (ammo == null)
		{
			return !weaponUsesProjectileAmmo(weapon);
		}
		if (projectileMatches(ammo, weapon))
		{
			return true;
		}
		return !weaponUsesProjectileAmmo(weapon) && passiveAmmoSlotItem(ammo);
	}

	static boolean strengthApplies(GearItem ammo, GearItem weapon)
	{
		return ammo != null && projectileMatches(ammo, weapon);
	}

	/** Arrow or bolt weapons only - the classes Dizana's quiver can hold
	 * (javelins, darts and chinchompas stay in their own slots). */
	static boolean usesArrowsOrBolts(GearItem weapon)
	{
		return weapon != null
			&& (ARROW_TIER_BY_WEAPON.containsKey(weapon.getId())
				|| BOLT_TIER_BY_WEAPON.containsKey(weapon.getId())
				|| weapon.getId() == DORGESHUUN_CROSSBOW);
	}

	/** A blessing (or other passive ammo-slot item) may ride the freed
	 * slot when the quiver carries the projectiles. */
	static boolean passiveForQuiver(GearItem item)
	{
		return passiveAmmoSlotItem(item);
	}

	private static boolean weaponUsesProjectileAmmo(GearItem weapon)
	{
		if (weapon == null)
		{
			return false;
		}
		int weaponId = weapon.getId();
		return ARROW_TIER_BY_WEAPON.containsKey(weaponId)
			|| BOLT_TIER_BY_WEAPON.containsKey(weaponId)
			|| weaponId == DORGESHUUN_CROSSBOW
			|| JAVELIN_WEAPONS.contains(weaponId)
			|| PAIRS.containsKey(weaponId);
	}

	private static boolean projectileMatches(GearItem ammo, GearItem weapon)
	{
		if (ammo == null || weapon == null)
		{
			return false;
		}
		int ammoId = ammo.getId();
		int weaponId = weapon.getId();
		if (weaponId == DORGESHUUN_CROSSBOW)
		{
			int tier = BOLT_TIER_BY_AMMO.getOrDefault(ammoId, 0);
			return (tier > 0 && tier <= 16) || DORGESHUUN_EXTRA_BOLTS.contains(ammoId);
		}
		Set<Integer> pair = PAIRS.get(weaponId);
		if (pair != null)
		{
			return pair.contains(ammoId);
		}
		if (JAVELIN_WEAPONS.contains(weaponId))
		{
			return JAVELIN_AMMO.contains(ammoId);
		}
		int arrowCap = ARROW_TIER_BY_WEAPON.getOrDefault(weaponId, 0);
		if (arrowCap > 0)
		{
			int tier = ARROW_TIER_BY_AMMO.getOrDefault(ammoId, 0);
			return tier > 0 && tier <= arrowCap;
		}
		int boltCap = BOLT_TIER_BY_WEAPON.getOrDefault(weaponId, 0);
		if (boltCap > 0)
		{
			int tier = BOLT_TIER_BY_AMMO.getOrDefault(ammoId, 0);
			return tier > 0 && tier <= boltCap;
		}
		return false;
	}

	private static boolean passiveAmmoSlotItem(GearItem ammo)
	{
		return ammo.getBonuses().getRangedStrength() <= 0 && ammo.getOffensive().getRanged() <= 0;
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.MonsterStats;

/**
 * Rat bone weapons (bone mace / bone shortbow / bone staff, from Scurrius)
 * - wiki-verified 2026-07-05: they CANNOT be used against anything that is
 * not a rat ("You can only use this weapon against rats."), and against
 * rats they add a flat +10 to the max hit. The bone staff's powered-staff
 * formula already includes the +10 (its wiki max-hit table: 38 at 99
 * Magic = trident-of-the-seas scaling + 10), so only the mace and
 * shortbow take the flat bonus here.
 */
public final class RatBoneRules
{
	private RatBoneRules()
	{
	}

	/** False when this weapon literally cannot be swung at this monster. */
	public static boolean canUse(MonsterStats monster, GearItem weapon)
	{
		return !isRatBone(weapon) || isRat(monster);
	}

	/** Flat max-hit bonus vs rats for the non-staff rat bone weapons. */
	public static int flatMaxHitBonus(MonsterStats monster, GearItem weapon)
	{
		if (weapon == null || !isRat(monster))
		{
			return 0;
		}
		String name = weapon.getNameLower();
		return name.startsWith("bone mace") || name.startsWith("bone shortbow") ? 10 : 0;
	}

	private static boolean isRatBone(GearItem weapon)
	{
		if (weapon == null)
		{
			return false;
		}
		String name = weapon.getNameLower();
		return name.startsWith("bone mace")
			|| name.startsWith("bone shortbow")
			|| name.startsWith("bone staff");
	}

	private static boolean isRat(MonsterStats monster)
	{
		return monster != null && monster.hasAttribute("rat");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.*;
import java.util.*;
import java.util.List;
import java.util.Map;

/**
 * Utility items a fight REQUIRES that pure dps ranking would never
 * pick: Zulrah's snakelings demand a recoil source (ring of recoil,
 * a recoil-charged Ring of suffering, or Echo boots). The optimizer
 * satisfies the requirement with the least-dps-loss option after the
 * main search; owning the UNCHARGED suffering counts as access to the
 * charged form (recoil rings are pocket change).
 */
public final class RequiredUtility
{
	private static final int RING_OF_RECOIL = 2550;
	private static final int SUFFERING_RECOIL = 20655;
	private static final int SUFFERING_UNCHARGED = 19550;
	private static final int SUFFERING_I_RECOIL = 20657;
	private static final int SUFFERING_I_UNCHARGED = 19710;
	private static final int ECHO_BOOTS = 28945;

	/** Satisfying item id -> the owned id that grants access to it. */
	private static final Map<Integer, Integer> RECOIL_ACCESS = new LinkedHashMap<>();

	static
	{
		RECOIL_ACCESS.put(SUFFERING_I_RECOIL, SUFFERING_I_UNCHARGED);
		RECOIL_ACCESS.put(SUFFERING_RECOIL, SUFFERING_UNCHARGED);
		RECOIL_ACCESS.put(ECHO_BOOTS, ECHO_BOOTS);
		RECOIL_ACCESS.put(RING_OF_RECOIL, RING_OF_RECOIL);
	}

	private RequiredUtility()
	{
	}

	public static boolean requiresRecoil(MonsterStats monster)
	{
		return monster != null && "zulrah".equalsIgnoreCase(monster.getName());
	}

	public static boolean hasRecoil(Loadout loadout)
	{
		for (GearItem item : loadout.getGear().values())
		{
			if (item != null && RECOIL_ACCESS.containsKey(item.getId()))
			{
				return true;
			}
		}
		return false;
	}

	/** Recoil items this request may equip, best-first preference. */
	public static List<GearItem> recoilCandidates(LoadoutData data, OptimizationRequest request)
	{
		List<GearItem> result = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : RECOIL_ACCESS.entrySet())
		{
			GearItem item = data.getGear(entry.getKey());
			if (item == null || request.isExcluded(item.getId())
				|| !request.getRequirementProfile().canEquip(item.getRequirements()))
			{
				continue;
			}
			boolean accessible = request.getCandidateMode() == CandidateMode.ALL_STANDARD
				|| request.getOwnedItems().owns(entry.getKey())
				|| request.getOwnedItems().owns(entry.getValue())
				|| request.isDream(entry.getKey());
			if (accessible)
			{
				result.add(item);
			}
		}
		return result;
	}
}

