package com.loadoutlab.engine;

public final class RollMath
{
	static final double SECONDS_PER_TICK = 0.6;

	private RollMath()
	{
	}

	public static double normalAccuracy(long attackRoll, long defenceRoll)
	{
		double atk = attackRoll;
		double def = defenceRoll;
		if (atk < 0)
		{
			atk = Math.min(0, atk + 2);
		}
		if (def < 0)
		{
			def = Math.min(0, def + 2);
		}
		if (atk >= 0 && def >= 0)
		{
			return atk > def
				? 1.0 - ((def + 2.0) / (2.0 * (atk + 1.0)))
				: atk / (2.0 * (def + 1.0));
		}
		if (atk >= 0)
		{
			return 1.0 - 1.0 / ((-def + 1.0) * (atk + 1.0));
		}
		if (def >= 0)
		{
			return 0.0;
		}
		double swappedAtk = -def;
		double swappedDef = -atk;
		return swappedAtk > swappedDef
			? 1.0 - ((swappedDef + 2.0) / (2.0 * (swappedAtk + 1.0)))
			: swappedAtk / (2.0 * (swappedDef + 1.0));
	}

	public static int effectiveLevel(int level, double prayer, int stanceBonus)
	{
		return (int) Math.floor(level * prayer) + stanceBonus + 8;
	}

	public static int maxHitFromEffective(int effectiveLevel, int strengthBonus)
	{
		return Math.max(0, (int) Math.floor((effectiveLevel * (strengthBonus + 64.0) + 320.0) / 640.0));
	}

	public static long attackRoll(int effectiveLevel, int attackBonus)
	{
		return (long) effectiveLevel * (attackBonus + 64L);
	}

	public static long defenceRoll(int effectiveLevel, int defenceBonus)
	{
		return (long) effectiveLevel * (defenceBonus + 64L);
	}

	public static double normalExpectedHit(double accuracy, int maxHit)
	{
		if (maxHit <= 0 || accuracy <= 0.0)
		{
			return 0.0;
		}
		return accuracy * (maxHit / 2.0 + 1.0 / (maxHit + 1.0));
	}

	/** Expected hit under the monster's FLAT ARMOUR, official-calc
	 * semantics (flatAddTransformer, verified 2026-08-21): POSITIVE
	 * armour clamps EVERY roll to max(0, k - armour) - the low rolls
	 * become zeros, which the old shifted-bounds model missed
	 * (Eclipse Moon overpriced ~16%, grey golem ~15%). Negative
	 * armour (Blood/Blue Moon's flat bonus) is an exact bound shift,
	 * delegated so armour-free numbers stay bit-identical. Bounds are
	 * RAW (pre-armour). */
	public static double expectedHitWithFlatArmour(double accuracy, int minHit, int maxHit,
		int armour)
	{
		if (armour <= 0)
		{
			// NEGATIVE armour is a flat damage BONUS, and their
			// transformer applies it after the accurate-zero rule (a
			// landed 0 counts as 1). Shifting the bounds instead
			// silently dropped that bump - every Blood/Blue Moon set ran
			// 0.1-0.5% low (field 2026-08-21). Riding the bonus on top
			// of the normal expectation keeps the bump AND the shift.
			return expectedHit(accuracy, minHit, maxHit) + accuracy * -armour;
		}
		if (maxHit <= 0 || accuracy <= 0.0)
		{
			return 0.0;
		}
		int lo = Math.max(0, Math.min(minHit, maxHit));
		// sum(max(0, k - armour)) over k in [lo, maxHit], closed form: the
		// rolls at or under the armour contribute nothing, the rest are a
		// run of consecutive integers. Walking the rolls gave the same
		// total, but this runs on EVERY melee and ranged trial.
		long first = Math.max((long) lo, (long) armour + 1);
		long sum = first > maxHit ? 0
			: triangle(maxHit - armour) - triangle(first - armour - 1);
		return accuracy * ((double) sum / (maxHit - lo + 1));
	}

	/** 0 + 1 + ... + n; n below zero is an empty run. */
	private static long triangle(long n)
	{
		return n <= 0 ? 0 : n * (n + 1) / 2;
	}

	public static double expectedHit(double accuracy, int minHit, int maxHit)
	{
		if (maxHit <= 0 || accuracy <= 0.0)
		{
			return 0.0;
		}
		if (minHit <= 0)
		{
			return normalExpectedHit(accuracy, maxHit);
		}
		int minimum = Math.min(minHit, maxHit);
		return accuracy * ((minimum + maxHit) / 2.0);
	}

	/** Confliction gauntlets (official BaseCalc): casting one-handed
	 * grants a SECOND accuracy roll, resolved as
	 * double / (1 + double - single) - the same double-roll the fang
	 * uses, folded so the extra roll cannot exceed certainty. */
	public static double conflictionAccuracy(long attackRoll, long defenceRoll)
	{
		double single = normalAccuracy(attackRoll, defenceRoll);
		double doubleRoll = fangAccuracy(attackRoll, defenceRoll);
		double denominator = 1 + doubleRoll - single;
		return denominator <= 0 ? single : doubleRoll / denominator;
	}

	public static double fangAccuracy(long attackRoll, long defenceRoll)
	{
		double atk = attackRoll;
		double def = defenceRoll;
		if (atk < 0)
		{
			atk = Math.min(0, atk + 2);
		}
		if (def < 0)
		{
			def = Math.min(0, def + 2);
		}
		if (atk >= 0 && def >= 0)
		{
			return atk > def
				? 1.0 - (def + 2.0) * (2.0 * def + 3.0) / (atk + 1.0) / (atk + 1.0) / 6.0
				: atk * (4.0 * atk + 5.0) / 6.0 / (atk + 1.0) / (def + 1.0);
		}
		if (atk >= 0)
		{
			return 1.0 - 1.0 / (-def + 1.0) / (atk + 1.0);
		}
		if (def >= 0)
		{
			return 0.0;
		}
		double reversedAttack = -def;
		double reversedDefence = -atk;
		return reversedAttack < reversedDefence
			? reversedAttack * (reversedDefence * 6.0 - 2.0 * reversedAttack + 5.0) / 6.0 / (reversedDefence + 1.0) / (reversedDefence + 1.0)
			: 1.0 - (reversedDefence + 2.0) * (2.0 * reversedDefence + 3.0) / 6.0 / (reversedDefence + 1.0) / (reversedAttack + 1.0);
	}
}

package com.loadoutlab.engine;

/**
 * Boat-cannon math (wiki: Boat combat / Cannons, verified 2026-08-31). Pure
 * formulas; the data (per-tier strengths, accuracies, tick rate) lives in
 * NavalCombat and callers pass numbers in.
 *
 * <p>Player-fired: max hit rides the player's EFFECTIVE ranged level - the
 * caller applies prayer/void through the engine's existing effective-level
 * machinery, exactly as land ranged does - and the worn ranged strength
 * bonus counts EXCLUDING the weapon, shield and ammo slots (wiki: those
 * three are ignored at the cannon).
 *
 * <p>Crew-fired: the last documented formula scales a base max hit by the
 * crew's Privateering level, (priv + 13) / 20. The wiki flags this formula
 * out-of-date with the real one unknown, so it is isolated HERE and marked
 * by NavalCombat.crewFormulaStale() - when the corrected formula lands,
 * this one method changes and every caller stays put.
 */
public final class ShipCannon
{
	/** All cannons fire on the same cycle regardless of tier. */
	public static final double ATTACK_SECONDS = 4.2;

	private ShipCannon()
	{
	}

	/**
	 * Max hit for a player-fired cannon:
	 * floor((level * (cannonStr + ballStr + wornStr + 64) + 320) / 640),
	 * plus one when a perildance bitter keg is aboard.
	 */
	public static int playerMaxHit(int effectiveRanged, int cannonStrength,
		int ballStrength, int wornRangedStrength, boolean perildance)
	{
		long strength = cannonStrength + ballStrength + wornRangedStrength + 64L;
		int hit = (int) ((effectiveRanged * strength + 320L) / 640L);
		return hit + (perildance ? 1 : 0);
	}

	/** The stale-but-documented crew scaling: floor(base * (priv + 13) / 20). */
	public static int crewMaxHit(int baseMaxHit, int privateering)
	{
		return (int) (baseMaxHit * (privateering + 13L) / 20L);
	}

	/** The cannon's equipment accuracy: its heavy-ranged accuracy plus the
	 * ball's, plus worn ranged accuracy excluding weapon/shield/ammo. Rolls
	 * against the monster's HEAVY defence through the standard machinery. */
	public static int equipmentAccuracy(int cannonHeavyAccuracy, int ballAccuracy,
		int wornRangedAccuracy)
	{
		return cannonHeavyAccuracy + ballAccuracy + wornRangedAccuracy;
	}

	/**
	 * Hit chance vs the monster's HEAVY ranged defence, through the same
	 * roll math the land engine uses. Effective level is visible ranged
	 * + 8 (no stance bonus at a cannon); prayer accuracy multipliers are
	 * the caller's concern, matching how the wiki's calculator treats
	 * prayer as an input to the level term.
	 */
	public static double hitChance(int effectiveRanged, int equipmentAccuracy,
		int monsterDefence, int monsterHeavyBonus)
	{
		long attack = RollMath.attackRoll(effectiveRanged + 8, equipmentAccuracy);
		long defence = RollMath.defenceRoll(monsterDefence + 9, monsterHeavyBonus);
		return RollMath.normalAccuracy(attack, defence);
	}

	/** DPS of one cannon: average landed damage over the 7-tick cycle.
	 * hitChance in [0,1]; a landed hit averages (maxHit / 2) with the
	 * uniform damage roll the game uses. */
	public static double dps(int maxHit, double hitChance)
	{
		return hitChance * (maxHit / 2.0) / ATTACK_SECONDS;
	}
}

package com.loadoutlab.engine;

import lombok.Getter;
import com.loadoutlab.data.*;
import java.util.*;
import java.util.List;

/**
 * Special-attack definitions and expected-damage math.
 *
 * <p>Every entry's cost/modifiers were verified against the OSRS Wiki
 * "Special attacks" page (and individual weapon pages) on 2026-07-05.
 * Accuracy modifiers multiply the ATTACK ROLL (not the final hit chance),
 * matching in-game mechanics; damage modifiers scale the max hit.
 *
 * <p>Expected damage is per single use of the special attack, against the
 * monster the base result was computed for. Utility effects (defence
 * drains, heals, bolt procs) are described in {@link #getNote()} but not
 * folded into the number.
 */
public final class SpecialAttack
{
	public enum Kind
	{
		/** One hit: accuracy and/or damage multipliers. */
		SINGLE,
		/** Two fully independent hits (dragon dagger, dragon knife). */
		DOUBLE_INDEPENDENT,
		/** Two hits that share one accuracy outcome (abyssal dagger). */
		LINKED_DOUBLE,
		/** Guaranteed damage, uniform 50-150% of max (voidwaker). */
		VOIDWAKER,
		/** Up to 4 accuracy rolls; damage tier by which roll landed (dragon claws). */
		CLAWS,
		/** Two hits, boosted damage roll with a minimum per hit, capped at 48 (dark bow). */
		DARK_BOW,
		/** Two arrows; custom prayer-less max-hit formula, 10/7 accuracy (magic shortbow). */
		MSB_SNAPSHOT,
		/** +10% damage; a second hit at 75% accuracy vs large monsters (halberds). */
		HALBERD_SWEEP,
		/** An instant extra normal attack (granite maul). */
		EXTRA_ATTACK,
		/** Level-scaled unique damage roll (volatile nightmare staff). */
		VOLATILE,
		/** One accuracy roll; a hit deals EXACTLY damageMultiplier * max, no damage roll (sunspear). */
		FIXED_FRACTION,
		/** Four independent accuracy rolls; damage tier scales with successes (crimson kisten). */
		MULTI_ROLL_TIERED,
		/** Claws-style cascade with tier means 1.25/1.00/0.75 of max (burning claws). */
		CASCADE_CLAWS,
	}

	private static final int DARK_BOW_CAP = 48;

	private final String[] namePrefixes;
	@Getter
	private final String displayName;
	@Getter
	private final CombatStyle style;
	@Getter
	private final Kind kind;
	@Getter
	private final int energyCost;
	private final double accuracyMultiplier;
	private final double damageMultiplier;
	@Getter
	private final String note;
	/** Defence drained on a damaging hit, as a fraction of CURRENT defence
	 * (DWH 0.30, elder maul 0.35); 0 for non-drain specs. BGS drains by
	 * damage dealt - modeled via {@link #drainsByDamage}. */
	private final double defenceDrainFraction;
	private final boolean drainsByDamage;
	/** Drains DEFENCE by this fraction of the target's MAGIC level per
	 * landed spec (Tonalztics of ralos' Division - wiki 2026-08-09:
	 * 12.5% per glaive hit, two glaives charged = 25% per spec). */
	private final double magicDrainFraction;

	private SpecialAttack(String[] namePrefixes, String displayName, CombatStyle style, Kind kind,
		int energyCost, double accuracyMultiplier, double damageMultiplier, String note,
		double defenceDrainFraction, boolean drainsByDamage, double magicDrainFraction)
	{
		this.defenceDrainFraction = defenceDrainFraction;
		this.drainsByDamage = drainsByDamage;
		this.magicDrainFraction = magicDrainFraction;
		this.namePrefixes = namePrefixes;
		this.displayName = displayName;
		this.style = style;
		this.kind = kind;
		this.energyCost = energyCost;
		this.accuracyMultiplier = accuracyMultiplier;
		this.damageMultiplier = damageMultiplier;
		this.note = note;
	}

	/** Wiki-verified entries live in special_attacks.json (hub token cap:
	 * data rides resources, not source). Order matters: more specific
	 * prefixes ("magic shortbow (i)") come first in the file. */
	private static final List<SpecialAttack> REGISTRY = loadRegistry();

	private static List<SpecialAttack> loadRegistry()
	{
		List<SpecialAttack> specs = new ArrayList<>();
		try
		{
			for (com.google.gson.JsonElement element : JsonResources.array(
				"/com/loadoutlab/data/special_attacks.json"))
			{
				com.google.gson.JsonObject row = element.getAsJsonObject();
				List<String> prefixes = new ArrayList<>();
				JsonResources.strings(row, "prefixes", prefixes);
				specs.add(new SpecialAttack(prefixes.toArray(new String[0]),
					row.get("name").getAsString(),
					CombatStyle.valueOf(row.get("style").getAsString()),
					Kind.valueOf(row.get("kind").getAsString()),
					row.get("cost").getAsInt(),
					row.get("accuracy").getAsDouble(),
					row.get("damage").getAsDouble(),
					row.get("note").getAsString(),
					row.get("drainFraction").getAsDouble(),
					row.get("drainsByDamage").getAsBoolean(),
					row.has("drainMagicFraction")
						? row.get("drainMagicFraction").getAsDouble() : 0));
			}
		}
		catch (Exception e)
		{
			// A malformed table must never take the client down; the spec
			// tests fail loudly on an empty registry instead.
			return Collections.emptyList();
		}
		return specs;
	}


	/** The definition for this weapon at this combat style, or null. */
	public static SpecialAttack match(GearItem item, CombatStyle style)
	{
		SpecialAttack spec = match(item);
		return spec != null && spec.style == style ? spec : null;
	}

	/** Style-free match: the spec swap is its own weapon switch, so every
	 * spec weapon is a candidate for ANY set (field request 2026-07-17 -
	 * "sometimes you want to use magic + chally"). */
	public static SpecialAttack match(GearItem item)
	{
		if (item == null || item.getSlot() != GearSlot.WEAPON)
		{
			return null;
		}
		String name = item.getNameLower();
		for (SpecialAttack spec : REGISTRY)
		{
			for (String prefix : spec.namePrefixes)
			{
				if (name.startsWith(prefix))
				{
					return spec;
				}
			}
		}
		return null;
	}

	/**
	 * Expected damage of ONE special attack, given the normal-attack result
	 * for the same loadout (source of max hit and attack/defence rolls).
	 */
	public double expectedDamage(DpsResult base, MonsterStats monster, PlayerLevels levels)
	{
		// The Wardens' ejected core (wiki): melee "will always deal their
		// max hit" - hitChance and every damage roll collapse to their
		// caps. Without this, the rolls below would halve every spec's
		// value at the one place the game is built around spec dumping.
		if (style == CombatStyle.MELEE && MonsterMechanics.isWardenCore(monster))
		{
			return coreMaxDamage(base, monster);
		}
		long attackRoll = base.getAttackRoll();
		long defenceRoll = base.getDefenceRoll();
		double hitChance = RollMath.normalAccuracy(
			(long) (attackRoll * accuracyMultiplier), defenceRoll);
		int max = base.getMaxHit();

		switch (kind)
		{
			case SINGLE:
				return hitChance * mean((int) (max * damageMultiplier));
			case DOUBLE_INDEPENDENT:
				return 2 * hitChance * mean((int) (max * damageMultiplier));
			case LINKED_DOUBLE:
				// One accuracy outcome for both hits.
				return hitChance * 2 * mean((int) (max * damageMultiplier));
			case VOIDWAKER:
				// Uniform 50-150% of max, no accuracy roll: averages exactly max.
				return max;
			case CLAWS:
				return clawsExpected(hitChance, max);
			case DARK_BOW:
				return darkBowExpected(hitChance, max, usesDragonArrows(base));
			case MSB_SNAPSHOT:
				return 2 * hitChance * mean(snapshotMax(base, levels));
			case HALBERD_SWEEP:
			{
				double first = hitChance * mean((int) (max * damageMultiplier));
				if (monster != null && monster.getSize() > 1)
				{
					double second = RollMath.normalAccuracy((long) (attackRoll * 0.75), defenceRoll);
					first += second * mean((int) (max * damageMultiplier));
				}
				return first;
			}
			case EXTRA_ATTACK:
				return base.getExpectedHit();
			case FIXED_FRACTION:
				// No damage roll: a hit deals exactly damageMultiplier * max.
				return hitChance * damageMultiplier * max;
			case MULTI_ROLL_TIERED:
				return multiRollTieredExpected(hitChance, max);
			case CASCADE_CLAWS:
				return cascadeClawsExpected(hitChance, max);
			case VOLATILE:
			default:
				return hitChance * mean(volatileMax(base, levels));
		}
	}

	/** Every melee hit at the Warden's core deals its max (wiki) - each
	 * kind collapses to its hit count at the TOP of its damage range:
	 * doubles land both boosted hits, the claw cascades sit at their
	 * tier-1 cap, the voidwaker's uniform roll caps at 150%. The 1x1
	 * core denies the halberd sweep its second hit - which is exactly
	 * why the DDS dump beats a chally there (field report 2026-08-06). */
	private double coreMaxDamage(DpsResult base, MonsterStats monster)
	{
		int max = base.getMaxHit();
		switch (kind)
		{
			case HALBERD_SWEEP:
				return (monster.getSize() > 1 ? 2.0 : 1.0)
					* (int) (max * damageMultiplier);
			case DOUBLE_INDEPENDENT:
			case LINKED_DOUBLE:
				return 2.0 * (int) (max * damageMultiplier);
			case CLAWS:
				return 2.0 * max; // tier-1 cascade cap (max + halves/quarters)
			case CASCADE_CLAWS:
				return 1.5 * max; // tier-1 cap of the 1.25-mean uniform
			case MULTI_ROLL_TIERED:
				return 1.7 * max; // four successes, top of the k=4 range
			case VOIDWAKER:
				return 1.5 * max;
			case EXTRA_ATTACK:
				return base.getExpectedHit(); // already max via calculate()
			case SINGLE:
			case FIXED_FRACTION:
			default:
				return (int) (max * damageMultiplier);
		}
	}

	/**
	 * Dragon claws cascade: accuracy is rolled up to four times; the tier of
	 * the successful roll sets the damage-roll modifier (100/75/50/25% of
	 * max added to the minimum). Expected totals per tier: 1.5max-1,
	 * 1.25max, max, 0.75max; a full miss averages ~1.
	 */
	private static double clawsExpected(double p, int max)
	{
		double miss = 1 - p;
		return p * (1.5 * max - 1)
			+ miss * p * (1.25 * max)
			+ miss * miss * p * max
			+ miss * miss * miss * p * (0.75 * max)
			+ Math.pow(miss, 4) * 1.0;
	}

	/**
	 * Crimson kisten Brutal Swing: four independent accuracy rolls; with
	 * k >= 1 successes damage is uniform in [(50+20k)%, (90+20k)%] of max
	 * (mean (0.7 + 0.2k) * max); zero successes deal nothing.
	 */
	private static double multiRollTieredExpected(double p, int max)
	{
		// Binomial coefficients C(4, k) for k = 0..4.
		final int[] choose = {1, 4, 6, 4, 1};
		double expected = 0;
		for (int k = 1; k <= 4; k++)
		{
			expected += choose[k] * Math.pow(p, k) * Math.pow(1 - p, 4 - k)
				* (0.7 + 0.2 * k) * max;
		}
		return expected;
	}

	/**
	 * Burning claws cascade: the first successful roll (of up to three)
	 * sets the tier - uniform damage with means 1.25/1.00/0.75 of max; a
	 * full miss deals 0/1/2 with 20/40/40% odds (expected 1.2). The burn
	 * damage-over-time is described in the note, not counted here.
	 */
	private static double cascadeClawsExpected(double p, int max)
	{
		double miss = 1 - p;
		return p * (1.25 * max)
			+ miss * p * (1.00 * max)
			+ miss * miss * p * (0.75 * max)
			+ miss * miss * miss * 1.2;
	}

	/** Dark bow: two hits, each rolled 0..boostedMax then clamped [min, 48]. */
	private static double darkBowExpected(double p, int max, boolean dragonArrows)
	{
		int boosted = (int) (max * (dragonArrows ? 1.5 : 1.3));
		int min = dragonArrows ? 8 : 5;
		double sum = 0;
		for (int d = 0; d <= boosted; d++)
		{
			sum += Math.min(DARK_BOW_CAP, Math.max(min, d));
		}
		return 2 * p * (sum / (boosted + 1));
	}

	private static boolean usesDragonArrows(DpsResult base)
	{
		GearItem ammo = base.getLoadout().get(GearSlot.AMMO);
		return ammo != null && ammo.getNameLower().startsWith("dragon arrow");
	}

	/**
	 * Snapshot max hit ignores prayers and void:
	 * floor(0.5 + (visible ranged + 10) * (ammo ranged str + 64) / 640).
	 */
	private static int snapshotMax(DpsResult base, PlayerLevels levels)
	{
		GearItem ammo = base.getLoadout().get(GearSlot.AMMO);
		int ammoStrength = ammo == null ? 0 : ammo.getBonuses().getRangedStrength();
		return (int) Math.floor(0.5 + (levels.getRanged() + 10) * (ammoStrength + 64) / 640.0);
	}

	/**
	 * Volatile spec max: spell max is min(floor(58 * level / 99) + 1, 58)
	 * - 58 from level 98 up - then the loadout's magic damage bonus
	 * (tenths of a percent) scales it. Wiki anchors: level 84 gives spell
	 * max 50 (57 with the staff's 15% bonus); level 99 gives 58 (66).
	 */
	private static int volatileMax(DpsResult base, PlayerLevels levels)
	{
		int spellMax = Math.min((int) Math.floor(58.0 * levels.getMagic() / 99.0) + 1, 58);
		double gearBonus = 1 + base.getLoadout().getBonuses().getMagicDamage() / 1000.0;
		return (int) Math.floor(spellMax * gearBonus);
	}

	private static double mean(int maxHit)
	{
		return maxHit / 2.0;
	}

	/** Chance this spec lands a damaging hit, from the base result's rolls. */
	public double landChance(DpsResult base)
	{
		if (kind == Kind.VOIDWAKER)
		{
			return 1.0;
		}
		return RollMath.normalAccuracy(
			(long) (base.getAttackRoll() * accuracyMultiplier), base.getDefenceRoll());
	}

	/**
	 * The monster's Defence level after ONE successful use of this spec, or
	 * the unchanged level for non-drain specs. BGS drains by damage dealt.
	 */
	public int drainedDefence(int currentDefence, double specExpectedDamage)
	{
		if (drainsByDamage)
		{
			return Math.max(0, currentDefence - (int) specExpectedDamage);
		}
		if (defenceDrainFraction > 0)
		{
			return currentDefence - (int) (currentDefence * defenceDrainFraction);
		}
		return currentDefence;
	}

	/** Monster-aware drain: the Division spec measures its DEFENCE drain
	 * off the target's MAGIC level, so it shines exactly where a DWH
	 * cannot reach (the wiki's example: Zulrah's 300 Magic). */
	public int drainedDefence(MonsterStats monster, double specExpectedDamage)
	{
		if (magicDrainFraction > 0)
		{
			return Math.max(0, monster.getDefence()
				- (int) (monster.getMagic() * magicDrainFraction));
		}
		return drainedDefence(monster.getDefence(), specExpectedDamage);
	}

	public boolean drainsDefence()
	{
		return drainsByDamage || defenceDrainFraction > 0 || magicDrainFraction > 0;
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.MonsterStats;

/**
 * Tormented Demon mechanics, matching the official calculator's default
 * phase view (verified against weirdgloop's engine 2026-07-05):
 *
 * <ul>
 * <li>Player accuracy is effectively 100% (their shield phases leave them
 *     defenceless to properly-aimed attacks; only the active 'Shielded'
 *     phase resists, which the official calc's default also ignores).</li>
 * <li>They take 20% reduced damage unless hit by a demonbane weapon/spell
 *     or an abyssal weapon (whip, tentacle, dagger, bludgeon).</li>
 * </ul>
 *
 * Not modeled: the Unshielded-phase bonus for crush/heavy/spell attacks.
 */
public final class TormentedDemonRules
{
	private static final String[] ABYSSAL = {
		"abyssal whip", "abyssal tentacle", "abyssal dagger", "abyssal bludgeon",
	};

	private TormentedDemonRules()
	{
	}

	public static boolean applies(MonsterStats monster)
	{
		return monster != null && "Tormented Demon".equalsIgnoreCase(monster.getName());
	}

	/** The flat 20% reduction, bypassed by demonbane and abyssal weapons. */
	public static double damageFactor(MonsterStats monster, CombatStyle style, GearItem weapon, String spellName)
	{
		if (!applies(monster))
		{
			return 1.0;
		}
		return bypassesReduction(style, weapon, spellName) ? 1.0 : 0.8;
	}

	private static boolean bypassesReduction(CombatStyle style, GearItem weapon, String spellName)
	{
		if (style == CombatStyle.MAGIC)
		{
			return spellName != null && spellName.contains("Demonbane");
		}
		// The demonbane weapon vocabulary lives on GearItem (one list with
		// MonsterMechanics and the optimizer's demon bump); a melee name
		// can never be the weapon of a RANGED attack, so one flag serves
		// both remaining styles.
		if (weapon == null)
		{
			return false;
		}
		if (weapon.isDemonbane())
		{
			return true;
		}
		for (String abyssal : ABYSSAL)
		{
			if (weapon.getNameLower().startsWith(abyssal))
			{
				return true;
			}
		}
		return false;
	}
}

package com.loadoutlab.engine;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.StatBlock;
import java.util.*;
import java.util.Map;

/**
 * What dying to another player above level 20 Wilderness costs per worn
 * UNTRADEABLE item, under the June 2026 Items Kept on Death rework
 * (wiki: Trouver parchment + Items Kept on Death, verified 2026-07-07):
 *
 * - Category 1 (no combat benefit): never lost, costs nothing.
 * - Category 2 (some combat bonuses): breaks; the victim pays the item's
 *   own repair/replacement fee (per-item, wiki-sourced). This bucket also
 *   carries the component-drop items (crystal armour reverts to a seed for
 *   the killer, slayer helm drops as a black mask, imbued rings drop the
 *   base ring, ...) priced at the component's value.
 * - Category 3 (strong combat bonuses): trouver-locked once (permanent);
 *   each PvP death above 20 Wilderness mangles the item and the victim
 *   pays 500,000 coins to restore it (the killer receives the fee). We
 *   assume the one-time lock has already been done, so the per-death cost
 *   is the flat 500k mangle fee.
 *
 * Entries in untradeable_death.json are keyed by lowercase item name
 * (GearItem.getName(), no version suffix). An UNLISTED untradeable that
 * carries any combat stats falls back to a conservative 500,000 default:
 * unknowns must not smuggle into "low-risk" sets for free - curation
 * whittles the list, the default keeps the risk budget honest meanwhile.
 * Untradeables with no combat stats (graceful class) cost nothing.
 */
public final class UntradeableDeathCosts
{
	private static final String RESOURCE = "/com/loadoutlab/data/untradeable_death.json";

	/** Conservative fallback for combat untradeables we have not curated. */
	public static final long UNKNOWN_COMBAT_UNTRADEABLE_GP = 500_000L;

	private static final Map<String, Long> COST_BY_NAME = new HashMap<>();
	private static final Map<String, Integer> CATEGORY_BY_NAME = new HashMap<>();
	/** Curated rebuild-errand proxies (re-obtain/re-enchant/re-imbue time,
	 * NOT gp - imbue points refund since April 2024). Counted into the
	 * risk total and the risk cap so "free but a 25-minute errand" items
	 * never read as safe (field request). */
	private static final Map<String, Long> FRICTION_BY_NAME = new HashMap<>();

	static
	{
		JsonObject root = com.loadoutlab.data.JsonResources.object(RESOURCE);
		if (root == null)
		{
			throw new IllegalStateException("Could not load " + RESOURCE);
		}
		{
			for (Map.Entry<String, JsonElement> entry : root.entrySet())
			{
				JsonObject row = entry.getValue().getAsJsonObject();
				String name = entry.getKey().toLowerCase(Locale.ROOT);
				COST_BY_NAME.put(name, row.get("costGp").getAsLong());
				CATEGORY_BY_NAME.put(name, row.get("category").getAsInt());
				if (row.has("frictionGp"))
				{
					FRICTION_BY_NAME.put(name, row.get("frictionGp").getAsLong());
				}
			}
		}
	}

	private UntradeableDeathCosts()
	{
	}

	/**
	 * Per-death gp cost of wearing this item into PvP above 20 Wilderness.
	 * Tradeables cost 0 here - their loss is priced by the kept-slot
	 * ranking in PvpRisk - EXCEPT category 5 (destroyed on any death,
	 * protection does not help), which charges regardless of tradeability.
	 */
	public static long costFor(GearItem item)
	{
		if (item == null)
		{
			return 0L;
		}
		if (item.isTradeable())
		{
			Long destroyed = categoryFor(item) == 5
				? COST_BY_NAME.get(item.getNameLower()) : null;
			return destroyed == null ? 0L : destroyed;
		}
		Long listed = COST_BY_NAME.get(item.getNameLower());
		if (listed != null)
		{
			return listed;
		}
		return hasCombatStats(item) ? UNKNOWN_COMBAT_UNTRADEABLE_GP : 0L;
	}

	/** Rebuild-errand proxy for a death loss (0 when none curated). */
	public static long frictionFor(GearItem item)
	{
		if (item == null)
		{
			return 0L;
		}
		Long friction = FRICTION_BY_NAME.get(item.getNameLower());
		return friction == null ? 0L : friction;
	}

	/** Category 5: destroyed on any death - never protectable. */
	public static boolean isDestroyedOnDeath(GearItem item)
	{
		return categoryFor(item) == 5;
	}

	/**
	 * Category 4: converts to a tradeable component dropped for the
	 * killer (slayer helm -> black mask, crystal -> seed). These are
	 * LOSABLE, so they compete for kept-on-death protection slots at
	 * their component value - protecting one prevents the drop.
	 */
	public static boolean isConvertible(GearItem item)
	{
		return categoryFor(item) == 4;
	}

	/** Curated category (1, 2, 3 or 4-converts), or 0 when unlisted. */
	public static int categoryFor(GearItem item)
	{
		if (item == null)
		{
			return 0;
		}
		Integer listed = CATEGORY_BY_NAME.get(item.getNameLower());
		return listed == null ? 0 : listed;
	}

	private static boolean hasCombatStats(GearItem item)
	{
		return nonZero(item.getOffensive()) || nonZero(item.getDefensive()) || nonZero(item.getBonuses());
	}

	private static boolean nonZero(StatBlock block)
	{
		return block.getStab() != 0 || block.getSlash() != 0 || block.getCrush() != 0
			|| block.getMagic() != 0 || block.getRanged() != 0
			|| block.getStrength() != 0 || block.getRangedStrength() != 0
			|| block.getMagicDamage() != 0 || block.getPrayer() != 0;
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Vampyre tier weapon rules, verified against the OSRS Wiki 2026-07-05:
 * tier 1 ("vampyre1") takes full damage from everything; tier 2
 * ("vampyre2", juvinates) takes HALF damage from non-silver weapons; tier 3
 * ("vampyre3", vyrewatch/sentinels/ancient feral vyres) takes NO damage
 * except from a specific weapon set - so suggesting a whip vs a Vyrewatch
 * Sentinel is not a weaker answer, it is a wrong one.
 *
 * <p>Not modeled: silver bolts making a crossbow effective vs tier 2.
 */
public final class VampyreRules
{
	/** The only weapons that harm tier-3 vampyres (Vyrewatch Sentinel page). */
	private static final String[] TIER3_WEAPONS = weapons("tier3");

	/** Silver weaponry: full damage vs tier 2 (regular weapons deal half). */
	private static final String[] SILVER_WEAPONS = weapons("silver");

	private VampyreRules()
	{
	}

	/** False when this weapon cannot damage the monster at all (tier 3). */
	public static boolean canDamage(MonsterStats monster, GearItem weapon)
	{
		if (monster == null || !monster.hasAttribute("vampyre3"))
		{
			return true;
		}
		return matches(weapon, TIER3_WEAPONS);
	}

	/** Damage scale: 0.5 for non-silver weapons vs tier 2, otherwise 1. */
	public static double damageFactor(MonsterStats monster, GearItem weapon)
	{
		if (monster == null || !monster.hasAttribute("vampyre2") || matches(weapon, SILVER_WEAPONS))
		{
			return 1.0;
		}
		return 0.5;
	}

	private static String[] weapons(String key)
	{
		List<String> names = new ArrayList<>();
		JsonResources.strings(JsonResources.objectOrThrow("vampyre_weapons.json"), key, names);
		return names.toArray(new String[0]);
	}

	private static boolean matches(GearItem weapon, String[] prefixes)
	{
		if (weapon == null)
		{
			return false;
		}
		String name = weapon.getNameLower();
		for (String prefix : prefixes)
		{
			if (name.startsWith(prefix))
			{
				return true;
			}
		}
		return false;
	}
}

package com.loadoutlab.engine;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.JsonResources;
import java.util.*;
import java.util.List;
import java.util.Map;

/**
 * Melee combat styles available per weapon category - game facts from the
 * wiki's weapon-type pages (cross-checked against the official calculator,
 * 2026-07-05). The upstream best-dps engine assumed every melee weapon has
 * every attack type at every stance, which invented styles weapons don't
 * have: a whip has no aggressive stance, and a Blunt weapon cannot slash -
 * that one let a barronite mace "slash" a Grey golem (slash defence 1,
 * everything else 300) for a 3x accuracy error against the official calc.
 *
 * <p>Stances: accurate = +3 attack, aggressive = +3 strength,
 * controlled = +1 both. Defensive is omitted - it adds no offence, so it
 * can never be the best-DPS pick.
 *
 * <p>The table itself lives in weapon_styles.json (hub token cap: data goes
 * in resources, not source). It is GENERATED from the old hardcoded table by
 * scripts/extract_weapon_styles.py, which asserts 24 categories, 56 style
 * entries and the 9-entry fallback row - regenerate with that script, never
 * by hand.
 */
public final class WeaponStyles
{
	/** One selectable style: the attack type plus its stance bonuses. */
	public static final class MeleeStyle
	{
		public final String attackType;
		public final int attackStance;
		public final int strengthStance;

		MeleeStyle(String attackType, int attackStance, int strengthStance)
		{
			this.attackType = attackType;
			this.attackStance = attackStance;
			this.strengthStance = strengthStance;
		}
	}

	private static final String RESOURCE = "/com/loadoutlab/data/weapon_styles.json";
	/** Resource key of the unknown-category fallback row - not a real weapon
	 * category, so it can never collide with one. */
	private static final String FALLBACK = "*";

	private static final Map<String, List<MeleeStyle>> BY_CATEGORY = load();

	/** Every attack type x stance a full search would try - the fallback. */
	private static final List<MeleeStyle> ALL =
		BY_CATEGORY.getOrDefault(FALLBACK, Collections.emptyList());

	private static Map<String, List<MeleeStyle>> load()
	{
		Map<String, List<MeleeStyle>> table = new HashMap<>();
		JsonObject root = JsonResources.object(RESOURCE);
		if (root == null)
		{
			return table;
		}
		for (Map.Entry<String, JsonElement> entry : root.entrySet())
		{
			List<MeleeStyle> styles = new ArrayList<>();
			for (JsonElement element : entry.getValue().getAsJsonArray())
			{
				JsonObject style = element.getAsJsonObject();
				styles.add(new MeleeStyle(style.get("attackType").getAsString(),
					style.get("attackStance").getAsInt(),
					style.get("strengthStance").getAsInt()));
			}
			table.put(entry.getKey(), Collections.unmodifiableList(styles));
		}
		return table;
	}

	private WeaponStyles()
	{
	}

	/** The melee styles this weapon actually offers (unknown category: all). */
	public static List<MeleeStyle> melee(GearItem weapon)
	{
		// Null weapon = bare fists, which is a real category row. Looking it up
		// through the same map (rather than returning it directly) is what
		// keeps a missing resource from returning null here and NPE-ing
		// DpsCalculator: an absent row falls back to ALL, and ALL itself
		// defaults to an empty list.
		List<MeleeStyle> styles = BY_CATEGORY.get(
			weapon == null ? "Unarmed" : weapon.getCategory());
		return styles != null ? styles : ALL;
	}
}

