		{
			JPopupMenu menu = new JPopupMenu();
			JPanel rack = Ui.darker(new GridLayout(0, 4, 2, 2));
			rack.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
			for (NavalCombat.Cannon option
				: NavalCombat.cannons())
			{
