package com.loadoutlab.render;

import java.awt.Component;
import java.awt.Graphics;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.imageio.ImageIO;
import javax.swing.Icon;

/** The classic stat icons, baked from the original painted art (see git
 * history for the painters): the hitsplat for max hit, the crosshair for
 * accuracy, and the fixed-width wrapper that gives every stat line one
 * hard left edge. */
final class StatIcons
{
	private StatIcons()
	{
	}

	/** Baked images by resource name. A missing or unreadable resource
	 * caches a fully transparent placeholder so paint degrades to blank -
	 * it never throws inside a Swing paint pass. */
	private static final Map<String, BufferedImage> BAKED = new ConcurrentHashMap<>();

	private static BufferedImage baked(String name, int size)
	{
		return BAKED.computeIfAbsent(name, n ->
		{
			try (InputStream in = StatIcons.class.getResourceAsStream(n))
			{
				if (in != null)
				{
					BufferedImage img = ImageIO.read(in);
					if (img != null)
					{
						return img;
					}
				}
			}
			catch (IOException ignored)
			{
				// fall through to the transparent placeholder
			}
			return new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		});
	}

	/**
	 * Shared shape for the square baked icons: a single pixel size used as
	 * both width and height, drawn from a PNG baked at exactly that size
	 * from the original paint code.
	 */
	abstract static class SizedIcon implements Icon
	{
		/** Icon edge length in pixels. */
		private final int size;
		private final BufferedImage image;

		SizedIcon(String bakedName, int size)
		{
			this.size = size;
			this.image = baked("stat-" + bakedName + "-" + size + ".png", size);
		}

		@Override
		public int getIconWidth()
		{
			return size;
		}

		@Override
		public int getIconHeight()
		{
			return size;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			g.drawImage(image, x, y, size, size, null);
		}
	}


	/** The baked crosshair for the accuracy line (glyph-safe). */
	static final class CrosshairIcon extends SizedIcon
	{
		CrosshairIcon(int size)
		{
			super("crosshair", size);
		}
	}


	/** The baked red hitsplat for the max-hit line (glyph-safe). */
	static final class HitsplatIcon extends SizedIcon
	{
		HitsplatIcon(int size)
		{
			super("hitsplat", size);
		}
	}


	/** A fixed-width box that centres its delegate - every stat-panel
	 * line's icon occupies the SAME column width, so the values start on
	 * one hard left edge (field spec: a strong visual column). */
	static final class FixedWidthIcon implements Icon
	{
		static final int WIDTH = 20;
		static final int HEIGHT = 16;
		final Icon delegate;

		FixedWidthIcon(Icon delegate)
		{
			this.delegate = delegate;
		}

		@Override
		public int getIconWidth()
		{
			return WIDTH;
		}

		@Override
		public int getIconHeight()
		{
			return Math.max(HEIGHT, delegate.getIconHeight());
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			delegate.paintIcon(c,
				g,
				x + Math.max(0, (WIDTH - delegate.getIconWidth()) / 2),
				y + Math.max(0, (getIconHeight() - delegate.getIconHeight()) / 2));
		}
	}

}

package com.loadoutlab.render;

import java.awt.*;
import javax.swing.*;
import net.runelite.client.ui.ColorScheme;
import java.awt.image.BufferedImage;

/**
 * The shared UI kit (merge-back dedupe): the handful of Swing recipes
 * the surface repeats everywhere, factored once. Helpers are exact
 * equivalents of the inline forms they replace - same properties in
 * the same order - so the look cannot drift.
 */
final class Ui
{
	private Ui()
	{
	}

	/** A panel on the standard dark ground. */
	static JPanel panel(LayoutManager layout)
	{
		JPanel panel = new JPanel(layout);
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return panel;
	}

	/** A panel on the darker inset ground. */
	static JPanel darker(LayoutManager layout)
	{
		JPanel panel = new JPanel(layout);
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		return panel;
	}

	/** A label with a fixed foreground. */
	static JLabel label(String text, Color fg)
	{
		JLabel label = new JLabel(text);
		label.setForeground(fg);
		return label;
	}

	/** Hand cursor + a click action (the classic clickable label). */
	static void onClick(Component component, Runnable action)
	{
		component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		component.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseClicked(java.awt.event.MouseEvent e)
			{
				action.run();
			}
		});
	}

	/** A square smooth-scaled icon. */
	static ImageIcon icon(Image image, int size)
	{
		return new ImageIcon(image.getScaledInstance(size, size, Image.SCALE_SMOOTH));
	}

	/** The image scaled to size, dimmed, with a red X painted over it - the
	 * "none picked" sentinel (Andrew 2026-09-01: a plain prayer book read as
	 * a prayer being ON). Drawn graphics, so the ASCII glyph gate is not in
	 * play. */
	static ImageIcon crossedOut(Image image, int size)
	{
		BufferedImage out = new BufferedImage(
			size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			RenderingHints.VALUE_ANTIALIAS_ON);
		// The base icon, dimmed so the X reads as the foreground.
		Composite base = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(
			AlphaComposite.SRC_OVER, 0.55f));
		g.drawImage(image, 0, 0, size, size, null);
		g.setComposite(base);
		int m = Math.max(2, size / 6);
		g.setStroke(new BasicStroke(Math.max(2f, size / 9f),
			BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(new Color(210, 70, 70));
		g.drawLine(m, m, size - m, size - m);
		g.drawLine(size - m, m, m, size - m);
		g.dispose();
		return new ImageIcon(out);
	}

	/** A menu item wired to an action, added to the menu. */
	static void item(JPopupMenu menu, String label, Runnable action)
	{
		JMenuItem item = new JMenuItem(label);
		item.addActionListener(e -> action.run());
		menu.add(item);
	}

	/** A tooltip body wrapped for Swing's html renderer. Six builders
	 * each wrote their own wrapper; this is the one. */
	static String tip(String... parts)
	{
		StringBuilder out = new StringBuilder("<html>");
		for (String part : parts)
		{
			out.append(part);
		}
		return out.append("</html>").toString();
	}

	/** A heading over one item per line - the shape the risk and
	 * counted-bonus tips each hand-rolled. The house rule: a breakdown
	 * is a list and numbers, never prose. */
	static String list(String heading, Iterable<?> items)
	{
		StringBuilder out = new StringBuilder(heading);
		for (Object item : items)
		{
			out.append("<br> ").append(item);
		}
		return out.toString();
	}

	/** The reconciliation ledger BOTH dps tooltips wear (field ask
	 * 2026-08-21: "less dense and more informative") - one fact per row:
	 * the bare SET the wiki calculator shows, the parts we fold on top,
	 * and the total the card prints. The two call sites differ only in
	 * the set row's note and in whether a zero spec row still shows, so
	 * both ride parameters - the table markup itself lives once.
	 * Returns the table only; callers own the surrounding html. */
	static String ledger(double set, String setNote, double specDps, boolean showSpec,
		double thrallsDps)
	{
		StringBuilder sum = new StringBuilder();
		sum.append("<table cellpadding='1' cellspacing='0'>")
			.append("<tr><td>set</td><td align='right'>&nbsp;&nbsp;")
			.append(String.format("%.3f", set))
			.append("</td><td><font color='#969696'>&nbsp;&nbsp;").append(setNote)
			.append("</font></td></tr>");
		if (showSpec)
		{
			sum.append("<tr><td>+ spec</td><td align='right'>&nbsp;&nbsp;")
				.append(String.format("%.2f", specDps)).append("</td><td></td></tr>");
		}
		if (thrallsDps > 0)
		{
			sum.append("<tr><td>+ thralls</td><td align='right'>&nbsp;&nbsp;")
				.append(String.format("%.2f", thrallsDps)).append("</td><td></td></tr>");
		}
		return sum.append("<tr><td><b>= shown here</b></td><td align='right'>&nbsp;&nbsp;<b>")
			.append(String.format("%.2f", set + specDps + thrallsDps))
			.append("</b></td><td></td></tr></table>").toString();
	}
}

package com.loadoutlab.render;

import java.awt.*;

/** The classic chip-row layout (ported verbatim): FlowLayout that
 * actually wraps, so no control silently clips off the row's end. */
final class WrapLayout extends FlowLayout
{
	WrapLayout(int align, int hgap, int vgap)
	{
		super(align, hgap, vgap);
	}

	@Override
	public Dimension preferredLayoutSize(Container target)
	{
		synchronized (target.getTreeLock())
		{
			// A fresh card has no width yet - falling back to unlimited
			// meant one endless row, clipped after a few chips (field
			// bug: parameters "disappearing" mid-compute). Assume the
			// plugin panel's width until the real one exists.
			int targetWidth = target.getWidth() > 0 ? target.getWidth()
				: (target.getParent() != null && target.getParent().getWidth() > 0
					? target.getParent().getWidth() : 220);
			Insets insets = target.getInsets();
			int maxWidth = targetWidth - insets.left - insets.right - getHgap() * 2;
			int x = 0;
			int rowHeight = 0;
			Dimension dim = new Dimension(0, insets.top + getVgap());
			for (int i = 0; i < target.getComponentCount(); i++)
			{
				Component c = target.getComponent(i);
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				if (x == 0 || x + getHgap() + d.width <= maxWidth)
				{
					x += (x > 0 ? getHgap() : 0) + d.width;
					rowHeight = Math.max(rowHeight, d.height);
				}
				else
				{
					dim.width = Math.max(dim.width, x);
					dim.height += rowHeight + getVgap();
					x = d.width;
					rowHeight = d.height;
				}
			}
			dim.width = Math.max(dim.width, x) + insets.left + insets.right + getHgap() * 2;
			dim.height += rowHeight + getVgap() + insets.bottom;
			return dim;
		}
	}
}

package com.loadoutlab.ui;

import java.awt.*;
import java.util.Set;
import java.util.function.Supplier;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * "Show in bank": outlines the active set's items in the bank (and the
 * bank-side inventory) so gearing up is a visual scan, not a search.
 * The id set is pre-expanded with variants (whip (or) glows when the
 * set says whip); null/empty means off.
 */
public class BankHighlightOverlay extends WidgetItemOverlay
{
	private static final Color GLOW = new Color(140, 200, 140);
	private static final Color FILL = new Color(140, 200, 140, 40);

	private final Supplier<Set<Integer>> highlighted;

	public BankHighlightOverlay(Supplier<Set<Integer>> highlighted)
	{
		this.highlighted = highlighted;
		showOnBank();
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		Set<Integer> ids = highlighted.get();
		if (ids == null || !ids.contains(itemId))
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		graphics.setColor(FILL);
		graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 6, 6);
		graphics.setColor(GLOW);
		graphics.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 6, 6);
	}
}

