package com.loadoutlab;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.DpsResult;
import com.loadoutlab.engine.LoadoutOptimizer;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerBonuses;
import com.loadoutlab.engine.TestRequests;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The wiki-calc shortlink payload must speak osrs-dps-calc's
 * ImportableData shape exactly (verified against their source,
 * IMPORT_VERSION 10): serializationVersion, one loadout with skills /
 * boost deltas / {id} equipment / prayer+potion enum ordinals, and a
 * monster resolved by id with mergeable inputs.
 */
class WikiCalcLinkTest
{
	private static LoadoutData data;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
	}

	@SuppressWarnings("unchecked")
	@Test
	@DisplayName("a melee result maps to their document: version 10, ids, enums, deltas")
	void meleePayloadShape()
	{
		MonsterStats monster = data.searchMonsters("general graardor", 1).get(0);
		OptimizationRequest request = TestRequests.of(monster, CombatStyle.MELEE,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null,
			0, com.loadoutlab.engine.CandidateMode.ALL_STANDARD, false, false,
			OwnedItems.EMPTY, 1);
		DpsResult best = new LoadoutOptimizer().optimize(data, request).get(0);

		Map<String, Object> payload = WikiCalcLink.payload(monster, best, -1,
			"Piety + Divine super combat", PlayerLevels.MAXED, PlayerLevels.MAXED,
			true, false);

		assertEquals(10, payload.get("serializationVersion"));
		// The document must survive gson under the JDK module system - the
		// private Collections$*/List.of types throw InaccessibleObjectException
		// (field bug 2026-07-23: the button silently died on serialize).
		assertDoesNotThrow(() -> new com.google.gson.Gson().toJson(payload));
		Map<String, Object> monsterDoc = (Map<String, Object>) payload.get("monster");
		assertEquals(monster.getId(), monsterDoc.get("id"));
		assertNotNull(((Map<String, Object>) monsterDoc.get("inputs")).get("defenceReductions"),
			"their import iterates defenceReductions - it must exist");

		Map<String, Object> loadout =
			((List<Map<String, Object>>) payload.get("loadouts")).get(0);
		assertEquals(List.of(13), loadout.get("prayers"), "Piety = their ordinal 13");
		Map<String, Object> buffs = (Map<String, Object>) loadout.get("buffs");
		assertEquals(List.of(14), buffs.get("potions"),
			"divine super combat maps to their SUPER_COMBAT (no divine entry)");
		assertEquals(true, buffs.get("onSlayerTask"));

		Map<String, Integer> boosts = (Map<String, Integer>) loadout.get("boosts");
		assertEquals(19, boosts.get("atk"), "super combat at 99: floor(5 + 99*0.15)");
		assertEquals(0, boosts.get("ranged"));

		Map<String, Object> equipment = (Map<String, Object>) loadout.get("equipment");
		assertTrue(equipment.containsKey("weapon"));
		int weaponId = (Integer)
			((Map<String, Object>) equipment.get("weapon")).get("id");
		assertEquals(best.getLoadout().getWeapon().getId(), weaponId);

		// The one multi-ordinal row - pins the JSON array parse in
		// wiki_calc_ids.json's potionIds.
		Map<String, Object> twoPotions = WikiCalcLink.payload(monster, best, -1,
			"Attack & strength potions", PlayerLevels.MAXED, PlayerLevels.MAXED,
			false, false);
		Map<String, Object> twoLoadout =
			((List<Map<String, Object>>) twoPotions.get("loadouts")).get(0);
		assertEquals(List.of(1, 10),
			((Map<String, Object>) twoLoadout.get("buffs")).get("potions"),
			"attack & strength potions = their ordinals 1 and 10");
	}

	@SuppressWarnings("unchecked")
	@Test
	@DisplayName("the blowpipe's dart rides the weapon's itemVars, never the ammo slot")
	void blowpipeDartRidesItemVars()
	{
		// Their harness note (2026-08-06): an ammo-slot dart is a
		// hand-thrown weapon; field report 2026-08-21: the cow payload
		// carried a dartless blowpipe (the blessing owns the ammo slot).
		MonsterStats monster = data.searchMonsters("cow", 1).get(0);
		OptimizationRequest request = TestRequests.of(monster, CombatStyle.RANGED,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null,
			0, com.loadoutlab.engine.CandidateMode.ALL_STANDARD, false, false,
			OwnedItems.EMPTY, 1);
		DpsResult best = new LoadoutOptimizer().optimize(data, request).get(0);

		int dragonDart = 11230;
		Map<String, Object> payload = WikiCalcLink.payload(monster, best, dragonDart,
			"Rigour + Divine ranging potion", PlayerLevels.MAXED, PlayerLevels.MAXED,
			false, false);
		Map<String, Object> equipment = (Map<String, Object>)
			((List<Map<String, Object>>) payload.get("loadouts")).get(0).get("equipment");
		Map<String, Object> weapon = (Map<String, Object>) equipment.get("weapon");
		Map<String, Object> vars = (Map<String, Object>) weapon.get("itemVars");
		assertNotNull(vars, "the dart travels on the weapon");
		assertEquals(dragonDart, vars.get("blowpipeDartId"));
		Map<String, Object> ammo = (Map<String, Object>) equipment.get("ammo");
		if (ammo != null)
		{
			assertNotEquals(dragonDart, ammo.get("id"),
				"the ammo slot never carries the dart");
		}
	}

	@SuppressWarnings("unchecked")
	@Test
	@DisplayName("a powered staff exports Accurate - their category has no Autocast")
	void poweredStaffCastsAccurate()
	{
		// Field report 2026-08-21: trident vs cow opened at 5 ticks
		// (Longrange fallback) - exactly 4/5 of our dps. A powered
		// staff's attackType wears the autocast prefix but carries no
		// spell name; the payload must land stance Accurate.
		MonsterStats monster = data.searchMonsters("cow", 1).get(0);
		OptimizationRequest request = TestRequests.of(monster, CombatStyle.MAGIC,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null,
			0, com.loadoutlab.engine.CandidateMode.ALL_STANDARD, false, false,
			OwnedItems.EMPTY, 1);
		DpsResult best = new LoadoutOptimizer().optimize(data, request).get(0);
		assertTrue(best.getSpellName() == null || best.getSpellName().isEmpty(),
			"the magic best vs a cow is a powered staff (no spell)");

		Map<String, Object> payload = WikiCalcLink.payload(monster, best, -1,
			"Augury + Saturated heart", PlayerLevels.MAXED, PlayerLevels.MAXED,
			false, false);
		Map<String, String> style = (Map<String, String>)
			((List<Map<String, Object>>) payload.get("loadouts")).get(0).get("style");
		assertEquals("magic", style.get("type"));
		assertEquals("Accurate", style.get("stance"));
	}

	@Test
	@DisplayName("the monster travels under its RAW wiki version")
	void monsterCarriesTheWikiVersion()
	{
		// The everyday Duke displays version '' but the official data
		// keys 'Post-quest, Awake' - a display version makes their
		// import fall back to the Awakened row (field 2026-08-21).
		MonsterStats duke = data.searchMonsters("duke sucellus", 1).get(0);
		assertEquals("", duke.getVersion(), "display stays clean");
		assertEquals("Post-quest, Awake", duke.getWikiVersion());
		OptimizationRequest request = TestRequests.of(duke, CombatStyle.MELEE,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null,
			0, com.loadoutlab.engine.CandidateMode.ALL_STANDARD, false, false,
			OwnedItems.EMPTY, 1);
		DpsResult best = new LoadoutOptimizer().optimize(data, request).get(0);
		Map<String, Object> payload = WikiCalcLink.payload(duke, best, -1,
			"Piety + Divine super combat", PlayerLevels.MAXED, PlayerLevels.MAXED,
			false, false);
		Map<String, Object> monsterDoc =
			(Map<String, Object>) payload.get("monster");
		assertEquals("Post-quest, Awake", monsterDoc.get("version"));
	}

	@Test
	@DisplayName("attack-type strings map to their {type, stance} pairs")
	void styleMapping()
	{
		assertEquals(Map.of("type", "slash", "stance", "Aggressive"),
			WikiCalcLink.styleOf("slash (aggressive)"));
		assertEquals(Map.of("type", "stab", "stance", "Controlled"),
			WikiCalcLink.styleOf("stab (controlled)"));
		assertEquals(Map.of("type", "ranged", "stance", "Rapid"),
			WikiCalcLink.styleOf("ranged rapid - dragon dart"));
		assertEquals(Map.of("type", "magic", "stance", "Autocast"),
			WikiCalcLink.styleOf("magic: Fire Surge"));
		assertEquals(Map.of("type", "magic", "stance", "Accurate"),
			WikiCalcLink.styleOf("magic"));
		assertNull(WikiCalcLink.styleOf(null));
	}

	@Test
	@DisplayName("the payload carries the invocation and maps synthetic ids to real rows")
	void invocationAndSyntheticIds()
	{
		MonsterStats warden = data.searchMonsters("tumeken's warden", 8).stream()
			.filter(m -> "Enraged".equals(m.getVersion()))
			.findFirst().orElseThrow();
		MonsterStats at300 = warden.withToaInvocation(300);
		OptimizationRequest request = TestRequests.of(at300, CombatStyle.RANGED,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED),
			null, 0, com.loadoutlab.engine.CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, 1);
		DpsResult best = new LoadoutOptimizer().optimize(data, request).get(0);

		Map<String, Object> payload = WikiCalcLink.payload(at300, best, -1,
			"Rigour + Divine ranging potion", PlayerLevels.MAXED, PlayerLevels.MAXED,
			false, false);
		@SuppressWarnings("unchecked")
		Map<String, Object> monsterDoc = (Map<String, Object>) payload.get("monster");
		@SuppressWarnings("unchecked")
		Map<String, Object> inputs = (Map<String, Object>) monsterDoc.get("inputs");
		assertEquals(300, inputs.get("toaInvocationLevel"),
			"the calculator must open at the card's raid level");

		// A synthetic group phase exports its REAL id - the calc only
		// knows real rows.
		MonsterStats synthetic = warden.immuneVariant(
			com.loadoutlab.data.MonsterStats.SYNTHETIC_ID_BASE + warden.getId() * 10 + 1,
			"P2 (test)", "immune_melee");
		Map<String, Object> syntheticPayload = WikiCalcLink.payload(synthetic, best, -1,
			"Rigour", PlayerLevels.MAXED, PlayerLevels.MAXED, false, false);
		@SuppressWarnings("unchecked")
		Map<String, Object> syntheticDoc = (Map<String, Object>) syntheticPayload.get("monster");
		assertEquals(warden.getId(), syntheticDoc.get("id"));
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.loadoutlab.testsupport.InMemoryConfigManager;
import java.util.Map;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class AlwaysFilterStoreTest
{
	private static final String SCOPE = "std.1111";
	private ConfigManager configManager;
	private AlwaysFilterStore store;

	@BeforeEach
	void setUp()
	{
		configManager = InMemoryConfigManager.create();
		store = freshStore();
	}

	/** The plugin always loads a character scope before use; a store
	 * without one writes to the pre-0.4.1 unscoped key, so a reload
	 * through a second instance would read a different key entirely. */
	private AlwaysFilterStore freshStore()
	{
		AlwaysFilterStore fresh = new AlwaysFilterStore(configManager, new Gson());
		fresh.loadScope(SCOPE);
		return fresh;
	}

	@Test
	@DisplayName("always-filter items persist with their add-time names and survive a reload")
	void itemsPersistAcrossReload()
	{
		store.add(9790, "Construction cape");
		store.add(13280, "Max cape");
		assertEquals(Map.of(9790, "Construction cape", 13280, "Max cape"), store.all());

		AlwaysFilterStore reloaded = freshStore();
		assertEquals("Construction cape", reloaded.all().get(9790),
			"the list survives a config round-trip");
	}

	@Test
	@DisplayName("removing the last item unsets the config key entirely")
	void emptyListUnsetsConfig()
	{
		store.add(9790, "Construction cape");
		store.remove(9790);
		assertTrue(store.all().isEmpty());
		assertNull(configManager.getConfiguration("loadoutlab", SCOPE + ".alwaysFilterItems"),
			"an empty list leaves no config residue");
	}

	@Test
	@DisplayName("a null add-time name falls back to the item id")
	void nullNameFallsBack()
	{
		store.add(1234, null);
		assertEquals("item 1234", store.all().get(1234));
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.loadoutlab.testsupport.InMemoryConfigManager;
import java.util.Map;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class CollectionLedgerTest
{
	private ConfigManager configManager;
	private CollectionLedger ledger;

	@BeforeEach
	void setUp()
	{
		configManager = InMemoryConfigManager.create();
		ledger = new CollectionLedger(configManager, new Gson());
		ledger.loadScope("std");
	}

	@Test
	@DisplayName("the merged view sums quantities across equipment, inventory, and bank")
	void mergeSumsAcrossSources()
	{
		ledger.update(CollectionLedger.Source.BANK, Map.of(4151, 1, 861, 2));
		ledger.update(CollectionLedger.Source.INVENTORY, Map.of(861, 1));
		ledger.update(CollectionLedger.Source.EQUIPMENT, Map.of(11832, 1));

		Map<Integer, Integer> owned = ledger.owned();
		assertEquals(1, owned.get(4151));
		assertEquals(3, owned.get(861));
		assertEquals(1, owned.get(11832));
	}

	@Test
	@DisplayName("the ledger survives a new session - bank from LAST visit still counts")
	void persistsAcrossInstances()
	{
		ledger.update(CollectionLedger.Source.BANK, Map.of(20997, 1));

		// A fresh instance on the same backing store stands in for the next
		// session: no bank visit yet, but ownership is already known.
		CollectionLedger next = new CollectionLedger(configManager, new Gson());
		next.loadScope("std");
		assertEquals(1, next.owned().get(20997));
		assertTrue(next.bankKnown());
	}

	@Test
	@DisplayName("a seasonal-world login never touches the standard ledger")
	void worldScopesAreIsolated()
	{
		ledger.update(CollectionLedger.Source.BANK, Map.of(4151, 1));

		ledger.loadScope("seasonal");
		assertTrue(ledger.owned().isEmpty(), "seasonal scope starts empty");
		ledger.update(CollectionLedger.Source.BANK, Map.of(995, 1_000_000));

		ledger.loadScope("std");
		assertEquals(1, ledger.owned().get(4151));
		assertNull(ledger.owned().get(995), "leagues gold must not leak into the main ledger");
	}

	@Test
	@DisplayName("an unchanged snapshot neither rewrites config nor changes the fingerprint")
	void unchangedSnapshotIsANoOp()
	{
		assertTrue(ledger.update(CollectionLedger.Source.INVENTORY, Map.of(4151, 1)));
		int fp = ledger.fingerprint();

		clearInvocations(configManager);
		assertFalse(ledger.update(CollectionLedger.Source.INVENTORY, Map.of(4151, 1)));
		assertEquals(fp, ledger.fingerprint());
		verify(configManager, never()).setConfiguration(anyString(), anyString(), anyString());
	}

	@Test
	@DisplayName("the fingerprint changes when ownership actually changes")
	void fingerprintTracksOwnership()
	{
		ledger.update(CollectionLedger.Source.BANK, Map.of(4151, 1));
		int before = ledger.fingerprint();
		ledger.update(CollectionLedger.Source.BANK, Map.of(4151, 1, 11802, 1));
		assertNotEquals(before, ledger.fingerprint());
	}

	@Test
	@DisplayName("a corrupt persisted entry starts that snapshot fresh instead of failing")
	void corruptEntryDegradesGracefully()
	{
		configManager.setConfiguration(CollectionLedger.CONFIG_GROUP, "std.collection.bank", "{not json!");
		CollectionLedger fresh = new CollectionLedger(configManager, new Gson());
		fresh.loadScope("std");
		assertTrue(fresh.owned().isEmpty());
		assertFalse(fresh.bankKnown());
	}

	@Test
	@DisplayName("the looting bag is a ledger source: its contents count as owned and persist")
	void lootingBagCountsAndPersists()
	{
		ledger.update(CollectionLedger.Source.LOOTING_BAG, Map.of(2434, 3));
		assertEquals(3, ledger.owned().get(2434));

		CollectionLedger next = new CollectionLedger(configManager, new Gson());
		next.loadScope("std");
		assertEquals(3, next.owned().get(2434));
		assertFalse(next.bankKnown(), "a looting bag scan alone is not a bank scan");
	}

	@Test
	@DisplayName("the storage sources (POH, STASH, cargo) merge into owned and persist independently")
	void storageSourcesMergeAndPersist()
	{
		ledger.update(CollectionLedger.Source.POH_COSTUMES, Map.of(11832, 1));
		ledger.update(CollectionLedger.Source.STASH, Map.of(4151, 1));
		ledger.update(CollectionLedger.Source.CARGO_HOLD_1, Map.of(2, 5000));

		CollectionLedger next = new CollectionLedger(configManager, new Gson());
		next.loadScope("std");
		assertEquals(1, next.owned().get(11832));
		assertEquals(1, next.owned().get(4151));
		assertEquals(5000, next.owned().get(2));
		assertFalse(next.bankKnown());

		// Emptying a STASH via a fresh chart read removes only its items.
		next.update(CollectionLedger.Source.STASH, Map.of());
		assertNull(next.owned().get(4151));
		assertEquals(1, next.owned().get(11832));
	}

	@org.junit.jupiter.api.Test
	void accountScopesNeverShareAndLegacyDataIsAdoptedOnce()
	{
		com.google.gson.Gson gson = new com.google.gson.Gson();
		CollectionLedger ledger = new CollectionLedger(configManager, gson);
		// Legacy pre-account data saved under the bare world scope.
		ledger.loadScope("std");
		ledger.update(CollectionLedger.Source.BANK, java.util.Map.of(4151, 1));
		// Account A adopts the legacy bank on first load...
		ledger.loadScope("std.1111");
		org.junit.jupiter.api.Assertions.assertTrue(ledger.owned().containsKey(4151));
		// ...and its own writes stay isolated from account B.
		ledger.update(CollectionLedger.Source.BANK, java.util.Map.of(20997, 1));
		ledger.loadScope("std.2222");
		org.junit.jupiter.api.Assertions.assertFalse(ledger.owned().containsKey(20997));
		// B adopts NOTHING: A already took the legacy scan, and the entry was
		// removed with it. Letting every account adopt it (the original
		// reading of "once") is what showed a test account the main's bank
		// and priced its BiS off gear it does not own - field report
		// 2026-08-26. An empty ledger until B scans is the honest state.
		org.junit.jupiter.api.Assertions.assertFalse(ledger.owned().containsKey(4151));
		// Back to A: the tbow is still there.
		ledger.loadScope("std.1111");
		org.junit.jupiter.api.Assertions.assertTrue(ledger.owned().containsKey(20997));
	}

	@org.junit.jupiter.api.Test
	void perSourceSnapshotsAreReadableAndReadOnly()
	{
		CollectionLedger ledger = new CollectionLedger(configManager, new Gson());
		ledger.loadScope("std");
		ledger.update(CollectionLedger.Source.BANK, Map.of(4151, 1));

		assertEquals(Map.of(4151, 1), ledger.snapshot(CollectionLedger.Source.BANK));
		assertEquals(Map.of(), ledger.snapshot(CollectionLedger.Source.STASH));
		org.junit.jupiter.api.Assertions.assertThrows(UnsupportedOperationException.class,
			() -> ledger.snapshot(CollectionLedger.Source.BANK).put(1, 1));
	}
}

package com.loadoutlab.collection;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class DwmsLinkTest
{
	/** A well-formed version-1 response payload, as DWMS builds it. */
	private static Map<String, Object> response(Object storages)
	{
		Map<String, Object> data = new HashMap<>();
		data.put("source", "Dude, Where's My Stuff?");
		data.put("target", "Loadout Lab");
		data.put("version", 1);
		data.put("storages", storages);
		return data;
	}

	private static Map<String, Object> storage(String category, String name, Object items)
	{
		Map<String, Object> data = new HashMap<>();
		data.put("category", category);
		data.put("name", name);
		data.put("lastUpdated", 1720549342765L);
		data.put("items", items);
		return data;
	}

	private static Map<String, Object> item(Object id, Object quantity)
	{
		Map<String, Object> data = new HashMap<>();
		data.put("id", id);
		data.put("quantity", quantity);
		return data;
	}

	@Test
	@DisplayName("families group items by response category for the location hints")
	void familiesGroupByCategory()
	{
		DwmsLink link = new DwmsLink();
		assertTrue(link.accept(response(List.of(
			storage("stash", "Hosidius STASH", List.of(item(11864, 1))),
			storage("stash", "Falador STASH", List.of(item(11864, 1))),
			storage("death", "Grave", List.of(item(4151, 1)))))));
		assertEquals(Map.of(11864, 2), link.families().get("stash"),
			"same-category storages merge");
		assertEquals(Map.of(4151, 1), link.families().get("death"));
		assertEquals(2, link.families().size());
		link.reset();
		assertTrue(link.families().isEmpty(), "reset drops the families too");
	}

	@Test
	@DisplayName("a well-formed response goes live, merging duplicate items across storages")
	void wellFormedResponseParses()
	{
		DwmsLink link = new DwmsLink();
		assertFalse(link.isLive(), "not live before the first response");

		assertTrue(link.accept(response(List.of(
			storage("stash", "STASH Units", List.of(item(4151, 1L), item(995, 100L))),
			storage("poh", "Armour Case", List.of(item(4151, 2L)))))));

		assertTrue(link.isLive());
		assertEquals(2, link.count());
		assertEquals(3, link.snapshot().get(4151), "same item across storages sums");
		assertEquals(100, link.snapshot().get(995));
	}

	@Test
	@DisplayName("responses addressed to another plugin are ignored")
	void otherTargetsAreIgnored()
	{
		DwmsLink link = new DwmsLink();
		Map<String, Object> data = response(List.of(storage("stash", "STASH Units",
			List.of(item(4151, 1L)))));
		data.put("target", "Bank Memory");

		assertFalse(link.accept(data));
		assertFalse(link.isLive());
		assertTrue(link.snapshot().isEmpty());
	}

	@Test
	@DisplayName("an unknown contract version is rejected, leaving the config-read fallback in charge")
	void unknownVersionIsRejected()
	{
		DwmsLink link = new DwmsLink();
		Map<String, Object> data = response(List.of(storage("stash", "STASH Units",
			List.of(item(4151, 1L)))));
		data.put("version", 2);

		assertFalse(link.accept(data));
		assertFalse(link.isLive());
	}

	@Test
	@DisplayName("malformed payloads and entries are dropped, never guessed at")
	void defensiveParsingDropsMalformedEntries()
	{
		DwmsLink link = new DwmsLink();
		assertFalse(link.accept(null));
		assertFalse(link.accept(Map.of()));

		Map<String, Object> data = response("not a list");
		assertFalse(link.accept(data));

		assertTrue(link.accept(response(List.of(
			"not a map",
			storage("stash", "STASH Units", "not a list"),
			storage("poh", "Armour Case", List.of(
				"not a map",
				item("4151", 1L),
				item(4151, "1"),
				item(null, 1L),
				item(4151, null),
				item(-1, 1L),
				item(0, 1L),
				item(4151, 0L),
				item(4151, -3L),
				item(11832, 2L)))))));

		assertTrue(link.isLive(), "a valid response with junk entries still goes live");
		assertEquals(Map.of(11832, 2), link.snapshot());
	}

	@Test
	@DisplayName("quantities beyond int range clamp instead of overflowing")
	void hugeQuantitiesClamp()
	{
		DwmsLink link = new DwmsLink();
		assertTrue(link.accept(response(List.of(
			storage("coins", "Coffer", List.of(item(995, 999_999_999_999L)))))));
		assertEquals(Integer.MAX_VALUE, link.snapshot().get(995));
	}

	@Test
	@DisplayName("an empty response still counts as live - DWMS answered, it just tracks nothing")
	void emptyResponseIsLive()
	{
		DwmsLink link = new DwmsLink();
		assertTrue(link.accept(response(List.of())));
		assertTrue(link.isLive());
		assertEquals(0, link.count());
	}

	@Test
	@DisplayName("a newer response replaces the previous snapshot wholesale")
	void newerResponseReplaces()
	{
		DwmsLink link = new DwmsLink();
		assertTrue(link.accept(response(List.of(
			storage("stash", "STASH Units", List.of(item(4151, 1L)))))));
		assertTrue(link.accept(response(List.of(
			storage("stash", "STASH Units", List.of(item(11832, 1L)))))));

		assertEquals(Map.of(11832, 1), link.snapshot());
	}

	@Test
	@DisplayName("reset (identity change) drops the snapshot and live status")
	void resetClears()
	{
		DwmsLink link = new DwmsLink();
		assertTrue(link.accept(response(List.of(
			storage("stash", "STASH Units", List.of(item(4151, 1L)))))));

		link.reset();

		assertFalse(link.isLive());
		assertTrue(link.snapshot().isEmpty());
		assertEquals(0, link.count());
	}

	@Test
	@DisplayName("the request payload carries our display name as the source")
	void requestCarriesSource()
	{
		assertEquals("Loadout Lab", DwmsLink.request().get("source"));
	}

	@Test
	@DisplayName("merge folds the live items into an owned map, summing quantities")
	void mergeSumsIntoOwned()
	{
		DwmsLink link = new DwmsLink();
		assertTrue(link.accept(response(List.of(
			storage("stash", "STASH Units", List.of(item(4151, 1L)))))));

		Map<Integer, Integer> owned = new HashMap<>(Map.of(4151, 2));
		link.mergeInto(owned);
		assertEquals(3, owned.get(4151));
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.loadoutlab.testsupport.InMemoryConfigManager;
import net.runelite.client.config.ConfigManager;
import org.junit.Assert;
import org.junit.Test;

public class ExclusionStoreTest
{
	@Test
	public void togglePersistsAcrossInstancesAndClears()
	{
		ConfigManager configManager = InMemoryConfigManager.create();
		ExclusionStore store = new ExclusionStore(configManager, new Gson());
		Assert.assertTrue(store.toggle(11230));
		Assert.assertTrue(store.isExcluded(11230));

		ExclusionStore next = new ExclusionStore(configManager, new Gson());
		Assert.assertTrue(next.isExcluded(11230));
		Assert.assertFalse(next.toggle(11230));
		Assert.assertFalse(next.isExcluded(11230));

		next.toggle(4151);
		next.clear();
		Assert.assertTrue(new ExclusionStore(configManager, new Gson()).snapshot().isEmpty());
	}
}

package com.loadoutlab.collection;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class ItemLocationsTest
{
	private static ItemLocations locations(Map<String, Map<Integer, Integer>> origins)
	{
		// Variant map for the tests: 100 and 101 are interchangeable.
		return new ItemLocations(origins,
			id -> id == 100 || id == 101 ? Set.of(100, 101) : Set.of(id));
	}

	private static Map<String, Map<Integer, Integer>> origins()
	{
		Map<String, Map<Integer, Integer>> origins = new LinkedHashMap<>();
		origins.put("equipped", Map.of(1, 1));
		origins.put("bank", Map.of(2, 1));
		origins.put("STASH", Map.of(3, 1, 101, 1));
		origins.put("POH costume room", Map.of(3, 1));
		origins.put("STASH" + ItemLocations.VIA_DWMS, Map.of(3, 1, 4, 1));
		origins.put("death storage" + ItemLocations.VIA_DWMS, Map.of(5, 1));
		return origins;
	}

	@Test
	@DisplayName("where() lists every origin holding the item, in display order")
	void whereListsOriginsInOrder()
	{
		assertEquals(List.of("STASH", "POH costume room", "STASH" + ItemLocations.VIA_DWMS),
			locations(origins()).where(3));
		assertTrue(locations(origins()).where(99).isEmpty());
	}

	@Test
	@DisplayName("a stored variant answers for the base id the optimizer suggests")
	void variantAnswersForBase()
	{
		assertEquals(List.of("STASH"), locations(origins()).where(100));
	}

	@Test
	@DisplayName("no hint when the item is at hand or not owned at all")
	void noHintWhenAtHandOrUnowned()
	{
		ItemLocations locations = locations(origins());
		assertEquals("", fetchHint(locations, 1), "equipped is at hand");
		assertEquals("", fetchHint(locations, 2), "banked is at hand");
		assertEquals("", fetchHint(locations, 99), "unowned items get no hint");
	}

	@Test
	@DisplayName("the hint names remote storages, preferring native labels over DWMS twins")
	void hintNamesRemoteStores()
	{
		ItemLocations locations = locations(origins());
		assertEquals("stored in STASH + POH costume room", fetchHint(locations, 3));
		assertEquals("stored in STASH" + ItemLocations.VIA_DWMS, fetchHint(locations, 4),
			"a DWMS-only origin still names itself");
		assertEquals("stored in death storage" + ItemLocations.VIA_DWMS, fetchHint(locations, 5));
	}

	@Test
	@DisplayName("the primary label folds DWMS twins onto native names and buckets the rest")
	void primaryLabels()
	{
		ItemLocations locations = locations(origins());
		assertEquals("equipped", locations.primary(1));
		assertEquals("bank", locations.primary(2));
		assertEquals("STASH", locations.primary(3), "first origin in display order wins");
		assertEquals("STASH", locations.primary(4), "DWMS twin folds onto the native name");
		assertEquals("DWMS", locations.primary(5), "DWMS-only family buckets as DWMS");
		assertEquals("", locations.primary(99), "unknown location has no label");
	}

	@Test
	@DisplayName("without a variant map, matching falls back to exact ids")
	void exactMatchingWithoutDataset()
	{
		ItemLocations locations = new ItemLocations(origins(), null);
		assertTrue(locations.where(100).isEmpty(), "101 no longer answers for 100");
		assertEquals(List.of("STASH"), locations.where(101));
	}

	/** The tooltip clause the plugin once built here; kept as the test's oracle. */
	private static String fetchHint(ItemLocations locations, int itemId)
	{
		List<String> where = locations.where(itemId);
		if (where.isEmpty())
		{
			return "";
		}
		for (String label : where)
		{
			if (java.util.Set.of("equipped", "inventory", "bank").contains(label))
			{
				return "";
			}
		}
		List<String> named = new ArrayList<>();
		for (String label : where)
		{
			if (!label.endsWith(ItemLocations.VIA_DWMS))
			{
				named.add(label);
			}
		}
		if (named.isEmpty())
		{
			named = where;
		}
		return "stored in " + String.join(" + ", named);
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.loadoutlab.testsupport.InMemoryConfigManager;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class ManualOwnedStoreTest
{
	private ConfigManager configManager;
	private ManualOwnedStore store;

	@BeforeEach
	void setUp()
	{
		configManager = InMemoryConfigManager.create();
		store = new ManualOwnedStore(configManager, new Gson());
		store.loadScope("std.1111");
	}

	@Test
	@DisplayName("marking an item stored elsewhere survives a new session on the same account")
	void togglePersistsAcrossInstances()
	{
		assertTrue(store.toggle(4151));
		assertTrue(store.isStored(4151));

		ManualOwnedStore next = new ManualOwnedStore(configManager, new Gson());
		next.loadScope("std.1111");
		assertTrue(next.isStored(4151));
		assertFalse(next.toggle(4151));
		assertFalse(next.isStored(4151));
	}

	@Test
	@DisplayName("stored-elsewhere lists never leak between accounts or world types")
	void scopesAreIsolated()
	{
		store.toggle(4151);

		store.loadScope("std.2222");
		assertTrue(store.snapshot().isEmpty(), "account B starts empty");
		store.toggle(11802);

		store.loadScope("seasonal.1111");
		assertTrue(store.snapshot().isEmpty(), "seasonal scope starts empty");

		store.loadScope("std.1111");
		assertTrue(store.isStored(4151));
		assertFalse(store.isStored(11802), "account B's item must not leak into A");
	}

	@Test
	@DisplayName("merging into the ledger view adds quantity-1 entries without losing real counts")
	void mergeIntoAddsWithoutLosingCounts()
	{
		store.toggle(12006);
		store.toggle(4151);

		Map<Integer, Integer> owned = new HashMap<>(Map.of(4151, 1, 861, 2));
		Map<Integer, Integer> merged = store.mergeInto(owned);

		assertEquals(1, merged.get(12006), "stored-only item joins at quantity 1");
		assertEquals(2, merged.get(861), "ledger counts pass through untouched");
		assertTrue(merged.get(4151) >= 1, "an item both banked and stored stays owned");
	}

	@Test
	@DisplayName("a corrupt persisted entry starts the list fresh instead of failing")
	void corruptEntryDegradesGracefully()
	{
		configManager.setConfiguration("loadoutlab", "std.1111.manualOwned", "{not json!");
		ManualOwnedStore fresh = new ManualOwnedStore(configManager, new Gson());
		fresh.loadScope("std.1111");
		assertTrue(fresh.snapshot().isEmpty());
	}

	@Test
	@DisplayName("clear empties the list and the empty state persists")
	void clearEmptiesAndPersists()
	{
		store.toggle(4151);
		store.clear();

		ManualOwnedStore next = new ManualOwnedStore(configManager, new Gson());
		next.loadScope("std.1111");
		assertTrue(next.snapshot().isEmpty());
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.testsupport.InMemoryConfigManager;
import java.util.Map;
import java.util.Set;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class MonsterProfileStoreTest
{
	private static final String ALL = MonsterProfileStore.ALL;

	private static final String SCOPE = "std.1111";
	private ConfigManager configManager;
	private MonsterProfileStore store;

	@BeforeEach
	void setUp()
	{
		configManager = InMemoryConfigManager.create();
		store = freshStore();
	}

	/** The plugin always loads a character scope before use; a store without
	 * one writes to the pre-0.4.1 unscoped key, so an assertion on a scoped
	 * key would pass without testing anything. */
	private MonsterProfileStore freshStore()
	{
		MonsterProfileStore fresh = new MonsterProfileStore(configManager, new Gson());
		fresh.loadScope(SCOPE);
		return fresh;
	}

	@Test
	@DisplayName("pins are per monster AND per scope: a style pin overlays the all-sets pin")
	void pinsScopeAndOverlay()
	{
		store.pin(415, ALL, GearSlot.HANDS, 21183);
		store.pin(415, "RANGED", GearSlot.HANDS, 7462);

		assertEquals(Integer.valueOf(21183), store.pinsFor(415, "MELEE").get(GearSlot.HANDS),
			"melee inherits the all-sets pin");
		assertEquals(Integer.valueOf(7462), store.pinsFor(415, "RANGED").get(GearSlot.HANDS),
			"the ranged-scoped pin wins its own card");
		assertTrue(store.pinsFor(9999, "MELEE").isEmpty(), "another mob starts clean");

		store.unpin(415, "RANGED", GearSlot.HANDS);
		assertEquals(Integer.valueOf(21183), store.pinsFor(415, "RANGED").get(GearSlot.HANDS),
			"removing the style pin falls back to all-sets");
	}

	@Test
	@DisplayName("filter items merge all-sets with the style scope")
	void filterItemsMerge()
	{
		store.addFilterItem(415, ALL, 385, "Shark");
		store.addFilterItem(415, "MELEE", 12695, "Super combat potion(4)");
		store.addFilterItem(415, "RANGED", 2444, "Ranging potion(4)");

		assertEquals(Set.of(385, 12695), filterItemsFor(store, 415, "MELEE"));
		assertEquals(Set.of(385, 2444), filterItemsFor(store, 415, "RANGED"));
		assertEquals(Set.of(385), filterItemsFor(store, 415, "MAGIC"));
	}

	@Test
	@DisplayName("per-mob exclusions merge all-sets with the style scope, per monster")
	void exclusionsMergeScopes()
	{
		store.exclude(415, ALL, 4151);
		store.exclude(415, "MELEE", 11802);
		store.exclude(9999, ALL, 12006);

		assertEquals(Set.of(4151, 11802), store.exclusionsFor(415, "MELEE"),
			"the melee card excludes the all-sets item AND the melee-only one");
		assertEquals(Set.of(4151), store.exclusionsFor(415, "RANGED"),
			"other cards only inherit the all-sets exclusion");
		assertEquals(Set.of(12006), store.exclusionsFor(9999, "MELEE"),
			"exclusions are per monster");
		assertTrue(store.exclusionsFor(1, "MELEE").isEmpty(), "unknown mob starts clean");
	}

	@Test
	@DisplayName("removing a per-mob exclusion restores the item for that scope only")
	void exclusionRemoval()
	{
		store.exclude(415, ALL, 4151);
		store.exclude(415, "MELEE", 4151);

		store.removeMobExclusion(415, "MELEE", 4151);
		assertEquals(Set.of(4151), store.exclusionsFor(415, "MELEE"),
			"the all-sets exclusion still applies after the style one is removed");

		store.removeMobExclusion(415, ALL, 4151);
		assertTrue(store.exclusionsFor(415, "MELEE").isEmpty());
		assertTrue(store.allExclusions(415).isEmpty(),
			"raw view empties once every scope is removed");
	}

	@Test
	@DisplayName("per-mob exclusions survive a reload (config round-trip)")
	void exclusionsPersist()
	{
		store.exclude(415, ALL, 4151);
		store.exclude(415, "RANGED", 12926);

		MonsterProfileStore reloaded = freshStore();
		assertEquals(Set.of(4151, 12926), reloaded.exclusionsFor(415, "RANGED"));
		assertEquals(Map.of(ALL, Set.of(4151), "RANGED", Set.of(12926)),
			reloaded.allExclusions(415));
	}

	@Test
	@DisplayName("a profile holding only exclusions is not pruned; removing them prunes it")
	void exclusionsKeepTheProfileAlive()
	{
		store.exclude(415, ALL, 4151);
		MonsterProfileStore reloaded = freshStore();
		assertEquals(Set.of(4151), reloaded.exclusionsFor(415, "MELEE"));

		reloaded.removeMobExclusion(415, ALL, 4151);
		MonsterProfileStore emptied = freshStore();
		assertTrue(emptied.allExclusions(415).isEmpty());
	}

	@Test
	@DisplayName("the whole profile survives a new session, scopes intact")
	void profilePersistsAcrossSessions()
	{
		store.pin(415, ALL, GearSlot.HANDS, 21183);
		store.setNote(415, "bring antidote++, pray melee after the spec");
		store.addFilterItem(415, "MELEE", 12695, "Super combat potion(4)");

		MonsterProfileStore next = freshStore();
		assertEquals(Map.of(GearSlot.HANDS, 21183), next.pinsFor(415, "MELEE"));
		assertEquals("bring antidote++, pray melee after the spec", next.note(415));
		assertEquals(Set.of(12695), filterItemsFor(next, 415, "MELEE"));
		assertEquals("Super combat potion(4)",
			next.allFilterItems(415).get("MELEE").get(12695));
	}

	@Test
	@DisplayName("the pinned spell persists per mob and clears to auto")
	void pinnedSpellPersists()
	{
		store.setPinnedSpell(415, "Wind Bolt");
		assertEquals("Wind Bolt", freshStore()
			.pinnedSpell(415));
		assertEquals("", store.pinnedSpell(9999), "other mobs stay on auto");
		store.setPinnedSpell(415, "");
		assertEquals("", store.pinnedSpell(415));
	}

	@Test
	@DisplayName("a spec-only profile survives save (not judged empty and pruned)")
	void pinnedSpecPersists()
	{
		// Field report 2026-08-09: pinning a spec did nothing because the
		// save() empty-check omitted the spec field, so a spec-only profile
		// was pruned in the same call that set it (the exact 2026-07-18 sims
		// bug, recurring). Read back from a FRESH store = the config
		// round-trip, the path the compute actually reads.
		store.setPinnedSpec(415, 28922);
		assertEquals(28922, freshStore()
			.pinnedSpec(415), "the spec pin must survive save + reload");
		assertEquals(0, store.pinnedSpec(9999), "other mobs stay on auto");
		store.setPinnedSpec(415, 0);
		assertEquals(0, store.pinnedSpec(415), "clearing returns to auto");
	}

	@Test
	@DisplayName("clearing every field prunes the profile from config entirely")
	void emptyProfilesPrune()
	{
		store.pin(415, ALL, GearSlot.HANDS, 21183);
		store.setNote(415, "note");
		store.setPinnedSpell(415, "Wind Bolt");
		store.addFilterItem(415, "MELEE", 385, "Shark");
		store.unpin(415, ALL, GearSlot.HANDS);
		store.setNote(415, "  ");
		store.setPinnedSpell(415, null);
		store.removeMobFilter(415, "MELEE", 385);

		String json = configManager.getConfiguration("loadoutlab", SCOPE + ".monsterProfiles");
		assertEquals("{}", json, "empty profiles must not accumulate as husks");
	}

	@Test
	@DisplayName("corrupt config degrades to no profiles")
	void corruptDegrades()
	{
		configManager.setConfiguration("loadoutlab", SCOPE + ".monsterProfiles", "{not json!");
		MonsterProfileStore fresh = freshStore();
		assertTrue(fresh.pinsFor(415, "MELEE").isEmpty());
		assertEquals("", fresh.note(415));
	}

	@Test
	@DisplayName("a sims-only profile survives the save (the Sim here field bug)")
	void simsOnlyProfilePersists()
	{
		// Field bug 2026-07-18: save()'s empty-profile prune did not count
		// sims, so a profile holding ONLY a sim was erased by the very call
		// that added it - "Sim here" appeared to do nothing.
		store.addSim(239, 22324, "Ghrazi rapier");
		assertEquals(Map.of(22324, "Ghrazi rapier"), store.allSims(239));
		assertEquals(Set.of(22324), store.simsFor(239));

		MonsterProfileStore reloaded = freshStore();
		assertEquals(Map.of(22324, "Ghrazi rapier"), reloaded.allSims(239),
			"the sim survives a config round-trip");

		store.removeMobSim(239, 22324);
		assertTrue(store.allSims(239).isEmpty());
		assertEquals("{}", configManager.getConfiguration("loadoutlab", SCOPE + ".monsterProfiles"),
			"an emptied sims profile prunes back to nothing");
	}

	@Test
	@DisplayName("supply overrides persist per mob and clear back to the global default")
	void supplyOverridesPersistAndClear()
	{
		store.setSupplyOverride(8781, "prayerRestore", "SANFEW_SERUM");
		store.setSupplyOverride(8781, "food", "NONE");
		assertEquals(Map.of("prayerRestore", "SANFEW_SERUM", "food", "NONE"),
			store.supplyOverrides(8781));
		assertTrue(store.supplyOverrides(9999).isEmpty(), "another mob keeps the defaults");

		MonsterProfileStore reloaded = freshStore();
		assertEquals("SANFEW_SERUM", reloaded.supplyOverrides(8781).get("prayerRestore"),
			"overrides survive a config round-trip");

		store.setSupplyOverride(8781, "prayerRestore", null);
		assertEquals(Map.of("food", "NONE"), store.supplyOverrides(8781),
			"a null choice returns the category to the global default");
	}

	@Test
	@DisplayName("a supplies-only profile survives the save (the every-field prune rule)")
	void suppliesOnlyProfilePersists()
	{
		// The Sim-here field bug's lesson: every Stored field must join
		// save()'s empty check, or a supplies-only profile would be erased
		// by the very call that set it.
		store.setSupplyOverride(8781, "antivenom", "ANTIVENOM_PLUS");
		MonsterProfileStore reloaded = freshStore();
		assertEquals(Map.of("antivenom", "ANTIVENOM_PLUS"), reloaded.supplyOverrides(8781));

		store.setSupplyOverride(8781, "antivenom", "");
		assertEquals("{}", configManager.getConfiguration("loadoutlab", SCOPE + ".monsterProfiles"),
			"clearing the only override prunes the profile away");
	}

	@Test
	@DisplayName("skipping degradable gear for a mob folds the degradable ids into every scope's exclusions, keeps the manage list clean, and survives a reload")
	void skipDegradable()
	{
		MonsterProfileStore store = new MonsterProfileStore(configManager, new Gson());
		store.setDegradableIds(Set.of(4716, 12006));
		assertFalse(store.skipDegradable(7, false), "unset follows the panel default");
		assertTrue(store.skipDegradable(7, true), "unset follows the panel default");
		store.setSkipDegradable(7, true);
		assertTrue(store.exclusionsFor(7, "MELEE").containsAll(Set.of(4716, 12006)));
		assertTrue(store.exclusionsFor(7, MonsterProfileStore.ALL_SETS).contains(4716));
		assertTrue(store.allExclusions(7).isEmpty(), "the manage menu lists only hand-picked exclusions");
		assertTrue(store.exclusionsFor(8, "MELEE").isEmpty(), "other mobs are untouched");
		MonsterProfileStore fresh = new MonsterProfileStore(configManager, new Gson());
		fresh.setDegradableIds(Set.of(4716));
		assertTrue(fresh.skipDegradable(7, false), "persisted");
		assertTrue(fresh.exclusionsFor(7, "RANGED").contains(4716));
		store.setSkipDegradable(7, false);
		assertFalse(store.skipDegradable(7, true));
		assertTrue(store.exclusionsFor(7, "MELEE").isEmpty());
	}

	/** ALL plus the style, as the card sees it. */
	private static Set<Integer> filterItemsFor(MonsterProfileStore store, int monsterId, String style)
	{
		Set<Integer> ids = new java.util.LinkedHashSet<>();
		Map<String, Map<Integer, String>> all = store.allFilterItems(monsterId);
		for (String scope : new String[]{MonsterProfileStore.ALL_SETS, style})
		{
			if (all.get(scope) != null)
			{
				ids.addAll(all.get(scope).keySet());
			}
		}
		return ids;
	}

	@Test
	@DisplayName("clear() empties every profile in the scope and persists the wipe (the reset-customisations control)")
	void clearWipesTheScope()
	{
		MonsterProfileStore store = new MonsterProfileStore(configManager, new Gson());
		store.setNote(415, "keep away");
		store.setSkipDegradable(416, true);
		store.clear();
		assertEquals("", store.note(415) == null ? "" : store.note(415));
		assertFalse(store.skipDegradable(416, false));
		MonsterProfileStore fresh = new MonsterProfileStore(configManager, new Gson());
		assertTrue(fresh.note(415) == null || fresh.note(415).isEmpty(), "the wipe persisted");
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.loadoutlab.testsupport.InMemoryConfigManager;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-25: "when i switched from my main to my test account, i
 * saw that the exclude list/sim list is the same. this should be unique per
 * character."
 *
 * <p>The bank ledger and the manual-owned list were already per-character; six
 * other stores wrote to a bare, global key. This pins the fix for the whole
 * family, plus the one-time migration that stops an existing install losing
 * its lists when the key gains the account hash.
 */
class PerCharacterScopeTest
{
	private ConfigManager configManager;
	private Gson gson;

	@BeforeEach
	void setUp()
	{
		configManager = InMemoryConfigManager.create();
		gson = new Gson();
	}

	@Test
	@DisplayName("two characters keep separate exclude, sim and protect lists")
	void listsDoNotBleedBetweenCharacters()
	{
		ExclusionStore exclusions = new ExclusionStore(configManager, gson);
		DreamStore dreams = new DreamStore(configManager, gson);
		ProtectOnlyStore protect = new ProtectOnlyStore(configManager, gson);

		exclusions.loadScope("std.1111");
		dreams.loadScope("std.1111");
		protect.loadScope("std.1111");
		exclusions.toggle(11832);   // bandos chestplate
		dreams.toggle(20997);       // twisted bow
		protect.toggle(4151);       // whip
		assertTrue(exclusions.isExcluded(11832));
		assertTrue(dreams.isDreamed(20997));
		assertTrue(protect.isProtectOnly(4151));

		// Switch character - the same store objects, a new scope.
		exclusions.loadScope("std.2222");
		dreams.loadScope("std.2222");
		protect.loadScope("std.2222");
		assertFalse(exclusions.isExcluded(11832), "the alt inherited the main's excludes");
		assertFalse(dreams.isDreamed(20997), "the alt inherited the main's sims");
		assertFalse(protect.isProtectOnly(4151), "the alt inherited the main's protect list");

		// ...and switching back finds the main's lists intact.
		exclusions.loadScope("std.1111");
		dreams.loadScope("std.1111");
		protect.loadScope("std.1111");
		assertTrue(exclusions.isExcluded(11832), "the main lost its excludes on return");
		assertTrue(dreams.isDreamed(20997), "the main lost its sims on return");
		assertTrue(protect.isProtectOnly(4151), "the main lost its protect list on return");
	}

	@Test
	@DisplayName("an existing install carries its pre-0.4.1 list into the first character")
	void legacyKeyMigratesOnce()
	{
		// What a pre-0.4.1 install looks like: a bare, unscoped key.
		configManager.setConfiguration("loadoutlab", "excludedItems", "[11832,4151]");

		ExclusionStore exclusions = new ExclusionStore(configManager, gson);
		exclusions.loadScope("std.1111");
		assertTrue(exclusions.isExcluded(11832), "the pre-0.4.1 list was dropped on upgrade");
		assertTrue(exclusions.isExcluded(4151), "the pre-0.4.1 list was dropped on upgrade");
	}

	@Test
	@DisplayName("seasonal and standard worlds are separate scopes for the same account")
	void seasonalIsItsOwnScope()
	{
		ExclusionStore exclusions = new ExclusionStore(configManager, gson);
		exclusions.loadScope("std.1111");
		exclusions.toggle(11832);

		exclusions.loadScope("seasonal.1111");
		assertFalse(exclusions.isExcluded(11832),
			"a leagues account inherited the main game's excludes");
	}

	@Test
	@DisplayName("monster profiles and supply defaults scope per character too")
	void profilesAndSuppliesScope()
	{
		MonsterProfileStore profiles = new MonsterProfileStore(configManager, gson);
		SupplyDefaultsStore supplies = new SupplyDefaultsStore(configManager, gson);

		profiles.loadScope("std.1111");
		supplies.loadScope("std.1111");
		profiles.setNote(2215, "bring a dds");
		supplies.setChoice("food", "shark");
		assertEquals("bring a dds", profiles.note(2215));
		assertEquals("shark", supplies.choice("food"));

		profiles.loadScope("std.2222");
		supplies.loadScope("std.2222");
		// noteFor returns "" for absent, never null.
		assertEquals("", profiles.note(2215), "the alt inherited the main's mob notes");
		assertNotEquals("shark", supplies.choice("food"),
			"the alt inherited the main's supply defaults");
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
