		List<GearItem> results = GearSearchTestSupport.searchGear(data, "abyssal w", 5);
		assertFalse(results.isEmpty());
		assertTrue(results.size() <= 5);
		assertTrue(results.get(0).labelLower().startsWith("abyssal w"),
			"first result should be a prefix match, got: " + results.get(0).label());
		for (GearItem item : results)
		{
			assertTrue(item.labelLower().contains("abyssal w"));
		}
	}

	@Test
	@DisplayName("a numeric query matches the item id exactly")
	void idQueryMatches()
	{
		List<GearItem> results = GearSearchTestSupport.searchGear(data, "4151", 5);
		assertFalse(results.isEmpty());
		assertEquals(4151, results.get(0).getId());
	}

	@Test
	@DisplayName("blank and unknown queries return no matches")
	void blankAndUnknownReturnEmpty()
	{
		assertTrue(GearSearchTestSupport.searchGear(data, "   ", 10).isEmpty());
		assertTrue(GearSearchTestSupport.searchGear(data, null, 10).isEmpty());
		assertTrue(GearSearchTestSupport.searchGear(data, "zzz not an item zzz", 10).isEmpty());
	}

	@Test
	@DisplayName("queries are case-insensitive")
	void caseInsensitive()
	{
		List<GearItem> lower = GearSearchTestSupport.searchGear(data, "dragon dagger", 5);
		List<GearItem> upper = GearSearchTestSupport.searchGear(data, "DRAGON Dagger", 5);
		assertFalse(lower.isEmpty());
		assertEquals(lower.get(0).getId(), upper.get(0).getId());
		assertEquals("dragon dagger",
			lower.get(0).getNameLower().toLowerCase(Locale.ROOT));
	}
}

package com.loadoutlab.data;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * Gear-corpus search used only by the test suite. Kept out of main source
 * so it does not count against the Plugin Hub bot's 200k token budget; the
 * ranking is the production version verbatim, driven off the public
 * {@link LoadoutData#getGearItems()} corpus view.
 */
public final class GearSearchTestSupport
{
	private GearSearchTestSupport()
	{
	}

	/**
	 * Item-name search: exact label/name (or id) first, then prefix, then
	 * substring - same ranking shape as {@link LoadoutData#searchMonsters}.
	 */
	public static List<GearItem> searchGear(LoadoutData data, String query, int limit)
	{
		String text = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
		if (text.isEmpty())
		{
			return Collections.emptyList();
		}

		ArrayList<GearItem> exact = new ArrayList<>();
		ArrayList<GearItem> prefix = new ArrayList<>();
		ArrayList<GearItem> contains = new ArrayList<>();
		for (GearItem item : data.getGearItems())
		{
			String label = item.labelLower();
			if (label.equals(text) || item.getNameLower().equals(text)
				|| String.valueOf(item.getId()).equals(text))
			{
				exact.add(item);
			}
			else if (label.startsWith(text))
			{
				prefix.add(item);
			}
			else if (label.contains(text))
			{
				contains.add(item);
			}
		}

		ArrayList<GearItem> result = new ArrayList<>(limit);
		addLimited(result, exact, limit);
		addLimited(result, prefix, limit);
		addLimited(result, contains, limit);
		return result;
	}

	private static <T> void addLimited(List<T> target, List<T> source, int limit)
	{
		for (T entry : source)
		{
			if (target.size() >= limit)
			{
				return;
			}
			target.add(entry);
		}
	}
}

