package com.loadoutlab.data;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

/**
 * The trip-supply tier tables (field direction 2026-07-20): persistent
 * food/fast-food/prayer/surge/anti-venom defaults with a "Detect best"
 * that picks the best owned tier, and anti-venom gated on the wiki's
 * venom-inflictor list.
 */
public class TripSuppliesTest
{
	@Test
	public void everyCategoryLoadsWithBestFirstOrdering()
	{
		// Spot-check the verified tier heads (wiki 2026-07-20): moonlight
		// antelope 26 hp leads food, karambwan leads fast food, super
		// restore leads prayer, extended anti-venom+ leads anti-venom.
		Assert.assertEquals("MOONLIGHT_ANTELOPE", TripSupplies.options(TripSupplies.FOOD).get(0).key);
		Assert.assertEquals("KARAMBWAN", TripSupplies.options(TripSupplies.FAST_FOOD).get(0).key);
		Assert.assertEquals("SUPER_RESTORE", TripSupplies.options(TripSupplies.PRAYER_RESTORE).get(0).key);
		Assert.assertEquals("SURGE_POTION", TripSupplies.options(TripSupplies.SURGE).get(0).key);
		Assert.assertEquals("MAX_CAPE", TripSupplies.options(TripSupplies.SPELLBOOK_CAPE).get(0).key);
		Assert.assertEquals("EXTENDED_ANTIVENOM", TripSupplies.options(TripSupplies.ANTIVENOM).get(0).key);
	}

	@Test
	public void detectBestPicksTheBestOwnedTierAcrossAnyDose()
	{
		// Owning only a 1-dose prayer potion (id 143) must still detect
		// PRAYER_POTION - the filter and detection cover every dose.
		Set<Integer> owned = new HashSet<>();
		owned.add(143);
		TripSupplies.Option pick = TripSupplies.detectBest(TripSupplies.PRAYER_RESTORE, owned::contains);
		Assert.assertNotNull(pick);
		Assert.assertEquals("PRAYER_POTION", pick.key);

		// Adding a super restore (3-dose, 3026) upgrades the pick.
		owned.add(3026);
		Assert.assertEquals("SUPER_RESTORE",
			TripSupplies.detectBest(TripSupplies.PRAYER_RESTORE, owned::contains).key);
	}

	/** Andrew 2026-09-01: "wildy food / supplies should prefer blighted
	 * options". Blighted variants are wilderness-only (wiki), so a trip
	 * there takes a banked one over any tradeable tier, and a land trip
	 * never picks one (ids objtypes-verified 2026-09-02). */
	@Test
	public void blightedSuppliesWinInTheWildernessAndNeverOnLand()
	{
		Set<Integer> bank = new HashSet<>(List.of(29143, 24592, 3024, 24598, 3144, 24595));
		Assert.assertEquals("BLIGHTED_ANGLERFISH",
			TripSupplies.detectBest(TripSupplies.FOOD, bank::contains, true).key);
		Assert.assertEquals("BLIGHTED_SUPER_RESTORE",
			TripSupplies.detectBest(TripSupplies.PRAYER_RESTORE, bank::contains, true).key);
		Assert.assertEquals("BLIGHTED_KARAMBWAN",
			TripSupplies.detectBest(TripSupplies.FAST_FOOD, bank::contains, true).key);
		// Land: the best tradeable tier, blighted ignored even when owned.
		Assert.assertEquals("MOONLIGHT_ANTELOPE",
			TripSupplies.detectBest(TripSupplies.FOOD, bank::contains, false).key);
		Set<Integer> onlyBlighted = Set.of(24592);
		Assert.assertNull("blighted cannot be eaten outside the wilderness",
			TripSupplies.detectBest(TripSupplies.FOOD, onlyBlighted::contains, false));
		// Wilderness without a blighted stack falls through to the tiers.
		Set<Integer> sharks = Set.of(385);
		Assert.assertEquals("SHARK",
			TripSupplies.detectBest(TripSupplies.FOOD, sharks::contains, true).key);
		// The two-arg detect is the land rule.
		Assert.assertNull(TripSupplies.detectBest(TripSupplies.FOOD, onlyBlighted::contains));
	}

	@Test
	public void detectBestReturnsNullWhenNothingIsOwned()
	{
		Assert.assertNull(TripSupplies.detectBest(TripSupplies.FOOD, id -> false));
	}

	@Test
	public void prayerRegenerationIsNeverAutoDetected()
	{
		// Its over-time mechanism must not win a detect - explicitly
		// selectable only (detect:false in the resource).
		Set<Integer> owned = new HashSet<>();
		owned.add(30125); // Prayer regeneration potion(4)
		Assert.assertNull(TripSupplies.detectBest(TripSupplies.PRAYER_RESTORE, owned::contains));
		Assert.assertNotNull(TripSupplies.option(TripSupplies.PRAYER_RESTORE, "PRAYER_REGENERATION"));
	}

	@Test
	public void spellbookCapeDetectPrefersTheMaxCape()
	{
		Set<Integer> owned = new HashSet<>();
		owned.add(9763); // Magic cape(t)
		Assert.assertEquals("MAGIC_CAPE",
			TripSupplies.detectBest(TripSupplies.SPELLBOOK_CAPE, owned::contains).key);
		owned.add(13280); // Max cape
		Assert.assertEquals("MAX_CAPE",
			TripSupplies.detectBest(TripSupplies.SPELLBOOK_CAPE, owned::contains).key);
	}

	@Test
	public void onlyTheSpellbookCapesAreUtilityPlacement()
	{
		// Utility = fight-relevant gear that is neither worn nor carried:
		// the bank layout's third strip. Consumables stay inventory-placed.
		for (TripSupplies.Option o : TripSupplies.options(TripSupplies.SPELLBOOK_CAPE))
		{
			Assert.assertTrue(o.key + " should be utility", o.utility);
		}
		for (String category : new String[]{TripSupplies.FOOD, TripSupplies.FAST_FOOD,
			TripSupplies.PRAYER_RESTORE, TripSupplies.SURGE, TripSupplies.ANTIVENOM})
		{
			for (TripSupplies.Option o : TripSupplies.options(category))
			{
				Assert.assertFalse(o.key + " should not be utility", o.utility);
			}
		}
	}

	@Test
	public void spellKitsCarryTheVerifiedArceuusCosts()
	{
		// Wiki-verified 2026-07-21: greater resurrect 10 fire 5 blood
		// 1 cosmic; Death Charge 1 death 1 blood 1 soul; Mark of Darkness
		// 1 cosmic 1 soul; pouch detect order divine > base.
		org.junit.Assert.assertArrayEquals(new int[]{554, 565, 564},
			TripSupplies.spellKit("thrallGreaterRunes"));
		org.junit.Assert.assertArrayEquals(new int[]{560, 565, 566},
			TripSupplies.spellKit("deathChargeRunes"));
		org.junit.Assert.assertArrayEquals(new int[]{564, 566},
			TripSupplies.spellKit("markOfDarknessRunes"));
		org.junit.Assert.assertEquals(27281, TripSupplies.spellKit("runePouch")[0]);
		org.junit.Assert.assertArrayEquals(new int[]{9075, 564, 563},
			TripSupplies.spellKit("spellbookSwapRunes"));
		org.junit.Assert.assertArrayEquals(new int[]{9075, 557, 560},
			TripSupplies.spellKit("vengeanceRunes"));
		org.junit.Assert.assertEquals(0, TripSupplies.spellKit("noSuchKit").length);
	}

	@Test
	public void unknownAndModeKeysResolveToNoOption()
	{
		Assert.assertNull(TripSupplies.option(TripSupplies.FOOD, "DETECT_BEST"));
		Assert.assertNull(TripSupplies.option(TripSupplies.FOOD, "NONE"));
		Assert.assertNull(TripSupplies.option(TripSupplies.FOOD, "NO_SUCH"));
	}

	@Test
	public void venomInflictorsMatchByNameIncludingVariants()
	{
		Assert.assertTrue(TripSupplies.inflictsVenom(named("Zulrah")));
		Assert.assertTrue(TripSupplies.inflictsVenom(named("Araxxor")));
		Assert.assertTrue(TripSupplies.inflictsVenom(named("Dreadborn Araxyte")));
		Assert.assertTrue(TripSupplies.inflictsVenom(named("Vorkath")));
		Assert.assertFalse(TripSupplies.inflictsVenom(named("General Graardor")));
		Assert.assertFalse(TripSupplies.inflictsVenom(named("Abyssal demon")));
		Assert.assertFalse(TripSupplies.inflictsVenom(null));
	}

	@Test
	public void displayIdLeadsEachIdList()
	{
		// ids[0] is the display/cell id: the 4-dose potion or cooked food.
		for (String category : new String[]{TripSupplies.FOOD, TripSupplies.FAST_FOOD,
			TripSupplies.PRAYER_RESTORE, TripSupplies.SURGE, TripSupplies.SPELLBOOK_CAPE,
			TripSupplies.ANTIVENOM})
		{
			List<TripSupplies.Option> options = TripSupplies.options(category);
			Assert.assertFalse(category + " must not be empty", options.isEmpty());
			for (TripSupplies.Option o : options)
			{
				Assert.assertTrue(o.key + " needs at least one id", o.ids.length >= 1);
			}
		}
	}

	private static MonsterStats named(String name)
	{
		if (name == null)
		{
			return null;
		}
		return new MonsterStats(1, name, "", 100, 100, 1, 1, null, null);
	}

	@Test
	public void cureMeAndThePrayerBookAreChoicesNeverADetectBestPick()
	{
		TripSupplies.Option cureMe = TripSupplies.option(TripSupplies.ANTIVENOM, "CURE_ME");
		TripSupplies.Option book = TripSupplies.option(TripSupplies.ANTIVENOM, "PRAYER_BOOK");
		org.junit.jupiter.api.Assertions.assertNotNull(cureMe, "Cure Me option");
		org.junit.jupiter.api.Assertions.assertNotNull(book, "Prayer book option");
		org.junit.jupiter.api.Assertions.assertFalse(cureMe.detect);
		org.junit.jupiter.api.Assertions.assertFalse(book.detect);
		org.junit.jupiter.api.Assertions.assertEquals(9075, cureMe.ids[0], "astral rune leads the Cure Me kit");
		org.junit.jupiter.api.Assertions.assertEquals(10890, book.ids[0], "the prayer book itself leads its kit");
		// Kits name every item so the card shows each one (field 2026-09-08: the holy symbol was filter-only).
		org.junit.jupiter.api.Assertions.assertArrayEquals(new String[]{"Astral rune (Cure Me)", "Cosmic rune (Cure Me)", "Law rune (Cure Me)"}, cureMe.names);
		org.junit.jupiter.api.Assertions.assertArrayEquals(new String[]{"Prayer book", "Holy symbol"}, book.names);
		org.junit.jupiter.api.Assertions.assertEquals(0, TripSupplies.option(TripSupplies.ANTIVENOM, "ANTIVENOM_PLUS").names.length, "potions are one cell");
		// Owning every rune and the book still leaves Detect-best on the potions.
		TripSupplies.Option detected = TripSupplies.detectBest(TripSupplies.ANTIVENOM,
			id -> id == 9075 || id == 564 || id == 563 || id == 10890 || id == 1718);
		org.junit.jupiter.api.Assertions.assertNull(detected);
	}

	@Test
	public void antipoisonCoversThePoisonersTheVenomListDoesNot()
	{
		LoadoutData data = new DataService().load();
		MonsterStats rex = data.searchMonsters("Dagannoth Rex", 1).get(0);
		MonsterStats zulrah = data.searchMonsters("Zulrah", 1).get(0);
		Assert.assertTrue(TripSupplies.inflictsPoison(rex));
		Assert.assertFalse(TripSupplies.inflictsVenom(rex));
		Assert.assertFalse("venom is its own category", TripSupplies.inflictsPoison(zulrah));
		Assert.assertEquals("ANTIDOTE_PP", TripSupplies.options(TripSupplies.ANTIPOISON).get(0).key);
		Assert.assertEquals("ANTIPOISON",
			TripSupplies.detectBest(TripSupplies.ANTIPOISON, id -> id == 175 || id == 9075).key);
		Assert.assertNotNull(TripSupplies.option(TripSupplies.ANTIPOISON, "CURE_ME"));
		Assert.assertTrue(java.util.Arrays.asList(TripSupplies.CATEGORY_KEYS).contains(TripSupplies.ANTIPOISON));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.Map;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;

/** Stat-identical analogs (god d'hide) must track what the player owns. */
public class AnalogTest
{
	private static LoadoutData data;
	private static MonsterStats callisto;

	@BeforeClass
	public static void load()
	{
		data = new DataService().load();
		callisto = data.searchMonsters("callisto", 1).get(0);
	}

	private static GearItem headPick(int ownedCoif)
	{
		OptimizationRequest req = TestRequests.of(callisto, CombatStyle.RANGED,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, 0, CandidateMode.ALL_STANDARD, true, false,
			new OwnedItems(data.canonicalizeOwned(Map.of(ownedCoif, 1)), true), 1)
			.withMaxTradeables(3);
		LoadoutOptimizer optimizer = new LoadoutOptimizer();
		// Mirror production: the dps-neutral fill is what populates a head
		// slot the raw beam legally leaves empty (post Summer Sweep-Up
		// 2026-07-22, every risk-surviving ranged head is dps-neutral here).
		DpsResult best = optimizer.fillDpsNeutralSlots(data, req,
			optimizer.optimize(data, req).get(0));
		return best.getLoadout().get(com.loadoutlab.data.GearSlot.HEAD);
	}

	@Test
	public void legAnalogsAreStatIdenticalInTheData()
	{
		// Platelegs vs plateskirts, proselyte cuisse vs tasset: the
		// dedupe's owned-preference and the gold border's stat
		// equivalence both rest on these being true stat clones.
		assertClones(1079, 1093);  // rune platelegs / plateskirt
		assertClones(4087, 4585);  // dragon platelegs / plateskirt
		assertClones(9676, 9678);  // proselyte cuisse / tasset
	}

	private static void assertClones(int a, int b)
	{
		GearItem left = data.getGear(a);
		GearItem right = data.getGear(b);
		Assert.assertNotNull(left);
		Assert.assertNotNull(right);
		Assert.assertEquals(left.getSlot(), right.getSlot());
		for (java.util.function.Function<GearItem, com.loadoutlab.data.StatBlock> block
			: java.util.List.<java.util.function.Function<GearItem, com.loadoutlab.data.StatBlock>>of(
				GearItem::getOffensive, GearItem::getDefensive, GearItem::getBonuses))
		{
			com.loadoutlab.data.StatBlock l = block.apply(left);
			com.loadoutlab.data.StatBlock r = block.apply(right);
			Assert.assertEquals(l.getStab(), r.getStab());
			Assert.assertEquals(l.getSlash(), r.getSlash());
			Assert.assertEquals(l.getCrush(), r.getCrush());
			Assert.assertEquals(l.getMagic(), r.getMagic());
			Assert.assertEquals(l.getRanged(), r.getRanged());
			Assert.assertEquals(l.getStrength(), r.getStrength());
			Assert.assertEquals(l.getRangedStrength(), r.getRangedStrength());
			Assert.assertEquals(l.getMagicDamage(), r.getMagicDamage());
			Assert.assertEquals(l.getPrayer(), r.getPrayer());
		}
	}

	@Test
	public void prayerDistinguishesStatClones_radasBlessingBeatsAncientBlessing()
	{
		// Both are zero-offense ammo-slot blessings; Rada's 4 gives +2
		// prayer vs +1. The old dedupe key ignored prayer, collapsed them,
		// and the tradeable preference picked the ancient blessing.
		java.util.Map<Integer, Integer> owned = new java.util.HashMap<>();
		owned.put(4151, 1);   // abyssal whip
		owned.put(20235, 1);  // ancient blessing (+1, tradeable)
		owned.put(22947, 1);  // rada's blessing 4 (+2, untradeable)
		MonsterStats goblin = data.searchMonsters("goblin", 1).get(0);
		OptimizationRequest req = TestRequests.of(goblin, CombatStyle.MELEE,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, 0, CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(data.canonicalizeOwned(owned), true), 1);
		LoadoutOptimizer optimizer = new LoadoutOptimizer();
		DpsResult best = optimizer.fillDpsNeutralSlots(data, req,
			optimizer.optimize(data, req).get(0));
		GearItem ammo = best.getLoadout().get(com.loadoutlab.data.GearSlot.AMMO);
		Assert.assertNotNull(ammo);
		Assert.assertEquals("Rada's blessing 4", ammo.getName());
	}

	@Test
	public void statTiedAnalogsFollowOwnership()
	{
		GearItem armadyl = headPick(12512);
		GearItem bandos = headPick(12504);
		// Only assert when the head pick lands in the god-coif class at all
		// (data drift could promote another helm); when it does, it must be
		// the OWNED god's.
		if (armadyl != null && armadyl.getName().endsWith("coif"))
		{
			Assert.assertEquals("Armadyl coif", armadyl.getName());
		}
		if (bandos != null && bandos.getName().endsWith("coif"))
		{
			Assert.assertEquals("Bandos coif", bandos.getName());
		}
		Assert.assertNotNull(armadyl);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The dual macuahuitl and the Bloodrager set effect, wiki-verified
 * (2026-07-17 field report): the weapon lands two CHAINED hits - the
 * first rolls half the max, the second (the remainder) only rolls when
 * the first lands - and with the full blood moon set each successful hit
 * has a 1/3 chance to make the next attack come one tick earlier
 * (acc/3 + acc^2 * 2/9 per attack, the official calc's expected speed).
 * Before this, the engine treated the macuahuitl as a plain one-hit 4t
 * weapon, so a dreamed-in full set never beat anything.
 */
class BloodMoonSetTest
{
	private static LoadoutData data;
	private static MonsterStats ankou;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
		ankou = data.searchMonsters("ankou", 1).get(0);
	}

	private static GearItem byNameVersion(String nameLower, String version)
	{
		for (GearItem item : data.getGearItems())
		{
			if (item.getNameLower().equals(nameLower)
				&& (version == null || version.equalsIgnoreCase(item.getVersion())))
			{
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + nameLower + " " + version);
	}

	private static OptimizationRequest request()
	{
		return new OptimizationRequest(ankou, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
	}

	private static DpsResult calc(boolean fullSet)
	{
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byNameVersion("dual macuahuitl", null));
		if (fullSet)
		{
			gear.put(GearSlot.HEAD, byNameVersion("blood moon helm", "New"));
			gear.put(GearSlot.BODY, byNameVersion("blood moon chestplate", "New"));
			gear.put(GearSlot.LEGS, byNameVersion("blood moon tassets", "New"));
		}
		return new DpsCalculator().calculate(request(), new Loadout(gear));
	}

	@Test
	@DisplayName("the macuahuitl's second hit is chained - expected damage is below a single roll of the full max")
	void chainedHitsExpectation()
	{
		DpsResult result = calc(false);
		double acc = result.getAccuracy();
		int max = result.getMaxHit();
		int firstMax = max / 2;
		int secondMax = max - firstMax;
		double chained = RollMath.normalExpectedHit(acc, firstMax)
			+ acc * RollMath.normalExpectedHit(acc, secondMax);
		assertEquals(chained, result.getExpectedHit(), 1e-9);
		// Strictly below the naive one-hit model whenever accuracy < 1.
		assertTrue(acc < 1.0, "test premise: ankou defends a little");
		assertTrue(result.getExpectedHit() < RollMath.normalExpectedHit(acc, max));
	}

	@Test
	@DisplayName("Bloodrager: the full blood moon set speeds the macuahuitl up by acc/3 + acc^2*2/9 ticks")
	void bloodragerExpectedSpeed()
	{
		DpsResult bare = calc(false);
		DpsResult set = calc(true);
		double acc = set.getAccuracy();
		double proc = acc / 3.0 + acc * acc * 2.0 / 9.0;
		// dps identity: expected damage over the EXPECTED interval, while
		// the displayed speed stays the base 4t.
		assertEquals(set.getExpectedHit() / ((4 - proc) * RollMath.SECONDS_PER_TICK),
			set.getDps(), 1e-9);
		assertEquals(4, set.getAttackSpeed());
		// The set effect is a real dps gain over the same weapon bare
		// (armour also shifts accuracy, so compare per-attack rates).
		assertTrue(set.getDps() * set.getExpectedHit() > 0);
		assertTrue(bare.getDps() > 0);
		// The chip must NAME the folded-in multiplier (audit A2.12).
		assertTrue(set.getCountedBonuses().stream()
			.anyMatch(line -> line.toLowerCase().contains("bloodrager")));
		assertTrue(bare.getCountedBonuses().stream()
			.noneMatch(line -> line.toLowerCase().contains("bloodrager")));
	}

	@Test
	@DisplayName("Used and Broken blood moon pieces still trigger Bloodrager (wiki: works while broken)")
	void brokenPiecesStillCount()
	{
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byNameVersion("dual macuahuitl", null));
		gear.put(GearSlot.HEAD, byNameVersion("blood moon helm", "Broken"));
		gear.put(GearSlot.BODY, byNameVersion("blood moon chestplate", "Used"));
		gear.put(GearSlot.LEGS, byNameVersion("blood moon tassets", "Broken"));
		DpsResult result = new DpsCalculator().calculate(request(), new Loadout(gear));
		assertTrue(result.getCountedBonuses().stream()
			.anyMatch(line -> line.toLowerCase().contains("bloodrager")));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class BlowpipeTest
{
	@Test
	public void blowpipeWithDragonDartsBeatsBareThrownDarts()
	{
		LoadoutData data = new DataService().load();
		MonsterStats hydra = data.searchMonsters("alchemical hydra", 1).get(0);
		OptimizationRequest game = new OptimizationRequest(
			hydra, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 3);
		List<DpsResult> results = new LoadoutOptimizer().optimize(data, game);
		Assert.assertFalse(results.isEmpty());
		for (DpsResult r : results)
		{
			Assert.assertFalse("bare thrown darts must never outrank a loaded blowpipe: "
					+ r.getLoadout().getWeapon().getName(),
				r.getLoadout().getWeapon().getName().endsWith(" dart"));
		}
	}

	@Test
	public void ownedBlowpipeUsesTheBestOwnedDartTierAndNeedsDarts()
	{
		LoadoutData data = new DataService().load();
		MonsterStats hydra = data.searchMonsters("alchemical hydra", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(12926, 1);  // toxic blowpipe (charged)
		owned.put(811, 500);  // rune darts
		OptimizationRequest request = new OptimizationRequest(
			hydra, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 1);
		DpsResult withRune = new LoadoutOptimizer().optimize(data, request).get(0);
		Assert.assertTrue(withRune.getAttackType().contains("rune darts"));

		owned.put(11230, 500); // dragon darts: better tier takes over
		DpsResult withDragon = new LoadoutOptimizer().optimize(data, new OptimizationRequest(
			hydra, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 1)).get(0);
		Assert.assertTrue(withDragon.getAttackType().contains("dragon darts"));
		Assert.assertTrue(withDragon.getDps() > withRune.getDps());
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellStats;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Flat max-hit bonuses on elemental spells (wiki, verified 2026-09-08 against
 * the official calculator's PlayerVsNPCCalc): chaos gauntlets +3 on any bolt
 * spell; the elemental amulet +2 on any elemental spell; an amulet of air /
 * water / earth / fire +2 on its own element. All added BEFORE the magic
 * damage percentage. Field report: Mike, Discord, 2026-09-07.
 */
class BoltSpellModifiersTest
{
	private static LoadoutData data;
	private static MonsterStats goblin;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
		goblin = data.searchMonsters("Goblin", 1).iterator().next();
	}

	private static GearItem byName(String nameLower)
	{
		for (GearItem g : data.getGearItems())
		{
			if (g.getNameLower().equals(nameLower))
			{
				return g;
			}
		}
		throw new AssertionError("missing from the gear data: " + nameLower);
	}

	private static SpellStats spell(String name)
	{
		return data.getSpells().stream().filter(s -> s.getName().equals(name)).findFirst()
			.orElseThrow(() -> new AssertionError("missing spell " + name));
	}

	/** Max hit for a spell on a staff of fire, plus any named extras. */
	@Test
	@DisplayName("Salarin honours the elemental amulet alone: strikes stay a flat 12 for every other item, 14 with it")
	void salarin()
	{
		MonsterStats salarin = data.searchMonsters("Salarin", 1).iterator().next();
		assertEquals(12, maxHitVs(salarin, "Fire Strike"));
		assertEquals(12, maxHitVs(salarin, "Fire Strike", "occult necklace"), "spell damage items do nothing");
		assertEquals(14, maxHitVs(salarin, "Fire Strike", "elemental amulet"), "the sole exception (wiki)");
		assertEquals(12, maxHitVs(salarin, "Fire Strike", "amulet of fire"), "the wiki names the elemental amulet only");
		assertEquals(14, maxHitVs(salarin, "Wind Strike", "elemental amulet"), "every strike is treated as the top bolt");
	}

	private static int maxHit(String spellName, String... extras)
	{
		return maxHitVs(goblin, spellName, extras);
	}

	private static int maxHitVs(MonsterStats monster, String spellName, String... extras)
	{
		OptimizationRequest request = TestRequests.of(monster, CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.NONE, spell(spellName), 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		EnumMap<GearSlot, GearItem> worn = new EnumMap<>(GearSlot.class);
		worn.put(GearSlot.WEAPON, byName("staff of fire"));
		for (String extra : extras)
		{
			GearItem item = byName(extra);
			worn.put(item.getSlot(), item);
		}
		return new DpsCalculator().calculate(request, new Loadout(worn)).getMaxHit();
	}

	@Test
	@DisplayName("chaos gauntlets add 3 to a bolt spell and nothing to a strike")
	void chaosGauntlets()
	{
		assertEquals(12, maxHit("Fire Bolt"), "Fire Bolt at 99 Magic");
		assertEquals(15, maxHit("Fire Bolt", "chaos gauntlets"));
		assertEquals(8, maxHit("Fire Strike"));
		assertEquals(8, maxHit("Fire Strike", "chaos gauntlets"));
	}

	@Test
	@DisplayName("the elemental amulet adds 2 to every elemental spell and stacks with the gauntlets")
	void elementalAmulet()
	{
		assertEquals(14, maxHit("Fire Bolt", "elemental amulet"));
		assertEquals(17, maxHit("Fire Bolt", "chaos gauntlets", "elemental amulet"));
		assertEquals(10, maxHit("Fire Strike", "elemental amulet"));
		assertEquals(26, maxHit("Wind Surge", "elemental amulet"));
	}

	@Test
	@DisplayName("an element amulet only lifts its own element")
	void elementAmulets()
	{
		assertEquals(14, maxHit("Fire Bolt", "amulet of fire"));
		assertEquals(12, maxHit("Fire Bolt", "amulet of air"));
		assertEquals(14, maxHit("Wind Bolt", "amulet of air"));
		// June 2025 rebalance: every Blast hits 16 at 99 Magic; the amulet adds 2.
		assertEquals(18, maxHit("Water Blast", "amulet of water"));
		assertEquals(18, maxHit("Earth Blast", "amulet of earth"));
		assertEquals(16, maxHit("Earth Blast", "amulet of water"));
	}
}

package com.loadoutlab.engine;

import org.junit.Assert;
import org.junit.Test;

/**
 * Equivalence sweep for the table-driven BoostProfile.apply(): the OLD
 * hardcoded per-constant switch is kept here verbatim and compared against
 * the live one over every constant at every level 1..126. Test source is
 * free of the plugin-hub token cap, so this stays as the permanent guard
 * that the (flat, factor, skills) encoding still reproduces the original
 * numbers - including MAGIC's flat +4 as factor 0.0 and NONE's same-instance
 * identity return.
 */
public class BoostProfileSweepTest
{
	private static int boost(int level, int base, double factor)
	{
		return (int) Math.floor(base + level * factor);
	}

	/** Verbatim copy of the pre-refactor apply() body. */
	private static PlayerLevels oldApply(BoostProfile profile, PlayerLevels base, PlayerLevels current)
	{
		PlayerLevels source = base == null ? PlayerLevels.MAXED : base;
		switch (profile)
		{
			case LIVE_CURRENT:
				return current == null ? source : current;
			case F2P_COMBAT:
				return source.withBoosts(
					boost(source.getAttack(), 3, 0.10),
					boost(source.getStrength(), 3, 0.10),
					0,
					0,
					0);
			case SUPER_COMBAT:
			case DIVINE_SUPER_COMBAT: // added 2026-07-21: same numbers as the base
				return source.withBoosts(
					boost(source.getAttack(), 5, 0.15),
					boost(source.getStrength(), 5, 0.15),
					boost(source.getDefence(), 5, 0.15),
					0,
					0);
			case RANGING:
			case DIVINE_RANGING: // added 2026-07-21: same numbers as the base
			case BASTION: // added 2026-08-21: ranging numbers, defence unmodeled
			case DIVINE_BASTION: // added 2026-08-26: same numbers, divine label
				return source.withBoosts(0, 0, 0, boost(source.getRanged(), 4, 0.10), 0);
			case SUPER_RANGING:
				return source.withBoosts(0, 0, 0, boost(source.getRanged(), 5, 0.15), 0);
			case SATURATED_HEART:
				return source.withBoosts(0, 0, 0, 0, boost(source.getMagic(), 4, 0.10));
			case IMBUED_HEART:
				return source.withBoosts(0, 0, 0, 0, boost(source.getMagic(), 1, 0.10));
			case MAGIC:
			case DIVINE_MAGIC: // added 2026-07-21: same numbers as the base
			case BATTLEMAGE: // added 2026-08-21: magic potion's +4, defence unmodeled
			case DIVINE_BATTLEMAGE: // added 2026-08-26: same numbers, divine label
				return source.withBoosts(0, 0, 0, 0, 4);
			case SUPER_MAGIC:
				return source.withBoosts(0, 0, 0, 0, boost(source.getMagic(), 5, 0.15));
			case OVERLOAD:
				return source.withBoosts(
					boost(source.getAttack(), 5, 0.13),
					boost(source.getStrength(), 5, 0.13),
					boost(source.getDefence(), 5, 0.13),
					boost(source.getRanged(), 5, 0.13),
					boost(source.getMagic(), 5, 0.13));
			case OVERLOAD_PLUS:
				return source.withBoosts(
					boost(source.getAttack(), 6, 0.16),
					boost(source.getStrength(), 6, 0.16),
					boost(source.getDefence(), 6, 0.16),
					boost(source.getRanged(), 6, 0.16),
					boost(source.getMagic(), 6, 0.16));
			case SMELLING_SALTS:
				return source.withBoosts(
					boost(source.getAttack(), 11, 0.16),
					boost(source.getStrength(), 11, 0.16),
					boost(source.getDefence(), 11, 0.16),
					boost(source.getRanged(), 11, 0.16),
					boost(source.getMagic(), 11, 0.16));
			case NONE:
			default:
				return source;
		}
	}

	@Test
	public void tableDrivenBoostsMatchTheOldPerConstantSwitchAtEveryLevel()
	{
		for (BoostProfile profile : BoostProfile.values())
		{
			for (int level = 1; level <= 126; level++)
			{
				// Asymmetric levels so a mis-wired skill letter cannot hide.
				PlayerLevels base = new PlayerLevels(level, level + 1, level + 2,
					level + 3, level + 4, level + 5, level + 6);
				PlayerLevels expected = oldApply(profile, base, null);
				PlayerLevels actual = profile.apply(base, null);
				String at = profile + " @ " + level;
				Assert.assertEquals(at, expected.getAttack(), actual.getAttack());
				Assert.assertEquals(at, expected.getStrength(), actual.getStrength());
				Assert.assertEquals(at, expected.getDefence(), actual.getDefence());
				Assert.assertEquals(at, expected.getRanged(), actual.getRanged());
				Assert.assertEquals(at, expected.getMagic(), actual.getMagic());
			}
		}
		// NONE must hand back the SAME instance, not an equal copy.
		PlayerLevels base = new PlayerLevels(70, 70, 70, 70, 70, 70, 70);
		Assert.assertSame(base, BoostProfile.NONE.apply(base, null));
		// LIVE_CURRENT still prefers the live levels, and falls back to base.
		PlayerLevels live = new PlayerLevels(80, 80, 80, 80, 80, 80, 80);
		Assert.assertSame(live, BoostProfile.LIVE_CURRENT.apply(base, live));
		Assert.assertSame(base, BoostProfile.LIVE_CURRENT.apply(base, null));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.MonsterDefences;
import com.loadoutlab.data.MonsterOffence;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.StatBlock;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import org.junit.Assert;
import org.junit.Test;

public class BossIncomingOverridesTest
{
	/** Graardor-shaped stats: atk 280 (+120), str 350 (+43), rng 350, 6t.
	 * The NPC formula derives a ranged max hit of 58 from these. */
	private static MonsterOffence offence(List<String> styles)
	{
		return new MonsterOffence(280, 350, 350, 80,
			120, 43, 100, 40, 0, 0, 6, styles);
	}

	private static MonsterStats named(String name, List<String> styles)
	{
		return versioned(name, "", styles);
	}

	private static MonsterStats versioned(String name, String version, List<String> styles)
	{
		return new MonsterStats(1, name, version, 600, 255, 4, 250, 80, 0,
			MonsterDefences.ZERO, offence(styles),
			java.util.Collections.emptyList(), false, "", 0);
	}

	private static Loadout armour(int stab, int slash, int crush, int magic, int ranged)
	{
		GearItem body = new GearItem(1, "Test platebody", "", GearSlot.BODY, "", 0,
			false, true, true, true, 0,
			StatBlock.ZERO,
			new StatBlock(stab, slash, crush, magic, ranged, 0, 0, 0, 0),
			StatBlock.ZERO, null);
		return new Loadout(Map.of(GearSlot.BODY, body));
	}

	private static IncomingDpsCalculator.StyleThreat threat(
		IncomingDpsCalculator.Result result, String style)
	{
		for (IncomingDpsCalculator.StyleThreat t : result.threats)
		{
			if (t.style.toLowerCase(Locale.ROOT).equals(style))
			{
				return t;
			}
		}
		Assert.fail("no " + style + " threat in " + result.threats.size() + " threats");
		return null;
	}

	@Test
	public void overrideReplacesTheDerivedMaxHitWithGraardorsScripted35Ranged()
	{
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			named("General Graardor", Arrays.asList("Crush", "Ranged")),
			armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertTrue(result.fullyModeled);
		Assert.assertNotNull(result.overrideNote);
		Assert.assertEquals(35, threat(result, "ranged").maxHit);
		Assert.assertEquals(60, threat(result, "crush").maxHit);
		// Crush owns 2/3 of the cadence, so it is the prayed style.
		Assert.assertEquals("Protect from Melee", result.protectPrayer);
		Assert.assertTrue(threat(result, "crush").blocked);
	}

	@Test
	public void krakenRollsMagicAccuracyButPiercesPrayer()
	{
		// Wiki: "uses typeless Magic, and as such Protect from Magic does
		// not provide any degree of damage reduction", yet it "can hit very
		// hard [28] but has very poor accuracy" - so the model is a normal
		// magic ACCURACY roll (magic defence gear is the real mitigation)
		// whose damage pierces prayer entirely (field report 2026-07-17).
		IncomingDpsCalculator.Result tanky = IncomingDpsCalculator.calculate(
			named("Kraken", Arrays.asList("Typeless Magic")),
			armour(0, 0, 0, 400, 0), 99, 99);
		Assert.assertTrue(tanky.fullyModeled);
		Assert.assertNull(tanky.protectPrayer);
		Assert.assertTrue(tanky.unprayedDps > 0);
		Assert.assertEquals(tanky.unprayedDps, tanky.totalDps, 1e-9);
		Assert.assertEquals(28, threat(tanky, "magic").maxHit);
		// The accuracy roll is real: magic defence lowers the number.
		IncomingDpsCalculator.Result naked = IncomingDpsCalculator.calculate(
			named("Kraken", Arrays.asList("Typeless Magic")),
			armour(0, 0, 0, 0, 0), 99, 99);
		Assert.assertTrue(tanky.totalDps < naked.totalDps);
	}

	@Test
	public void partialPierceAttacksAlwaysContributeSomething()
	{
		// Corporeal Beast: magic carries TRUE max 65 with prayerFactor
		// 0.667 - whichever prayer is chosen, the prayed total must equal
		// the per-threat identity sum and stay strictly positive.
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			named("Corporeal Beast", Arrays.asList("Crush", "Magic")),
			armour(200, 200, 200, 0, 150), 99, 99);
		IncomingDpsCalculator.StyleThreat magic = threat(result, "magic");
		Assert.assertEquals(65, magic.maxHit);
		double identity = 0;
		for (IncomingDpsCalculator.StyleThreat threat : result.threats)
		{
			identity += threat.dps * threat.share * (threat.blocked ? threat.prayerFactor : 1);
		}
		Assert.assertEquals(identity, result.totalDps, 1e-9);
		Assert.assertTrue(result.totalDps > 0);
		Assert.assertTrue(result.totalDps < result.unprayedDps);
	}

	@Test
	public void rotationSharesWeightEachStylesContributionToTheTotal()
	{
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			named("General Graardor", Arrays.asList("Crush", "Ranged")),
			armour(200, 200, 200, 0, 150), 99, 99);
		IncomingDpsCalculator.StyleThreat crush = threat(result, "crush");
		IncomingDpsCalculator.StyleThreat ranged = threat(result, "ranged");
		Assert.assertEquals(0.667, crush.share, 1e-9);
		Assert.assertEquals(0.333, ranged.share, 1e-9);
		Assert.assertEquals(crush.dps * 0.667 + ranged.dps * 0.333,
			result.unprayedDps, 1e-9);
		// Crush is blocked, so the total is the ranged share alone.
		Assert.assertEquals(ranged.dps * 0.333, result.totalDps, 1e-9);
	}

	@Test
	public void typelessChipDamageIsModeledAsAlwaysHittingAndNeverBlocked()
	{
		// King Black Dragon: dragonfire (65 and 50) is typeless - accuracy 1
		// against any armour, contributing at its share regardless of prayer.
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			named("King Black Dragon", Arrays.asList("Stab", "Dragonfire")),
			armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertTrue(result.fullyModeled);
		Assert.assertEquals("Protect from Melee", result.protectPrayer);
		IncomingDpsCalculator.StyleThreat fire = threat(result, "typeless");
		Assert.assertEquals(65, fire.maxHit);
		// Always hits: dps is maxHit/2 per 6t sheet speed with no accuracy term.
		Assert.assertEquals((65 / 2.0) / (6 * 0.6), fire.dps, 1e-9);
		Assert.assertTrue(result.totalDps > 0);
	}

	@Test
	public void monstersWithoutAnOverrideKeepTheUniformV1Model()
	{
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			named("Test Boss", Arrays.asList("Crush", "Ranged")),
			armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertNull(result.overrideNote);
		// v1 derives the ranged max hit (58) from the stat sheet.
		Assert.assertEquals(58, threat(result, "ranged").maxHit);
		Assert.assertEquals(0.5, threat(result, "crush").share, 1e-9);
	}

	@Test
	public void zulrahFormsCarryTheirOwnAttacksAndPrayers()
	{
		// Field bug 2026-07-17: the name-keyed whole-fight entry told every
		// form to pray mage. Version-keyed entries give each form ITS OWN
		// protect prayer; the bare name stays as the whole-fight fallback.
		IncomingDpsCalculator.Result serp = IncomingDpsCalculator.calculate(
			versioned("Zulrah", "Serpentine", Arrays.asList("Ranged")),
			armour(0, 0, 0, 0, 0), 99, 99);
		Assert.assertEquals("Protect from Missiles", serp.protectPrayer);
		Assert.assertEquals(0.0, serp.totalDps, 1e-9);

		// The blue form carries BOTH books - the prayer pick maximizes
		// savings for YOUR gear: heavy ranged defence leaves magic as the
		// bigger threat (pray mage), heavy magic defence flips it. A
		// symmetric offence isolates the armour-driven flip.
		MonsterStats tanzanite = new MonsterStats(1, "Zulrah", "Tanzanite",
			600, 255, 4, 250, 80, 0, MonsterDefences.ZERO,
			new MonsterOffence(1, 1, 300, 300, 0, 0, 50, 0, 50, 0, 4,
				Arrays.asList("Magic", "Ranged")),
			java.util.Collections.emptyList(), false, "", 0);
		IncomingDpsCalculator.Result tanzRangedTank = IncomingDpsCalculator.calculate(
			tanzanite, armour(0, 0, 0, 0, 400), 99, 99);
		Assert.assertEquals("Protect from Magic", tanzRangedTank.protectPrayer);
		Assert.assertTrue("the unprayed half still lands", tanzRangedTank.totalDps > 0);
		IncomingDpsCalculator.Result tanzMageTank = IncomingDpsCalculator.calculate(
			tanzanite, armour(0, 0, 0, 400, 0), 99, 99);
		Assert.assertEquals("Protect from Missiles", tanzMageTank.protectPrayer);

		IncomingDpsCalculator.Result magma = IncomingDpsCalculator.calculate(
			versioned("Zulrah", "Magma", Arrays.asList("Typeless")),
			armour(0, 0, 0, 0, 0), 99, 99);
		Assert.assertNull("no prayer helps the tail slam", magma.protectPrayer);
		// Avoidable (field report: 'all of his attacks are dodgeable') -
		// the standard play takes zero; the tooltip keeps the undodged
		// value for context.
		Assert.assertEquals(0.0, magma.totalDps, 1e-9);
		Assert.assertEquals(0.0, magma.unprayedDps, 1e-9);
		IncomingDpsCalculator.StyleThreat slam =
			threat(magma, "typeless (avoidable - assumed dodged)");
		Assert.assertEquals(30, slam.maxHit);
		Assert.assertTrue("the undodged dps stays visible", slam.dps > 0);

		// The versionless fallback still answers (whole-fight mix).
		Assert.assertNotNull(IncomingDpsCalculator.calculate(
			named("Zulrah", Arrays.asList("Ranged", "Magic")),
			armour(0, 0, 0, 0, 0), 99, 99).protectPrayer);
	}

	/** The style whitelist BossIncomingOverrides.parse() used to enforce at
	 * load time. It moved here with the rest of the data validation: test
	 * source is free of the plugin-hub token cap, and the sweep below is
	 * coupled to a hardcoded boss list, so a newly added boss has to come
	 * through this check. */
	private static final java.util.Set<String> STYLES = java.util.Set.of(
		"melee", "stab", "slash", "crush", "ranged", "magic", "typeless");

	@Test
	public void everySeededBossIsPresentAndItsSharesSumToAtMostOne()
	{
		List<String> expected = Arrays.asList(
			"general graardor", "k'ril tsutsaroth", "kree'arra",
			"commander zilyana", "zulrah", "vorkath", "cerberus", "callisto",
			"artio", "vet'ion", "calvar'ion", "venenatis", "spindel",
			"chaos elemental", "king black dragon", "alchemical hydra",
			"corporeal beast", "kraken",
			"zulrah|serpentine", "zulrah|tanzanite", "zulrah|magma");
		for (String name : expected)
		{
			BossIncomingOverrides.BossOverride override = BossIncomingOverrides
				.overridesFor(named(name, List.of("Melee")));
			Assert.assertNotNull(name, override);
			// An EMPTY attack list would sail through the shares check below,
			// so demand attacks before looking at them.
			Assert.assertFalse(name + ": no attacks", override.getAttacks().isEmpty());
			double shares = 0;
			for (BossIncomingOverrides.Attack attack : override.getAttacks())
			{
				Assert.assertTrue(name + ": unknown style " + attack.getStyle(),
					STYLES.contains(attack.getStyle()));
				Assert.assertTrue(name, attack.getMaxHit() > 0);
				Assert.assertTrue(name, attack.getShare() > 0);
				Assert.assertTrue(name, attack.getShare() <= 1.0);
				Assert.assertTrue(name, attack.getSpeedTicks() >= 0);
				Assert.assertTrue(name + ": prayerFactor out of range",
					attack.getPrayerFactor() >= 0 && attack.getPrayerFactor() <= 1);
				if ("typeless".equals(attack.getStyle()))
				{
					Assert.assertFalse(name, attack.isPrayable());
				}
				shares += attack.getShare();
			}
			Assert.assertTrue(name + " shares " + shares, shares <= 1.0 + 1e-9);
		}
		Assert.assertEquals(expected.size(), BossIncomingOverrides.names().size());
	}

	@Test
	public void fullyPrayerPiercingBossesRecommendNoProtectionPrayer()
	{
		// Vet'ion's lightning and shield bash are dodge-based, not prayable:
		// no prayer recommendation, and praying changes nothing.
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			named("Vet'ion", Arrays.asList("Slash", "Magic")),
			armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertNull(result.protectPrayer);
		Assert.assertEquals(result.unprayedDps, result.totalDps, 1e-9);
		Assert.assertTrue(result.totalDps > 0);
	}

	@Test
	public void partialPrayerPierceCountsTheThroughDamage()
	{
		// Corp's magic: TRUE max 65, Protect from Magic blocks only 1/3
		// (factor 0.667). Prayed total must include the pierce-through;
		// unprayed must use the full 65-based dps.
		LoadoutData data = new DataService().load();
		MonsterStats corp = data.searchMonsters("corporeal beast", 1).get(0);
		// Heavy melee armour + zero magic defence: the magic saving must
		// dominate, so Protect from Magic gets prayed and the pierce shows.
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			corp, tankMeleeArmour(), 99, 99);
		Assert.assertEquals("Protect from Magic", result.protectPrayer);
		Assert.assertTrue(result.totalDps > 0);
		Assert.assertTrue(result.totalDps < result.unprayedDps);
		boolean sawPierce = false;
		for (IncomingDpsCalculator.StyleThreat threat : result.threats)
		{
			if (threat.blocked && threat.prayerFactor > 0)
			{
				sawPierce = true;
				Assert.assertEquals(65, threat.maxHit);
				Assert.assertEquals(0.667, threat.prayerFactor, 1e-9);
			}
		}
		Assert.assertTrue("corp magic must be a partial pierce", sawPierce);
	}

	@Test
	public void prayerChoiceMaximizesSavingsNotRawSize()
	{
		// Callisto: melee 55 but only half-blocked; magic 50 fully
		// blockable. Praying magic SAVES more than praying melee even
		// though the melee hit is bigger - the chosen prayer must be the
		// bigger saving.
		LoadoutData data = new DataService().load();
		MonsterStats callisto = data.searchMonsters("callisto", 1).get(0);
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			callisto, new Loadout(java.util.Map.of()), 99, 99);
		Assert.assertEquals("Protect from Magic", result.protectPrayer);
	}

	private static Loadout tankMeleeArmour()
	{
		com.loadoutlab.data.GearItem body = new com.loadoutlab.data.GearItem(
			99, "Tank platebody", "", com.loadoutlab.data.GearSlot.BODY, "", 0,
			false, true, true, true, 0,
			com.loadoutlab.data.StatBlock.ZERO,
			new com.loadoutlab.data.StatBlock(500, 500, 500, 0, 0, 0, 0, 0, 0),
			com.loadoutlab.data.StatBlock.ZERO, null);
		return new Loadout(java.util.Map.of(com.loadoutlab.data.GearSlot.BODY, body));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import org.junit.Assert;
import org.junit.Test;

/**
 * Crystal armour scaling for the crystal bow / bow of faerdhinen, verified
 * against the official wiki calculator engine (scripts/verify_official.py:
 * bofa-graardor, bofahelm/body/legs/set-graardor, cbowset-graardor and
 * bofasetslayer-graardor all at 0.0% delta):
 *
 *   accuracy roll x(20+n)/20, max hit x(40+n)/40
 *   where n = helm 1, legs 2, body 3 (full set: +30% accuracy, +15% damage)
 *
 * The multiplier applies to the BASE roll/max hit, before salve/slayer
 * (flooring order verified in-game by the wiki calc devs). Inactive pieces
 * give nothing, and only the two bows scale - not the blade or halberd.
 */
public class CrystalSetTest
{
	@Test
	public void eachCrystalPieceScalesTheBofaByItsExactWeight()
	{
		LoadoutData data = new DataService().load();
		OptimizationRequest request = request(data, false);
		DpsResult bare = calc(data, request, "Bow of faerdhinen", null, null);
		assertExactScaling(data, request, bare, 1, "Crystal helm");
		assertExactScaling(data, request, bare, 2, "Crystal legs");
		assertExactScaling(data, request, bare, 3, "Crystal body");
		assertExactScaling(data, request, bare, 6, "Crystal helm", "Crystal body", "Crystal legs");
	}

	@Test
	public void fullCrystalSetBoostsTheCrystalBowByThirtyAccFifteenDamage()
	{
		LoadoutData data = new DataService().load();
		OptimizationRequest request = request(data, false);
		DpsResult bare = calc(data, request, "Crystal bow", null, null);
		DpsResult withSet = calc(data, request, "Crystal bow", null,
			new String[]{"Crystal helm", "Crystal body", "Crystal legs"});
		Assert.assertEquals(expectedRoll(bare, withSet, 6), withSet.getAttackRoll());
		Assert.assertEquals(bare.getMaxHit() * 46 / 40, withSet.getMaxHit());
		Assert.assertTrue(withSet.getDps() > bare.getDps() * 1.15);
	}

	@Test
	public void inactiveCrystalPiecesGiveTheBofaNothing()
	{
		LoadoutData data = new DataService().load();
		OptimizationRequest request = request(data, false);
		DpsResult bare = calc(data, request, "Bow of faerdhinen", null, null);
		DpsResult withInactive = calc(data, request, "Bow of faerdhinen", "Inactive",
			new String[]{"Crystal helm", "Crystal body", "Crystal legs"});
		// Inactive pieces have zero bonuses AND must not count for scaling.
		Assert.assertEquals(bare.getAttackRoll(), withInactive.getAttackRoll());
		Assert.assertEquals(bare.getMaxHit(), withInactive.getMaxHit());
	}

	@Test
	public void crystalScalingFloorsBeforeTheSlayerHelmMultiplier()
	{
		// The wiki calc devs verified in-game that crystal applies to the
		// base max hit before the slayer helm multiplier; the reverse order
		// gives a max hit one higher at these stats.
		LoadoutData data = new DataService().load();
		OptimizationRequest request = request(data, true);
		DpsResult bare = calc(data, request, "Bow of faerdhinen", null, null);
		DpsResult slayerSet = calc(data, request, "Bow of faerdhinen", null,
			new String[]{"Slayer helmet (i)", "Crystal body", "Crystal legs"});
		int base = bare.getMaxHit();
		int crystalFirst = (base * 45 / 40) * 23 / 20;
		int slayerFirst = (base * 23 / 20) * 45 / 40;
		Assert.assertNotEquals("pick stats where the flooring order matters", crystalFirst, slayerFirst);
		Assert.assertEquals(crystalFirst, slayerSet.getMaxHit());
	}

	@Test
	public void crystalArmourDoesNotScaleTheBladeOfSaeldor()
	{
		LoadoutData data = new DataService().load();
		MonsterStats graardor = data.searchMonsters("general graardor", 1).get(0);
		OptimizationRequest request = new OptimizationRequest(
			graardor, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
		DpsResult bare = calc(data, request, "Blade of saeldor", null, null);
		DpsResult withSet = calc(data, request, "Blade of saeldor", null,
			new String[]{"Crystal helm", "Crystal body", "Crystal legs"});
		Assert.assertEquals(bare.getMaxHit(), withSet.getMaxHit());
	}

	private static void assertExactScaling(LoadoutData data, OptimizationRequest request,
		DpsResult bare, int pieces, String... armour)
	{
		DpsResult result = calc(data, request, "Bow of faerdhinen", null, armour);
		Assert.assertEquals(String.join("+", armour) + " accuracy",
			expectedRoll(bare, result, pieces), result.getAttackRoll());
		// Crystal armour has no ranged strength, so the base max is shared.
		Assert.assertEquals(String.join("+", armour) + " ranged strength",
			bare.getLoadout().getBonuses().getRangedStrength(),
			result.getLoadout().getBonuses().getRangedStrength());
		Assert.assertEquals(String.join("+", armour) + " max hit",
			bare.getMaxHit() * (40 + pieces) / 40, result.getMaxHit());
	}

	/**
	 * Roll = effectiveLevel x (rangedAttack + 64), crystal-scaled before any
	 * other multiplier. Derive the effective level from the bare bow's roll
	 * (identity multiplier), then rebuild the scaled loadout's expectation.
	 */
	private static long expectedRoll(DpsResult bare, DpsResult scaled, int pieces)
	{
		long bareBonus = bare.getLoadout().getOffensive().getRanged() + 64;
		Assert.assertEquals("effective level derivation", 0, bare.getAttackRoll() % bareBonus);
		long effective = bare.getAttackRoll() / bareBonus;
		long scaledBonus = scaled.getLoadout().getOffensive().getRanged() + 64;
		return effective * scaledBonus * (20 + pieces) / 20;
	}

	private static OptimizationRequest request(LoadoutData data, boolean onTask)
	{
		MonsterStats graardor = data.searchMonsters("general graardor", 1).get(0);
		return new OptimizationRequest(
			graardor, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, onTask,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
	}

	private static DpsResult calc(LoadoutData data, OptimizationRequest request,
		String weapon, String armourVersion, String[] armour)
	{
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byName(data, weapon, null));
		if (armour != null)
		{
			for (String name : armour)
			{
				GearItem item = byName(data, name, armourVersion);
				gear.put(item.getSlot(), item);
			}
		}
		return new DpsCalculator().calculate(request, new Loadout(gear));
	}

	private static GearItem byName(LoadoutData data, String name, String version)
	{
		return data.getGearItems().stream()
			.filter(g -> g.getName().equalsIgnoreCase(name))
			.filter(g -> version == null ? g.isStandardGear() : version.equalsIgnoreCase(g.getVersion()))
			.findFirst().orElseThrow(() -> new AssertionError("missing " + name));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import org.junit.Assert;
import org.junit.Test;

/**
 * Demonbane effectiveness is PER MONSTER (wiki; mirrors the official
 * calc's demonbaneVulnerability): Duke Sucellus resists at 70%, so
 * Emberlight's +70% accuracy/damage lands as +49%. Field report
 * 2026-08-12 (rncq via Discord): "for duke the dmg is wrong ... duke
 * has a bit of resistance towards emberlight".
 */
public class DemonbaneVulnerabilityTest
{
	private static LoadoutData data;

	private static LoadoutData data()
	{
		if (data == null)
		{
			data = new DataService().load();
		}
		return data;
	}

	private static GearItem byName(String nameLower)
	{
		return data().getGearItems().stream()
			.filter(g -> g.getNameLower().equals(nameLower) && g.isStandardGear())
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + nameLower));
	}

	private static DpsResult emberlightVs(String monster)
	{
		MonsterStats mob = data().searchMonsters(monster, 1).get(0);
		OptimizationRequest request = TestRequests.of(mob, CombatStyle.MELEE,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byName("emberlight"));
		DpsResult result = new DpsCalculator().calculate(request, new Loadout(gear));
		Assert.assertNotNull(result);
		return result;
	}

	@Test
	public void dukeResistsDemonbaneAtSeventyPercent()
	{
		MonsterStats duke = data().searchMonsters("duke sucellus", 1).get(0);
		Assert.assertTrue("duke must be a demon for the bonus to apply at all",
			duke.hasAttribute("demon"));
		Assert.assertEquals(70, DemonbaneVulnerability.percentFor(duke));
		// 70% bonus x 70% effectiveness = +49%.
		Assert.assertEquals(49, DemonbaneVulnerability.scaledBonus(duke, 70));
	}

	@Test
	public void theResistedBonusIsWhatTheEngineApplies()
	{
		MonsterStats duke = data().searchMonsters("duke sucellus", 1).get(0);
		DpsResult resisted = emberlightVs("duke sucellus");
		// Rebuild the unresisted max hit the old code produced and prove
		// the shown one is strictly lower (the field report's "damage
		// discrepancy") yet still above the no-demonbane baseline.
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byName("emberlight"));
		OptimizationRequest plain = TestRequests.of(
			data().searchMonsters("abyssal demon", 1).get(0), CombatStyle.MELEE,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		DpsResult fullBonus = new DpsCalculator().calculate(plain, new Loadout(gear));
		Assert.assertNotNull(fullBonus);
		Assert.assertTrue("Duke's max hit must sit BELOW a full-effectiveness demon's: "
				+ resisted.getMaxHit() + " vs " + fullBonus.getMaxHit(),
			resisted.getMaxHit() < fullBonus.getMaxHit());
		Assert.assertTrue("but still above the unbuffed baseline",
			resisted.getMaxHit() > fullBonus.getMaxHit() * 100 / 170);
		Assert.assertEquals(70, DemonbaneVulnerability.percentFor(duke));
	}

	@Test
	public void unlistedMonstersKeepFullEffectiveness()
	{
		Assert.assertEquals(100, DemonbaneVulnerability.percentFor(
			data().searchMonsters("abyssal demon", 1).get(0)));
		Assert.assertEquals(70, DemonbaneVulnerability.scaledBonus(
			data().searchMonsters("abyssal demon", 1).get(0), 70));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Dragonfire honesty (2026-07 player audit A3.2): when the shield-required
 * constraint CANNOT be satisfied (no protective shield in the pool), the
 * beam used to half-apply it - every two-handed weapon banned AND the
 * returned set still had an empty shield, with pure-damage items (Ultor,
 * Avernic) unrecoverable by the neutral fill. A maxed player's Vorkath
 * magic card showed a 2.71-dps Sanguinesti while their Shadow computed
 * ~7.5. Now the constraint is all-or-nothing: unsatisfiable means the
 * UNCONSTRAINED set comes back flagged antifire-assumed, so the panel can
 * say "needs a super antifire" instead of quietly recommending nonsense.
 */
class DragonfireHonestyTest
{
	private static LoadoutData data;
	private static MonsterStats vorkath;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
		vorkath = data.searchMonsters("vorkath", 1).get(0);
		assertEquals("", vorkath.getVersion(), "test premise: everyday Vorkath owns the bare name");
		assertTrue(DragonfireRules.breathesFire(vorkath));
	}

	private static GearItem byName(String nameLower, String versionLower)
	{
		for (GearItem item : data.getGearItems())
		{
			if (item.getNameLower().equals(nameLower)
				&& (versionLower == null || versionLower.equals(item.getVersionLower())))
			{
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + nameLower);
	}

	private static OptimizationRequest owning(CombatStyle style, GearItem... items)
	{
		Map<Integer, Integer> owned = new HashMap<>();
		for (GearItem item : items)
		{
			owned.put(item.getId(), 1);
		}
		return new OptimizationRequest(vorkath, style, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 3);
	}

	@Test
	@DisplayName("no protective shield owned: the 2h Shadow comes back, flagged antifire-assumed")
	void unsatisfiableConstraintFallsBackHonestly()
	{
		GearItem shadow = byName("tumeken's shadow", "charged");
		List<DpsResult> results = new LoadoutOptimizer().optimize(data, owning(CombatStyle.MAGIC, shadow));
		assertFalse(results.isEmpty(), "the shadow line must not die");
		assertEquals("tumeken's shadow", results.get(0).getLoadout().getWeapon().getNameLower());
		assertTrue(results.get(0).isAntifireAssumed(),
			"the result must confess it assumes a super antifire");
	}

	@Test
	@DisplayName("a protective shield owned: the constraint applies and nothing is assumed")
	void satisfiableConstraintStaysHonest()
	{
		GearItem sang = byName("sanguinesti staff", "charged");
		GearItem antiDragon = byName("anti-dragon shield", null);
		List<DpsResult> results = new LoadoutOptimizer().optimize(
			data, owning(CombatStyle.MAGIC, sang, antiDragon));
		assertFalse(results.isEmpty());
		DpsResult best = results.get(0);
		assertNotNull(best.getLoadout().get(com.loadoutlab.data.GearSlot.SHIELD),
			"protection must be worn");
		assertTrue(DragonfireRules.isProtectiveShield(
			best.getLoadout().get(com.loadoutlab.data.GearSlot.SHIELD)));
		assertFalse(best.isAntifireAssumed());
	}

	@Test
	@DisplayName("an explicit antifire potion is the user's own assumption - not flagged")
	void explicitPotionIsNotFlagged()
	{
		GearItem shadow = byName("tumeken's shadow", "charged");
		List<DpsResult> results = new LoadoutOptimizer().optimize(
			data, owning(CombatStyle.MAGIC, shadow).withAntifirePotion(true));
		assertFalse(results.isEmpty());
		assertEquals("tumeken's shadow", results.get(0).getLoadout().getWeapon().getNameLower());
		assertFalse(results.get(0).isAntifireAssumed());
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.List;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;

public class DragonfireRulesTest
{
	private static LoadoutData data;

	@BeforeClass
	public static void load()
	{
		data = new DataService().load();
	}

	private static MonsterStats monster(String name)
	{
		return data.searchMonsters(name, 1).get(0);
	}

	@Test
	public void firebreathersAreDetectedByTheirDragonfireStyleAndBabiesAreNot()
	{
		Assert.assertTrue(DragonfireRules.breathesFire(monster("green dragon")));
		Assert.assertTrue(DragonfireRules.breathesFire(monster("steel dragon")));
		Assert.assertTrue(DragonfireRules.breathesFire(monster("vorkath")));
		Assert.assertTrue(DragonfireRules.breathesFire(monster("king black dragon")));
		Assert.assertFalse(DragonfireRules.breathesFire(monster("baby black dragon")));
		Assert.assertFalse(DragonfireRules.breathesFire(monster("zulrah")));
	}

	@Test
	public void gearModeForcesAProtectiveShieldAndBansTwoHanders()
	{
		OptimizationRequest req = TestRequests.of(monster("vorkath"), CombatStyle.RANGED,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, 0, CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		List<DpsResult> out = new LoadoutOptimizer().optimize(data, req);
		Assert.assertFalse(out.isEmpty());
		GearItem shield = out.get(0).getLoadout().get(GearSlot.SHIELD);
		Assert.assertNotNull("gear mode must fill the shield slot", shield);
		Assert.assertTrue(shield.label() + " is not dragonfire-protective",
			DragonfireRules.isProtectiveShield(shield));
		Assert.assertFalse(out.get(0).getLoadout().getWeapon().isTwoHanded());
	}

	@Test
	public void thePotionToggleLiftsTheConstraintAndNeverCostsDps()
	{
		OptimizationRequest gear = TestRequests.of(monster("green dragon"), CombatStyle.MELEE,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, 0, CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		double shielded = new LoadoutOptimizer().optimize(data, gear).get(0).getDps();
		double potion = new LoadoutOptimizer().optimize(data, gear.withAntifirePotion(true)).get(0).getDps();
		Assert.assertTrue(potion >= shielded - 1e-9);
	}

	@Test
	public void nonDragonsAreUnaffectedByTheShieldRule()
	{
		OptimizationRequest req = TestRequests.of(monster("general graardor"), CombatStyle.MELEE,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, 0, CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		List<DpsResult> out = new LoadoutOptimizer().optimize(data, req);
		GearItem shield = out.get(0).getLoadout().get(GearSlot.SHIELD);
		Assert.assertTrue(shield == null || !DragonfireRules.isProtectiveShield(shield)
			|| out.get(0).getLoadout().getWeapon().isTwoHanded() == false);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Candidate pool semantics: candidates = (owned + dreams + within-budget
 * purchases) - exclusions.
 */
public class DreamAndBudgetTest
{
	private static LoadoutData data;
	private static MonsterStats zulrah;

	@BeforeClass
	public static void load()
	{
		data = new DataService().load();
		// Zulrah: magic 300, the twisted bow's home turf - a dreamed tbow
		// must dominate here (vs a low-magic monster it may honestly lose).
		zulrah = data.searchMonsters("zulrah", 1).get(0);
	}

	private static OptimizationRequest owned(Map<Integer, Integer> owned, int budgetGp)
	{
		return TestRequests.of(zulrah, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, budgetGp,
			budgetGp > 0 ? CandidateMode.OWNED_OR_BUDGET : CandidateMode.OWNED_ONLY,
			true, false, new OwnedItems(data.canonicalizeOwned(owned), true), 1);
	}

	@Test
	public void aDreamedTwistedBowJoinsAnOwnedOnlySearch()
	{
		// Owned: magic shortbow + rune arrows. Dreamed: a twisted bow.
		OptimizationRequest plain = owned(Map.of(861, 1, 892, 100), 0);
		OptimizationRequest dreaming = plain.withDreamItems(Set.of(20997)); // twisted bow
		DpsResult without = new LoadoutOptimizer().optimize(data, plain).get(0);
		DpsResult with = new LoadoutOptimizer().optimize(data, dreaming).get(0);
		Assert.assertEquals("Twisted bow", with.getLoadout().getWeapon().getName());
		Assert.assertTrue(with.getDps() > without.getDps());
	}

	@Test
	public void anExcludedDreamItemStaysOut()
	{
		OptimizationRequest req = owned(Map.of(861, 1, 892, 100), 0)
			.withDreamItems(Set.of(20997))
			.withExcludedItems(Set.of(20997));
		DpsResult best = new LoadoutOptimizer().optimize(data, req).get(0);
		Assert.assertNotEquals("Twisted bow", best.getLoadout().getWeapon().getName());
	}

	@Test
	public void aBudgetShopsUpgradesWithinTotalSpend()
	{
		// Own a maple shortbow + adamant arrows (rune arrows outclass the
		// bow's ammo tier); 1M budget must buy real upgrades but keep the
		// TOTAL purchase cost within budget.
		OptimizationRequest req = owned(Map.of(853, 1, 890, 100), 1_000_000);
		DpsResult best = new LoadoutOptimizer().optimize(data, req).get(0);
		OptimizationRequest plain = owned(Map.of(853, 1, 890, 100), 0);
		DpsResult without = new LoadoutOptimizer().optimize(data, plain).get(0);
		Assert.assertTrue(best.getDps() > without.getDps());
		Assert.assertTrue("spent " + best.getPurchaseCost(),
			best.getPurchaseCost() <= 1_000_000);
		// And something was actually bought.
		Assert.assertTrue(best.getPurchaseCost() > 0);
	}

	@Test
	public void dreamItemsDoNotChargeTheUpgradeBudget()
	{
		// 100k budget + dreamed tbow: the dream is pretend-owned (free),
		// the budget still shops small upgrades around it.
		OptimizationRequest req = owned(Map.of(892, 100), 100_000)
			.withDreamItems(Set.of(20997));
		DpsResult best = new LoadoutOptimizer().optimize(data, req).get(0);
		Assert.assertEquals("Twisted bow", best.getLoadout().getWeapon().getName());
		Assert.assertTrue(best.getPurchaseCost() <= 100_000);
	}
}

