package com.loadoutlab.engine;

import com.loadoutlab.optimizer.BoostSelector;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * F2P mode used to assume members consumables and prayers (2026-07 player
 * audit A3.5): Super combat / Ranging potion / Saturated heart labels on
 * F2P cards, and game-best prayers of Piety/Rigour/Augury that do not
 * exist on a free world. F2P assumptions now cap at the real F2P book
 * (everything through Mystic Might) and F2P potions (attack + strength).
 * Also locks A2.12: sub-31 prayer tiers are NAMED, not silently applied.
 */
class F2pAssumptionsTest
{
	@Test
	@DisplayName("the F2P prayer ceiling is the 1.15 tier, by name")
	void f2pPrayerCeiling()
	{
		PrayerBonuses f2p = PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.F2P);
		assertEquals("Incredible Reflexes + Ultimate Strength", f2p.nameFor(CombatStyle.MELEE));
		assertEquals("Eagle Eye", f2p.nameFor(CombatStyle.RANGED));
		assertEquals("Mystic Might", f2p.nameFor(CombatStyle.MAGIC));
	}

	@Test
	@DisplayName("F2P boosts: attack+strength potions for melee, nothing for ranged/magic")
	void f2pBoosts()
	{
		assertEquals(BoostProfile.F2P_COMBAT, BoostSelector.bestFor(CombatStyle.MELEE, OwnedItems.EMPTY, true, false));
		assertEquals(BoostProfile.NONE, BoostSelector.bestFor(CombatStyle.RANGED, OwnedItems.EMPTY, true, false));
		assertEquals(BoostProfile.NONE, BoostSelector.bestFor(CombatStyle.MAGIC, OwnedItems.EMPTY, true, false));
		assertEquals(BoostProfile.F2P_COMBAT, BoostSelector.ceilingFor(CombatStyle.MELEE, true));
		// Members with an EMPTY bank now assume nothing either (2026-08-25):
		// this line used to expect SUPER_COMBAT, which was the same defect the
		// ironman field report caught. The F2P assertions above are unaffected -
		// F2P_COMBAT is a mode ceiling, not an owned item.
		assertEquals(BoostProfile.NONE, BoostSelector.bestFor(CombatStyle.MELEE, OwnedItems.EMPTY, false, false));
	}

	@Test
	@DisplayName("attack/strength potions boost +3 plus 10% of the level")
	void f2pCombatPotionMath()
	{
		PlayerLevels boosted = BoostProfile.F2P_COMBAT.apply(PlayerLevels.MAXED, null);
		assertEquals(99 + 3 + 9, boosted.getAttack());
		assertEquals(99 + 3 + 9, boosted.getStrength());
		assertEquals(99, boosted.getRanged(), "no F2P ranged boost exists");
		assertEquals(99, boosted.getMagic(), "no F2P magic boost exists");
	}

	@Test
	@DisplayName("sub-31 prayer tiers are named in the assumes label (audit A2.12)")
	void lowTierPrayersAreNamed()
	{
		PlayerLevels low = new PlayerLevels(99, 99, 99, 99, 99, 16, 99);
		PrayerBonuses prayers = PrayerBonuses.bestAvailable(low, PrayerUnlocks.ALL);
		assertEquals("Improved Reflexes + Superhuman Strength", prayers.nameFor(CombatStyle.MELEE));
		assertEquals("Sharp Eye", prayers.nameFor(CombatStyle.RANGED));
		assertEquals("Mystic Will", prayers.nameFor(CombatStyle.MAGIC));

		PlayerLevels mid = new PlayerLevels(99, 99, 99, 99, 99, 27, 99);
		PrayerBonuses midPrayers = PrayerBonuses.bestAvailable(mid, PrayerUnlocks.ALL);
		assertEquals("Hawk Eye", midPrayers.nameFor(CombatStyle.RANGED));
		assertEquals("Mystic Lore", midPrayers.nameFor(CombatStyle.MAGIC));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import org.junit.Assert;
import org.junit.Test;

/**
 * Flat armour applies PER HITSPLAT (official calc: a hit-distribution
 * transformer on accurate hits). Blue Moon's -5 rewards multi-hit
 * weapons twice (wiki: "weapons which deal damage via multiple
 * hitsplats are particularly effective here" - field report
 * 2026-08-10: "double hits on blue moon is good"); Eclipse Moon's +6
 * punishes them twice. The old order split the macuahuitl's max AFTER
 * armour, crediting the -5 only once.
 */
public class FlatArmourPerHitTest
{
	private static LoadoutData data;

	private static LoadoutData data()
	{
		if (data == null)
		{
			data = new DataService().load();
		}
		return data;
	}

	private static GearItem byName(String nameLower)
	{
		return data().getGearItems().stream()
			.filter(g -> g.getNameLower().equals(nameLower) && g.isStandardGear())
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + nameLower));
	}

	private static DpsResult macuahuitlVs(String monster)
	{
		MonsterStats mob = data().searchMonsters(monster, 1).get(0);
		OptimizationRequest request = TestRequests.of(mob, CombatStyle.MELEE,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byName("dual macuahuitl"));
		DpsResult result = new DpsCalculator().calculate(request, new Loadout(gear));
		Assert.assertNotNull(result);
		return result;
	}

	@Test
	public void blueMoonCreditsTheMinusFiveOnBothHitsplats()
	{
		DpsResult result = macuahuitlVs("blue moon");
		// Each hitsplat carries its own +5, applied AFTER the accurate-
		// zero rule (a landed 0 counts as 1) - repinned 2026-08-21 from
		// the old bound-shift model, which dropped that bump and ran
		// 0.5% low; the harness vector macuahuitl-bluemoon is now exact.
		int rawMax = result.getMaxHit() - 5;
		int firstRaw = rawMax / 2;
		int secondRaw = rawMax - firstRaw;
		double acc = result.getAccuracy();
		double perHitExpected = RollMath.expectedHitWithFlatArmour(acc, 0, firstRaw, -5)
			+ acc * RollMath.expectedHitWithFlatArmour(acc, 0, secondRaw, -5);
		Assert.assertEquals("each hitsplat carries its own +5",
			perHitExpected, result.getExpectedHit(), 1e-9);
	}

	@Test
	public void eclipseMoonChargesTheArmourOnBothHitsplats()
	{
		MonsterStats mob = data().searchMonsters("eclipse moon", 1).get(0);
		int armour = mob.getDefensive().getFlatArmour();
		Assert.assertTrue("eclipse forms carry positive flat armour", armour > 0);
		DpsResult result = macuahuitlVs("eclipse moon");
		int rawMax = result.getMaxHit() + armour;
		int firstRaw = rawMax / 2;
		int secondRaw = rawMax - firstRaw;
		double acc = result.getAccuracy();
		// Per-roll clamp, NOT a bound shift (official-calc verified
		// 2026-08-21: the shifted model overpriced Eclipse ~16% - the
		// noxhalberd-eclipsemoon harness vector now matches to 0.00%).
		double perHitExpected = RollMath.expectedHitWithFlatArmour(acc, 0, firstRaw, armour)
			+ acc * RollMath.expectedHitWithFlatArmour(acc, 0, secondRaw, armour);
		Assert.assertEquals("each hitsplat pays the armour on every roll",
			perHitExpected, result.getExpectedHit(), 1e-9);
	}
}

