			.filter(g -> g.getName().equalsIgnoreCase(weaponName) && g.isStandardGear())
			.findFirst().orElseThrow(() -> new AssertionError("missing " + weaponName));
	}

	private static DpsResult calculate(MonsterStats monster, String weaponName)
	{
		GearItem weapon = weapon(weaponName);
		OptimizationRequest request = new OptimizationRequest(
			monster, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, weapon);
		return new DpsCalculator().calculate(request, new Loadout(gear));
	}

	@Test
	public void graniteHammerGolembaneBeatsTheTentacleAgainstDusk()
	{
		// Aug 2025: the granite hammer deals 30% extra damage AND accuracy
		// vs golem-type monsters (Dusk, Dawn, gargoyles...).
		MonsterStats dusk = data().searchMonsters("dusk", 1).get(0);
		Assert.assertTrue(dusk.hasAttribute("golem"));
		Assert.assertTrue(calculate(dusk, "Granite hammer").getDps()
			> calculate(dusk, "Abyssal tentacle").getDps());
	}

	@Test
	public void golembaneDoesNotApplyToNonGolems()
	{
		MonsterStats goblin = data().searchMonsters("goblin", 1).get(0);
		// Against a non-golem the hammer is just its stat sheet: the
		// tentacle wins comfortably.
		Assert.assertTrue(calculate(goblin, "Abyssal tentacle").getDps()
			> calculate(goblin, "Granite hammer").getDps());
	}

	@Test
	public void optimizerPicksTheHammerAtAGolem()
	{
		// The pool lesson, which the model tests above do NOT cover: golembane
		// lives in the DPS model, not in the hammer's raw stats (crush +57 /
		// str +56), so the weapon-pool cut dropped it before the bonus could
		// ever be applied. Field-found 2026-08-01 at the Mad Angel - a
		// Zamorakian hasta was suggested and the owned melee answer came in
		// ~2 dps low (6.58 vs 8.58).
		MonsterStats madAngel = data().searchMonsters("mad angel", 1).get(0);
		Assert.assertTrue(madAngel.hasAttribute("golem"));

		// The FULL standard pool is the point: the cut keeps 24 weapons by
		// raw score, and the hammer only survives it because of the golem
		// boost. A two-weapon owned pool would never reach the cut and would
		// re-prove the DPS model instead of the pool behaviour.
		OptimizationRequest request = new OptimizationRequest(
			madAngel, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 3);
		java.util.List<DpsResult> results = new LoadoutOptimizer().optimize(data(), request);
		Assert.assertFalse(results.isEmpty());
		Assert.assertEquals("granite hammer",
			results.get(0).getLoadout().getWeapon().getNameLower());
	}

	@Test
	public void barroniteMaceGetsItsFifteenPercentAgainstGolems()
	{
		// Grey golem: golem-typed with zero flat armour, so the max-hit
		// ratio is exactly the 15% golembane factor.
		MonsterStats golem = data().searchMonsters("grey golem", 1).get(0);
		MonsterStats goblin = data().searchMonsters("goblin", 1).get(0);
		int vsGolem = calculate(golem, "Barronite mace").getMaxHit();
		int vsGoblin = calculate(goblin, "Barronite mace").getMaxHit();
		Assert.assertEquals((int) (vsGoblin * 23L / 20), vsGolem);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.MonsterDefences;
import com.loadoutlab.data.MonsterOffence;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.StatBlock;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class IncomingDpsCalculatorTest
{
	/** Graardor-shaped melee stats: atk 280 (+120), str 350 (+43), 6t. */
	private static MonsterOffence offence(List<String> styles)
	{
		return new MonsterOffence(280, 350, 350, 80,
			120, 43, 100, 40, 0, 0, 6, styles);
	}

	private static MonsterStats monster(List<String> styles)
	{
		return new MonsterStats(1, "Test Boss", "", 600, 255, 4, 250, 80, 0,
			MonsterDefences.ZERO, offence(styles),
			java.util.Collections.emptyList(), false, "", 0);
	}

	/** A single armour piece carrying the whole set's defensive block. */
	private static Loadout armour(int stab, int slash, int crush, int magic, int ranged)
	{
		GearItem body = new GearItem(1, "Test platebody", "", GearSlot.BODY, "", 0,
			false, true, true, true, 0,
			StatBlock.ZERO,
			new StatBlock(stab, slash, crush, magic, ranged, 0, 0, 0, 0),
			StatBlock.ZERO, null);
		return new Loadout(Map.of(GearSlot.BODY, body));
	}

	@Test
	public void singleStyleMonsterIsFullyBlockedByTheProtectionPrayer()
	{
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			monster(List.of("Crush")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Melee", result.protectPrayer);
		Assert.assertEquals(0.0, result.totalDps, 1e-9);
		Assert.assertTrue(result.unprayedDps > 0);
		Assert.assertTrue(result.fullyModeled);
		Assert.assertTrue(result.threats.get(0).blocked);
	}

	@Test
	public void hybridStylesProtectByDeliveryNotRoll()
	{
		// Wiki (Magical melee / Magical ranged pages): the accuracy roll
		// is vs magic defence, but the PRAYER follows the delivery - a
		// Pyrefiend's magical melee is blocked by Protect from MELEE
		// (field report 2026-08-08, grZ: "this is wrong should be melee
		// protect"), magical ranged by Protect from MISSILES.
		IncomingDpsCalculator.Result melee = IncomingDpsCalculator.calculate(
			monster(List.of("Magical melee")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Melee", melee.protectPrayer);
		IncomingDpsCalculator.Result ranged = IncomingDpsCalculator.calculate(
			monster(List.of("Magical ranged")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Missiles", ranged.protectPrayer);
		// The inverse hybrids: ranged magic (Kree'arra, Spinolyps) is a
		// CAST that rolls vs ranged defence - Protect from Magic blocks
		// it; ranged melee (dust devils) is melee-blocked.
		IncomingDpsCalculator.Result cast = IncomingDpsCalculator.calculate(
			monster(List.of("Ranged magic")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Magic", cast.protectPrayer);
		IncomingDpsCalculator.Result swing = IncomingDpsCalculator.calculate(
			monster(List.of("Ranged melee")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Melee", swing.protectPrayer);
	}

	@Test
	public void chipStyleContributesItsRotationShareWhilePrayingTheWorst()
	{
		// Hand-computed: crush roll 289*184=53176 vs def (99+9)*(200+64)=28512
		// -> acc 0.73189, max hit (359*107+320)/640=60, 6t
		// -> crush dps 0.73189*30/3.6 = 6.0991.
		// Ranged roll 359*164=58876 vs 108*214=23112 -> acc 0.80373,
		// max (359*104+320)/640=58 -> dps 0.80373*29/3.6 = 6.4745 (worst).
		// Protect Missiles; chip = crush share 6.0991/2 = 3.0495.
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			monster(Arrays.asList("Crush", "Ranged")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Missiles", result.protectPrayer);
		Assert.assertEquals(3.0495, result.totalDps, 0.005);
		// Unprayed adds the blocked ranged share: 3.0495 + 6.4745/2 = 6.2868.
		Assert.assertEquals(6.2868, result.unprayedDps, 0.005);
		Assert.assertEquals(60, result.threats.get(0).maxHit);
	}

	@Test
	public void aPreparedCalculatorMatchesTheFullCalculationExactly()
	{
		// The defense-weighted beam scores thousands of candidate sets per
		// optimize; prepare() hoists the monster-side constants and must
		// reproduce calculate() bit-for-bit on both model paths.
		MonsterStats sheet = monster(Arrays.asList("Crush", "Ranged", "Magic", "Dragonfire"));
		Loadout[] armours = {
			armour(0, 0, 0, 0, 0),
			armour(200, 180, 210, 40, 150),
			armour(-20, 300, 5, 120, 60),
		};
		IncomingDpsCalculator.Prepared prepared = IncomingDpsCalculator.prepare(sheet, 82, 91);
		for (Loadout loadout : armours)
		{
			IncomingDpsCalculator.Result full = IncomingDpsCalculator.calculate(sheet, loadout, 82, 91);
			Assert.assertEquals(full.totalDps, prepared.totalDps(loadout), 0.0);
		}
	}

	@Test
	public void aPreparedCalculatorMatchesOnCuratedOverrideBosses()
	{
		com.loadoutlab.data.LoadoutData data = new com.loadoutlab.data.DataService().load();
		for (String name : new String[]{"Callisto", "Zulrah", "Corporeal Beast"})
		{
			MonsterStats boss = data.searchMonsters(name, 1).get(0);
			IncomingDpsCalculator.Prepared prepared = IncomingDpsCalculator.prepare(boss, 85, 89);
			for (Loadout loadout : new Loadout[]{
				armour(0, 0, 0, 0, 0), armour(220, 240, 230, 80, 200)})
			{
				IncomingDpsCalculator.Result full = IncomingDpsCalculator.calculate(boss, loadout, 85, 89);
				Assert.assertEquals(full.totalDps, prepared.totalDps(loadout), 0.0);
			}
		}
	}

	@Test
	public void betterArmourMeansLessIncomingDps()
	{
		double tank = IncomingDpsCalculator.calculate(
			monster(Arrays.asList("Crush", "Ranged")), armour(300, 300, 300, 0, 300), 99, 99).totalDps;
		double naked = IncomingDpsCalculator.calculate(
			monster(Arrays.asList("Crush", "Ranged")), armour(0, 0, 0, 0, 0), 99, 99).totalDps;
		Assert.assertTrue(tank + " < " + naked, tank < naked);
	}

	@Test
	public void magicDefenceUsesMagicLevelAndMagicDefBonus()
	{
		MonsterStats mage = monster(List.of("Magic", "Ranged"));
		double lowMagic = IncomingDpsCalculator.calculate(mage, armour(0, 0, 0, 0, 0), 99, 1).totalDps;
		double highMagic = IncomingDpsCalculator.calculate(mage, armour(0, 0, 0, 0, 0), 99, 99).totalDps;
		Assert.assertTrue(highMagic <= lowMagic);
		double magicArmour = IncomingDpsCalculator.calculate(mage, armour(0, 0, 0, 120, 0), 99, 99).totalDps;
		Assert.assertTrue(magicArmour < highMagic);
	}

	@Test
	public void unmodeledStylesAreSurfacedNotSilentlyDropped()
	{
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			monster(Arrays.asList("Typeless")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertFalse(result.fullyModeled);
		Assert.assertNull(result.protectPrayer);
		Assert.assertEquals(0.0, result.totalDps, 1e-9);
		Assert.assertFalse(result.threats.get(0).modeled);
	}

	@Test
	public void genericMeleeAssumesTheWeakestDefensiveSide()
	{
		// Generic "Melee" must use min(stab, slash, crush) = 50 here,
		// so it hits harder than a typed Crush attack against crush 300.
		double generic = IncomingDpsCalculator.calculate(
			monster(List.of("Melee", "Ranged")), armour(50, 300, 300, 0, 0), 99, 99).totalDps;
		double typed = IncomingDpsCalculator.calculate(
			monster(List.of("Crush", "Ranged")), armour(50, 300, 300, 0, 0), 99, 99).totalDps;
		Assert.assertTrue(generic >= typed);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterGroups;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * KQ's phase immunity is a protection PRAYER, and Verac's set pierces it
 * (wiki: 25% guaranteed hit, +1 damage, "includes monsters that make use
 * of protection prayers"). Field report 2026-08-06: pinning full Verac's
 * rendered "No usable owned set found" because the synthetic phase
 * encoded the prayer as absolute immunity - the classic full-Verac's KQ
 * kill was impossible in the model.
 */
class KalphiteVeracTest
{
	private static LoadoutData data;
	private static MonsterStats airborne;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
		airborne = MonsterGroups.load(data).stream()
			.filter(g -> "Kalphite Queen".equals(g.getName()))
			.flatMap(g -> g.getMobs().stream())
			.filter(m -> m.getVersion().contains("no mel")
				|| m.hasAttribute("immune_melee"))
			.findFirst().orElseThrow();
		assertTrue(airborne.hasAttribute("prayer_immunity"),
			"test premise: the airborne form's immunity is prayer-based");
	}

	private static Loadout verac(boolean full)
	{
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		for (GearItem g : data.getGearItems())
		{
			String n = g.getNameLower();
			if (!g.isStandardGear())
			{
				continue;
			}
			if (n.startsWith("verac's flail"))
			{
				gear.put(GearSlot.WEAPON, g);
			}
			if (full && n.startsWith("verac's helm"))
			{
				gear.put(GearSlot.HEAD, g);
			}
			if (full && n.startsWith("verac's brassard"))
			{
				gear.put(GearSlot.BODY, g);
			}
			if (full && n.startsWith("verac's plateskirt"))
			{
				gear.put(GearSlot.LEGS, g);
			}
		}
		return new Loadout(gear);
	}

	private static OptimizationRequest req()
	{
		return TestRequests.of(airborne, CombatStyle.MELEE,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED),
			null, 0, CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
	}

	@Test
	@DisplayName("full Verac's pierces the airborne prayer at exactly the proc rate")
	void fullSetPierces()
	{
		DpsResult r = new DpsCalculator().calculate(req(), verac(true));
		assertNotNull(r, "the flail must gate melee entry through the prayer");
		assertTrue(r.getDps() > 0, "the classic full-Verac's kill must be possible");
		assertEquals(0.25, r.getAccuracy(), 1e-9, "only the proc lands");
		assertEquals(0.25 * RollMath.normalExpectedHit(1.0, r.getMaxHit()),
			r.getExpectedHit(), 0.05, "expectation is the proc quarter, +1 damage");
	}

	@Test
	@DisplayName("the flail without the set lands nothing - but stays a zero, not a null")
	void partialSetIsZeroNotNull()
	{
		DpsResult r = new DpsCalculator().calculate(req(), verac(false));
		assertNotNull(r, "partial Verac states must survive for the beam to finish the set");
		assertEquals(0.0, r.getDps(), 1e-9);
	}

	@Test
	@DisplayName("a whip is still simply immune")
	void whipStaysImmune()
	{
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		for (GearItem g : data.getGearItems())
		{
			if (g.getNameLower().equals("abyssal whip"))
			{
				gear.put(GearSlot.WEAPON, g);
			}
		}
		assertNull(new DpsCalculator().calculate(req(), new Loadout(gear)));
	}

	@Test
	@DisplayName("the optimizer assembles the set on its own when the pieces are owned")
	void optimizerAssemblesTheSet()
	{
		java.util.Map<Integer, Integer> owned = new java.util.HashMap<>();
		for (GearItem g : data.getGearItems())
		{
			String n = g.getNameLower();
			if (g.isStandardGear() && (n.startsWith("verac's") || n.equals("abyssal whip")
				|| n.equals("bandos chestplate") || n.equals("bandos tassets")))
			{
				owned.put(g.getId(), 1);
			}
		}
		OptimizationRequest request = TestRequests.of(airborne,
			CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false, new OwnedItems(owned, true), 1);
		List<DpsResult> out = new LoadoutOptimizer().optimize(data, request);
		assertFalse(out.isEmpty(), "an owned Verac's set must produce a melee answer");
		assertTrue(DpsCalculator.fullVeracSet(out.get(0).getLoadout()),
			"the answer must be the assembled set, was: " + out.get(0).getLoadout().getGear());
		assertTrue(out.get(0).getDps() > 0);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The leaf-bladed battleaxe deals +17.5% damage to turoths and kurasks
 * (wiki-verified passive, stacks with the slayer helmet; 2026-07 player
 * audit A2.4). Damage only - accuracy is untouched. Per the pool lesson,
 * the conditional also needs a candidate-score boost and an
 * optimizer-level test proving the axe actually gets PICKED.
 */
class LeafBladedTest
{
	private static LoadoutData data;
	private static MonsterStats kurask;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
		kurask = data.searchMonsters("kurask", 1).get(0);
		assertTrue(kurask.hasAttribute("leafy"), "test premise: kurask is leafy");
	}

	private static GearItem byName(String nameLower)
	{
		for (GearItem item : data.getGearItems())
		{
			if (item.getNameLower().equals(nameLower))
			{
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + nameLower);
	}

	private static DpsResult calc(MonsterStats monster, GearItem weapon)
	{
		OptimizationRequest request = new OptimizationRequest(monster,
			CombatStyle.MELEE, PlayerLevels.MAXED, PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, true,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, weapon);
		return new DpsCalculator().calculate(request, new Loadout(gear));
	}

	@Test
	@DisplayName("the battleaxe hits 17.5% harder at a kurask than its raw stats say")
	void damageBoostApplies()
	{
		GearItem axe = byName("leaf-bladed battleaxe");
		GearItem sword = byName("leaf-bladed sword");

		// Same weapon vs a non-leafy target of any defence: max hit is a pure
		// function of strength gear, so the leafy bump shows in maxHit alone.
		MonsterStats goblin = data.searchMonsters("goblin", 1).get(0);
		int plainMax = calc(goblin, axe).getMaxHit();
		int leafyMax = calc(kurask, axe).getMaxHit();
		assertEquals(plainMax * 47 / 40, leafyMax,
			"kurask max hit must be the plain max hit boosted 17.5%");

		// The sword carries no such passive - identical max hit both places.
		assertEquals(calc(goblin, sword).getMaxHit(), calc(kurask, sword).getMaxHit());
	}

	@Test
	@DisplayName("the optimizer PICKS the battleaxe at kurask (pool lesson)")
	void optimizerPicksTheAxe()
	{
		OptimizationRequest request = new OptimizationRequest(kurask,
			CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, true,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 3);
		List<DpsResult> results = new LoadoutOptimizer().optimize(data, request);
		assertFalse(results.isEmpty());
		assertEquals("leaf-bladed battleaxe",
			results.get(0).getLoadout().getWeapon().getNameLower(),
			"the +17.5% must make the axe the melee pick, not just a dps footnote");
	}
}

