	@Test
	public void sweep() throws Exception
	{
		String dir = System.getenv("LOADOUT_LAB_VECTORS");
		Assume.assumeNotNull(dir);
		Assume.assumeNotNull(System.getenv("LOADOUT_LAB_SWEEP"));

		LoadoutData data = new DataService().load();
		LoadoutOptimizer optimizer = new LoadoutOptimizer();
		Gson gson = new GsonBuilder().setPrettyPrinting().create();
		List<Map<String, Object>> vectors = new ArrayList<>();
		List<Map<String, Object>> ours = new ArrayList<>();

		for (String[] m : SWEEP_MONSTERS)
		{
			MonsterStats monster = data.searchMonsters(m[0], 10).stream()
				.filter(x -> m[1].isEmpty() || m[1].equalsIgnoreCase(x.getVersion()))
				.findFirst()
				.orElse(data.searchMonsters(m[0], 1).stream().findFirst().orElse(null));
			if (monster == null)
			{
				continue;
			}
			for (CombatStyle style : new CombatStyle[]{CombatStyle.MELEE, CombatStyle.RANGED, CombatStyle.MAGIC})
			{
				OptimizationRequest request = new OptimizationRequest(
					monster, style, PlayerLevels.MAXED,
					prayersFor(style), null, 0,
					CandidateMode.ALL_STANDARD, true, false,
					OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
				List<DpsResult> results = optimizer.optimize(data, request);
				if (results.isEmpty())
				{
					continue;
				}
				DpsResult result = results.get(0);
				String name = (m[0] + "-" + style).toLowerCase().replace(" ", "").replace("'", "");

				List<Object> gearNames = new ArrayList<>();
				for (GearItem item : result.getLoadout().getGear().values())
				{
					if (item != null)
					{
						gearNames.add(gearRef(item));
					}
				}
				Map<String, Object> vector = new LinkedHashMap<>();
				vector.put("name", name);
				vector.put("monster", m[0]);
				vector.put("monsterVersion", m[1]);
				vector.put("gear", gearNames);
				vector.put("prayers", prayerNames(style));
				if (!result.getSpellName().isEmpty())
				{
					vector.put("spell", result.getSpellName());
					if (result.getSpellName().contains("Demonbane"))
					{
						vector.put("markOfDarkness", true);
					}
				}
				vectors.add(vector);

				Map<String, Object> mine = new LinkedHashMap<>();
				mine.put("name", name);
				mine.put("dps", result.getDps());
				mine.put("maxHit", result.getMaxHit());
				mine.put("accuracy", result.getAccuracy());
				mine.put("attackRoll", result.getAttackRoll());
				mine.put("weapon", result.getLoadout().getWeapon().getName());
				ours.add(mine);
			}
		}
		try (FileWriter w = new FileWriter(dir + "/vectors.json"))
		{
			gson.toJson(vectors, w);
		}
		try (FileWriter w = new FileWriter(dir + "/ours.json"))
		{
			gson.toJson(ours, w);
		}
		System.out.println("sweep exported " + vectors.size() + " vectors");
	}

	@Test
	public void export() throws Exception
	{
		String dir = System.getenv("LOADOUT_LAB_VECTORS");
		Assume.assumeNotNull(dir);
		Assume.assumeTrue(System.getenv("LOADOUT_LAB_SWEEP") == null);

		LoadoutData data = new DataService().load();
		Gson gson = new GsonBuilder().setPrettyPrinting().create();
		List<Map<String, Object>> vectors = new ArrayList<>();
		List<Map<String, Object>> ours = new ArrayList<>();

		for (String[] s : SCENARIOS)
		{
			if (s[4] == null)
			{
				continue; // placeholder rows
			}
			String name = s[0];
			// Our corpus collapses combat-identical versions (and blanks the
			// label), so fall back to the first name match; s[2] stays in
			// the vector for the official side's exact-version lookup.
			// Version compare is FIRST-TOKEN both sides: our loader
			// normalizes the wiki's compound strings ("Awakened, Awake"
			// -> "Awakened") while the official data keeps them raw -
			// the vector carries the raw string for their lookup.
			MonsterStats monster = data.searchMonsters(s[1], 10).stream()
				.filter(m -> s[2] == null || s[2].isEmpty()
					|| firstToken(s[2]).equalsIgnoreCase(firstToken(m.getVersion())))
				.findFirst()
				.orElse(data.searchMonsters(s[1], 1).stream().findFirst().orElse(null));
			GearItem weapon = byName(data, s[4]);
			if (monster == null || weapon == null)
			{
				continue;
			}
			CombatStyle style = CombatStyle.valueOf(s[3]);
			com.loadoutlab.data.SpellStats forcedSpell = s.length > 6 && s[6] != null
				? data.getSpells().stream().filter(sp -> sp.getName().equalsIgnoreCase(s[6])).findFirst().orElse(null)
				: null;
			EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
			gear.put(GearSlot.WEAPON, weapon);
			List<Object> gearNames = new ArrayList<>();
			gearNames.add(gearRef(weapon));
			Integer blowpipeDartId = null;
			if (s[5] != null && s[5].startsWith("DART:"))
			{
				// The blowpipe's loaded dart: itemVars on the official side
				// (a dart as gear is a thrown WEAPON there and would replace
				// the blowpipe); our side keeps the BlowpipeDarts assumption
				// - game-best assumes dragon, so name a dragon dart here.
				GearItem dart = byName(data, s[5].substring(5));
				blowpipeDartId = dart.getId();
			}
			else if (s[5] != null)
			{
				GearItem ammo = byName(data, s[5]);
				gear.put(GearSlot.AMMO, ammo);
				gearNames.add(gearRef(ammo));
			}
			boolean onTask = false;
			int toaInvocation = 0;
			for (int i = 7; i < s.length; i++)
			{
				if (s[i] == null)
				{
					continue;
				}
				if (s[i].startsWith("INVO:"))
				{
					toaInvocation = Integer.parseInt(s[i].substring(5));
					continue;
				}
				GearItem extra = byName(data, s[i]);
				gear.put(extra.getSlot(), extra);
				gearNames.add(gearRef(extra));
				onTask |= s[i].toLowerCase().contains("slayer helmet");
			}
			monster = MonsterMechanics.atToaInvocation(monster, toaInvocation);

			OptimizationRequest request = new OptimizationRequest(
				monster, style, PlayerLevels.MAXED,
				prayersFor(style), forcedSpell, 0,
				CandidateMode.ALL_STANDARD, true, onTask,
				OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
			DpsResult result = new DpsCalculator().calculate(request, new Loadout(gear));
			if (result == null)
			{
				continue;
			}

			Map<String, Object> vector = new LinkedHashMap<>();
			vector.put("name", name);
			vector.put("monster", s[1]);
			vector.put("monsterVersion", s[2] == null ? "" : s[2]);
			vector.put("gear", gearNames);
			if (blowpipeDartId != null)
			{
				vector.put("blowpipeDartId", blowpipeDartId);
			}
			if (toaInvocation > 0)
			{
				vector.put("toaInvocationLevel", toaInvocation);
			}
			vector.put("prayers", prayerNames(style));
			if (onTask)
			{
				vector.put("onSlayerTask", true);
			}
			String spellName = result.getSpellName();
			if (spellName != null && !spellName.isEmpty())
			{
				vector.put("spell", spellName);
				if (spellName.contains("Demonbane"))
				{
					vector.put("markOfDarkness", true);
				}
			}
			vectors.add(vector);

			Map<String, Object> mine = new LinkedHashMap<>();
			mine.put("name", name);
			mine.put("dps", result.getDps());
			mine.put("maxHit", result.getMaxHit());
			mine.put("accuracy", result.getAccuracy());
			mine.put("attackRoll", result.getAttackRoll());
			mine.put("spell", result.getSpellName());
			ours.add(mine);
		}

		try (FileWriter w = new FileWriter(dir + "/vectors.json"))
		{
			gson.toJson(vectors, w);
		}
		try (FileWriter w = new FileWriter(dir + "/ours.json"))
		{
			gson.toJson(ours, w);
		}
		System.out.println("exported " + vectors.size() + " vectors to " + dir);
	}

	private static Object gearRef(GearItem item)
	{
		// [name, version, id]: the harness looks the piece up by id first -
		// the official data cases names differently (Tonalztics of Ralos,
		// Trident of the Swamp) and a name miss drops the vector.
		return new Object[]{item.getName(), item.getVersion(), item.getId()};
	}

	private static String firstToken(String version)
	{
		if (version == null)
		{
			return "";
		}
		int comma = version.indexOf(',');
		return (comma < 0 ? version : version.substring(0, comma)).trim();
	}

	private static GearItem byName(LoadoutData data, String name)
	{
		// "Name#Version" pins an exact variant (Toxic blowpipe#Charged);
		// plain names keep first-standard-match, where Empty can precede
		// Charged in corpus order.
		int hash = name.indexOf('#');
		String plain = hash < 0 ? name : name.substring(0, hash);
		String version = hash < 0 ? null : name.substring(hash + 1);
		return data.getGearItems().stream()
			.filter(g -> g.getName().equalsIgnoreCase(plain)
				&& (version == null || g.getVersion().equalsIgnoreCase(version))
				&& (version != null || g.isStandardGear()))
			.findFirst().orElse(null);
	}

	private static PrayerBonuses prayersFor(CombatStyle style)
	{
		return PrayerBonuses.bestAvailable(PlayerLevels.MAXED);
	}

	private static List<String> prayerNames(CombatStyle style)
	{
		switch (style)
		{
			case RANGED: return List.of("RIGOUR");
			// Augury only - the wiki engine stacks any prayers it is fed,
			// but the game's prayer groups forbid two magic prayers at once.
			case MAGIC: return List.of("AUGURY");
			default: return List.of("PIETY");
		}
	}
}

package com.loadoutlab.engine;

import org.junit.Assert;
import org.junit.Test;

/**
 * Guards the null-normalisation the with- helpers do. The helpers clone the
 * request rather than routing through a normalising constructor, so each
 * nullable-argument helper has to normalise at its own call site - this test
 * is what catches a new helper that forgets.
 */
public class OptimizationRequestTest
{
	private static OptimizationRequest base()
	{
		return TestRequests.of(
			null, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, 1);
	}

	@Test
	public void withExcludedItemsNullYieldsAnEmptySetNotNull()
	{
		OptimizationRequest r = base().withExcludedItems(null);
		Assert.assertNotNull(r.getExcludedItems());
		Assert.assertTrue(r.getExcludedItems().isEmpty());

		// isExcluded would NPE if the field had been left null.
		Assert.assertFalse(r.isExcluded(4151));
	}

	@Test
	public void theOtherNullableWithersNormaliseToo()
	{
		OptimizationRequest r = base()
			.withDreamItems(null)
			.withProtectOnlyItems(null)
			.withPinnedItems(null)
			.withSpellbookLock(null);
		// No getter for the dream set - isDream would NPE if it were null.
		Assert.assertFalse(r.isDream(4151));
		Assert.assertTrue(r.getProtectOnlyItems().isEmpty());
		Assert.assertTrue(r.getPinnedItems().isEmpty());
		Assert.assertEquals("", r.getSpellbookLock());
	}
}

package com.loadoutlab.engine;

import java.util.HashMap;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class OwnedItemsTest
{
	private static OwnedItems of(Map<Integer, Integer> quantities)
	{
		return new OwnedItems(quantities, true);
	}

	@Test
	public void presenceFingerprintIgnoresQuantityChanges()
	{
		// The optimizer's answers depend only on owns() (quantity > 0), so
		// shooting arrows or scaling ether must NOT invalidate its cache.
		Map<Integer, Integer> before = new HashMap<>();
		before.put(884, 1200); // arrows
		before.put(4151, 1);
		Map<Integer, Integer> after = new HashMap<>(before);
		after.put(884, 3); // most of the stack shot away

		Assert.assertEquals(of(before).presenceFingerprint(), of(after).presenceFingerprint());
	}

	@Test
	public void presenceFingerprintChangesWhenOwnershipActuallyChanges()
	{
		Map<Integer, Integer> base = new HashMap<>();
		base.put(4151, 1);

		Map<Integer, Integer> gained = new HashMap<>(base);
		gained.put(11832, 1); // new item: 0 -> 1
		Assert.assertNotEquals(of(base).presenceFingerprint(), of(gained).presenceFingerprint());

		Map<Integer, Integer> lost = new HashMap<>(gained);
		lost.put(11832, 0); // lost to zero: 1 -> 0
		Assert.assertEquals("a zero-quantity row means NOT owned - same as absent",
			of(base).presenceFingerprint(), of(lost).presenceFingerprint());
		Assert.assertNotEquals(of(gained).presenceFingerprint(), of(lost).presenceFingerprint());
	}

	@Test
	public void presenceFingerprintMatchesOwnsSemanticsExactly()
	{
		// owns() is the contract: any two ledgers agreeing on owns() for
		// every id must fingerprint identically.
		Map<Integer, Integer> a = new HashMap<>();
		a.put(1, 5);
		a.put(2, 0);
		a.put(3, 1);
		Map<Integer, Integer> b = new HashMap<>();
		b.put(1, 1);
		b.put(3, 999);
		Assert.assertEquals(of(a).presenceFingerprint(), of(b).presenceFingerprint());
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Pinned items: user preference wins the slot (bracelet of slaughter
 * class - value the model cannot price), the optimizer builds the best
 * set AROUND the pin. Optimizer-level by mandate: these run the real
 * search, the same path the panel renders.
 */
class PinTest
{
	private static LoadoutData data;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
	}

	private static OptimizationRequest ranged(CandidateMode mode, OwnedItems owned)
	{
		return new OptimizationRequest(
			data.searchMonsters("goblin", 1).get(0), CombatStyle.RANGED,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			mode, true, false, owned, RequirementProfile.MAXED, 1);
	}

	@Test
	@DisplayName("a pinned bracelet of slaughter holds the hands slot against better dps gloves")
	void pinnedSlaughterBraceletWins()
	{
		OwnedItems owned = new OwnedItems(
			Map.of(861, 1, 21326, 100, 7462, 1, 21183, 1), true);
		List<DpsResult> results = new LoadoutOptimizer().optimize(data,
			ranged(CandidateMode.OWNED_ONLY, owned)
				.withPinnedItems(Map.of(GearSlot.HANDS, 21183)));
		assertFalse(results.isEmpty());
		GearItem hands = results.get(0).getLoadout().get(GearSlot.HANDS);
		assertNotNull(hands);
		assertEquals("bracelet of slaughter", hands.getNameLower(),
			"got: " + hands.getNameLower());
	}

	@Test
	@DisplayName("an UNOWNED pin still rides in owned-only mode - 'I am bringing this'")
	void unownedPinAppears()
	{
		OwnedItems owned = new OwnedItems(Map.of(861, 1, 21326, 100), true);
		List<DpsResult> results = new LoadoutOptimizer().optimize(data,
			ranged(CandidateMode.OWNED_ONLY, owned)
				.withPinnedItems(Map.of(GearSlot.HANDS, 21183)));
		assertFalse(results.isEmpty());
		GearItem hands = results.get(0).getLoadout().get(GearSlot.HANDS);
		assertNotNull(hands);
		assertEquals("bracelet of slaughter", hands.getNameLower());
	}

	@Test
	@DisplayName("a pinned salve rides a low-risk set - the never-risk veto yields to the pin")
	void pinnedSalveSurvivesLowRisk()
	{
		MonsterStatsHolder rev = new MonsterStatsHolder();
		rev.monster = data.searchMonsters("revenant demon", 1).get(0);
		GearItem salve = null;
		for (GearItem item : data.getGearItems())
		{
			if (item.getNameLower().equals("salve amulet(ei)"))
			{
				salve = item;
			}
		}
		assertNotNull(salve);

		OptimizationRequest constrained = new OptimizationRequest(
			rev.monster, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY,
			RequirementProfile.MAXED, 1)
			.withMaxTradeables(3).withRiskBudgetGp(25_000)
			.withPinnedItems(Map.of(GearSlot.NECK, salve.getId()));

		List<DpsResult> results = new LoadoutOptimizer().optimize(data, constrained);
		assertFalse(results.isEmpty());
		GearItem neck = results.get(0).getLoadout().get(GearSlot.NECK);
		assertNotNull(neck);
		assertEquals("salve amulet(ei)", neck.getNameLower(),
			"the pin must override the rebuild veto and the cap, got: " + neck.getNameLower());
	}

	@Test
	@DisplayName("a pinned weapon locks the weapon line")
	void pinnedWeaponForced()
	{
		List<DpsResult> results = new LoadoutOptimizer().optimize(data,
			ranged(CandidateMode.ALL_STANDARD, OwnedItems.EMPTY)
				.withPinnedItems(Map.of(GearSlot.WEAPON, 861)));
		assertFalse(results.isEmpty());
		GearItem weapon = results.get(0).getLoadout().get(GearSlot.WEAPON);
		assertEquals("magic shortbow", weapon.getNameLower(),
			"got: " + weapon.getNameLower());
	}

	private static final class MonsterStatsHolder
	{
		com.loadoutlab.data.MonsterStats monster;
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellStats;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * A pinned spell must only ride weapons that can actually cast it
 * (field report 2026-08-09: Blood Barrage pinned on Thermy, but the
 * recommended weapon was a Trident - a powered staff that can only
 * fire its own built-in). The auto-spell path already enforces
 * autocast legality per weapon; the fixed-spell path skipped it.
 */
public class PinnedSpellLegalityTest
{
	private static LoadoutData data;

	private static LoadoutData data()
	{
		if (data == null)
		{
			data = new DataService().load();
		}
		return data;
	}

	private static SpellStats spell(String name)
	{
		return data().getSpells().stream()
			.filter(s -> s.getName().equalsIgnoreCase(name))
			.findFirst().orElseThrow(AssertionError::new);
	}

	private static void own(Map<Integer, Integer> owned, String nameLower)
	{
		GearItem item = data().getGearItems().stream()
			.filter(g -> g.getNameLower().equals(nameLower) && g.isStandardGear())
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + nameLower));
		owned.put(item.getId(), 1);
	}

	private static OptimizationRequest ownedMagicRequest(MonsterStats mob, Map<Integer, Integer> owned)
	{
		return new OptimizationRequest(
			mob, CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 1);
	}

	@Test
	public void aPinnedBarrageNeverRidesAPoweredStaff()
	{
		MonsterStats thermy = data().searchMonsters("thermonuclear smoke devil", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		own(owned, "trident of the seas");
		own(owned, "ancient staff");

		List<DpsResult> results = new LoadoutOptimizer().optimize(data(),
			ownedMagicRequest(thermy, owned).withSpell(spell("Blood Barrage")));
		Assert.assertFalse("an ancient staff is owned - the pin must field it", results.isEmpty());
		String weapon = results.get(0).getLoadout().get(GearSlot.WEAPON).labelLower();
		Assert.assertFalse("a powered staff cannot cast a pinned spell: " + weapon,
			weapon.contains("trident"));
		Assert.assertTrue("the ancient-capable staff carries the pin: " + weapon,
			weapon.contains("ancient staff"));
	}

	@Test
	public void noAutocastCapableWeaponMeansNoResultNotAnIllegalPair()
	{
		MonsterStats thermy = data().searchMonsters("thermonuclear smoke devil", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		own(owned, "trident of the seas");
		// Harmonised autocasts the standard book only - it must not
		// carry an ancient pin either.
		own(owned, "harmonised nightmare staff");

		List<DpsResult> results = new LoadoutOptimizer().optimize(data(),
			ownedMagicRequest(thermy, owned).withSpell(spell("Blood Barrage")));
		Assert.assertTrue("no owned weapon can autocast the pin - honest empty beats an illegal pair",
			results.isEmpty());
	}

	@Test
	public void aStandardPinStillPricesNormally()
	{
		MonsterStats thermy = data().searchMonsters("thermonuclear smoke devil", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		own(owned, "kodai wand");

		List<DpsResult> results = new LoadoutOptimizer().optimize(data(),
			ownedMagicRequest(thermy, owned).withSpell(spell("Fire Surge")));
		Assert.assertFalse(results.isEmpty());
		Assert.assertTrue(results.get(0).getMaxHit() > 0);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Poison tiers stat-tie but are not equal in game (field request: always
 * recommend dragon dagger p++ over plain). Optimizer-level: the real
 * search must pick the p++ when tiers tie.
 */
class PoisonTierTest
{
	private static LoadoutData data;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
	}

	@Test
	@DisplayName("poison tiers parse from corpus versions, unpoisoned included")
	void tiersParse()
	{
		int[] tiers = new int[4];
		for (GearItem item : data.getGearItems())
		{
			if (item.getNameLower().equals("dragon dagger"))
			{
				tiers[item.poisonTier()]++;
			}
		}
		assertArrayEquals(new int[]{1, 1, 1, 1}, tiers,
			"expected exactly one dagger per tier 0..3");
	}

	@Test
	@DisplayName("owning every dagger tier, the search recommends the p++")
	void ownedDaggersPickThePlusPlus()
	{
		// 1215 unpoisoned, 1231 p, 5680 p+, 5698 p++.
		OwnedItems owned = new OwnedItems(
			Map.of(1215, 1, 1231, 1, 5680, 1, 5698, 1), true);
		OptimizationRequest request = new OptimizationRequest(
			data.searchMonsters("goblin", 1).get(0), CombatStyle.MELEE,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false, owned, RequirementProfile.MAXED, 1);

		List<DpsResult> results = new LoadoutOptimizer().optimize(data, request);
		assertFalse(results.isEmpty());
		GearItem weapon = results.get(0).getLoadout().get(GearSlot.WEAPON);
		assertEquals("dragon dagger", weapon.getNameLower());
		assertEquals(3, weapon.poisonTier(),
			"expected the p++ tier, got version: " + weapon.getVersionLower());
	}
}

package com.loadoutlab.engine;

import org.junit.Assert;
import org.junit.Test;

/**
 * The assume-chip prayer picker (field direction 2026-07-21: "I don't use
 * Piety against every mob"): named tiers per style whose factors mirror
 * bestAvailable's cascade exactly.
 */
public class PrayerPickTest
{
	@Test
	public void picksReplaceOnlyTheChosenStylesFactors()
	{
		PrayerBonuses best = PrayerBonuses.bestAvailable(PlayerLevels.MAXED);
		PrayerBonuses chivalry = PrayerBonuses.forPick(CombatStyle.MELEE, "Chivalry", best);
		Assert.assertEquals(1.15, chivalry.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.18, chivalry.getMeleeStrength(), 1e-9);
		Assert.assertEquals("Chivalry", chivalry.nameFor(CombatStyle.MELEE));
		Assert.assertEquals("the other styles keep the fallback",
			best.getRangedAccuracy(), chivalry.getRangedAccuracy(), 1e-9);

		PrayerBonuses eagle = PrayerBonuses.forPick(CombatStyle.RANGED, "Eagle Eye", best);
		Assert.assertEquals(1.15, eagle.getRangedAccuracy(), 1e-9);
		Assert.assertEquals(1.15, eagle.getRangedStrength(), 1e-9);

		PrayerBonuses might = PrayerBonuses.forPick(CombatStyle.MAGIC, "Mystic Might", best);
		Assert.assertEquals(1.15, might.getMagicAccuracy(), 1e-9);
		Assert.assertEquals(2.0, might.getMagicDamagePercent(), 1e-9);

		// The lower melee combo tiers (field ask 2026-07-21): 1.10/1.10
		// and 1.05/1.05, mirroring bestAvailable's cascade exactly.
		PrayerBonuses mid = PrayerBonuses.forPick(CombatStyle.MELEE,
			"Superhuman Strength + Improved Reflexes", best);
		Assert.assertEquals(1.10, mid.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.10, mid.getMeleeStrength(), 1e-9);
		PrayerBonuses low = PrayerBonuses.forPick(CombatStyle.MELEE,
			"Burst of Strength + Clarity of Thought", best);
		Assert.assertEquals(1.05, low.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.05, low.getMeleeStrength(), 1e-9);

		// The lower ranged/magic tiers (field ask 2026-07-21 part 2),
		// mirroring the cascade: Hawk/Sharp Eye, Mystic Lore/Will.
		Assert.assertEquals(1.10, PrayerBonuses.forPick(CombatStyle.RANGED,
			"Hawk Eye", best).getRangedAccuracy(), 1e-9);
		Assert.assertEquals(1.05, PrayerBonuses.forPick(CombatStyle.RANGED,
			"Sharp Eye", best).getRangedStrength(), 1e-9);
		PrayerBonuses lore = PrayerBonuses.forPick(CombatStyle.MAGIC, "Mystic Lore", best);
		Assert.assertEquals(1.10, lore.getMagicAccuracy(), 1e-9);
		Assert.assertEquals(1.0, lore.getMagicDamagePercent(), 1e-9);
		PrayerBonuses will = PrayerBonuses.forPick(CombatStyle.MAGIC, "Mystic Will", best);
		Assert.assertEquals(1.05, will.getMagicAccuracy(), 1e-9);
		Assert.assertEquals(0.0, will.getMagicDamagePercent(), 1e-9);
	}

	@Test
	public void unknownPicksFallBackToDetect()
	{
		PrayerBonuses best = PrayerBonuses.bestAvailable(PlayerLevels.MAXED);
		Assert.assertSame(best, PrayerBonuses.forPick(CombatStyle.MELEE, "Retribution", best));
	}

	@Test
	public void everyStyleOffersItsNamedTiers()
	{
		Assert.assertEquals("Piety", PrayerBonuses.optionsFor(CombatStyle.MELEE)[0]);
		Assert.assertEquals("Rigour", PrayerBonuses.optionsFor(CombatStyle.RANGED)[0]);
		Assert.assertEquals("Augury", PrayerBonuses.optionsFor(CombatStyle.MAGIC)[0]);
	}

	@Test
	public void boostMembershipDrivesTheStyleMenus()
	{
		Assert.assertTrue(BoostProfile.SMELLING_SALTS.boosts('a'));
		Assert.assertTrue(BoostProfile.SMELLING_SALTS.boosts('m'));
		Assert.assertTrue(BoostProfile.SUPER_COMBAT.boosts('a'));
		Assert.assertFalse(BoostProfile.SUPER_COMBAT.boosts('r'));
		Assert.assertTrue(BoostProfile.RANGING.boosts('r'));
		Assert.assertFalse(BoostProfile.RANGING.boosts('m'));
	}
}

package com.loadoutlab.engine;

import org.junit.Assert;
import org.junit.Test;

public class PrayerUnlocksTest
{
	@Test
	public void lockedPrayersFallBackToTheBestUnlockedTier()
	{
		PlayerLevels maxed = PlayerLevels.MAXED;

		// No King's Ransom: no Piety - falls to Ultimate Strength tier.
		PrayerBonuses noKr = PrayerBonuses.bestAvailable(maxed,
			new PrayerUnlocks(false, true, true, true, true));
		Assert.assertEquals(1.15, noKr.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.15, noKr.getMeleeStrength(), 1e-9);

		// No Rigour scroll but Deadeye unlocked: 18/18.
		PrayerBonuses noRigour = PrayerBonuses.bestAvailable(maxed,
			new PrayerUnlocks(true, false, true, true, true));
		Assert.assertEquals(1.18, noRigour.getRangedAccuracy(), 1e-9);
		Assert.assertEquals(1.18, noRigour.getRangedStrength(), 1e-9);

		// Neither Rigour nor Deadeye: Eagle Eye tier.
		PrayerBonuses eagleEye = PrayerBonuses.bestAvailable(maxed,
			new PrayerUnlocks(true, false, true, false, true));
		Assert.assertEquals(1.15, eagleEye.getRangedAccuracy(), 1e-9);

		// No Augury but Mystic Vigour: 1.18 accuracy, 3% damage.
		PrayerBonuses noAugury = PrayerBonuses.bestAvailable(maxed,
			new PrayerUnlocks(true, true, false, true, true));
		Assert.assertEquals(1.18, noAugury.getMagicAccuracy(), 1e-9);
		Assert.assertEquals(3.0, noAugury.getMagicDamagePercent(), 1e-9);

		// Everything unlocked: Augury WINS over Mystic Vigour, it never
		// stacks with it - all magic prayers share one prayer group, so
		// only one can be active (the wiki calc engine happily stacks
		// illegal combos; the game does not).
		PrayerBonuses all = PrayerBonuses.bestAvailable(maxed, PrayerUnlocks.ALL);
		Assert.assertEquals(1.20, all.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.25, all.getMagicAccuracy(), 1e-9);
		Assert.assertEquals(4.0, all.getMagicDamagePercent(), 1e-9);
		Assert.assertEquals("Augury", all.nameFor(CombatStyle.MAGIC));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.SpellRunes;
import java.util.HashMap;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-27 (Not on Hand's F2P test account): the plugin
 * recommended Death Charge - members, Magic 90, A Kingdom Divided, a
 * blood + death + soul rune per cast - and autocast spells whose runes the
 * bank does not hold.
 *
 * <p>The gate checks only the premium combat runes (blood, soul, death,
 * wrath). Elemental and mind/chaos-class runes are deliberately ungated -
 * any shop sells them, and requiring every air rune in the bank would be
 * noise, not honesty.
 */
class PremiumRuneGateTest
{
	private static final int BLOOD = 565;
	private static final int DEATH = 560;
	private static final int SOUL = 566;
	private static final int WRATH = 21880;

	private static OwnedItems bank(int... ids)
	{
		Map<Integer, Integer> owned = new HashMap<>();
		for (int id : ids)
		{
			owned.put(id, 1000);
		}
		return new OwnedItems(owned, true);
	}

	@Test
	@DisplayName("a runeless bank blocks blood, death, soul and wrath spells")
	void runelessBankBlocksPremiumSpells()
	{
		OwnedItems empty = bank();
		assertFalse(SpellRunes.premiumRunesOwned("Fire Wave", empty), "Fire Wave costs a blood rune");
		assertFalse(SpellRunes.premiumRunesOwned("Ice Barrage", empty), "Ice Barrage costs blood + death");
		assertFalse(SpellRunes.premiumRunesOwned("Fire Surge", empty), "Fire Surge costs a wrath rune");
		assertFalse(SpellRunes.premiumRunesOwned("Death Charge", empty), "Death Charge costs blood + death + soul");
	}

	@Test
	@DisplayName("cheap-rune spells always pass - shops sell their runes")
	void cheapSpellsAlwaysPass()
	{
		OwnedItems empty = bank();
		assertTrue(SpellRunes.premiumRunesOwned("Fire Strike", empty));
		assertTrue(SpellRunes.premiumRunesOwned("Fire Bolt", empty));
	}

	@Test
	@DisplayName("owning exactly the needed premium runes unlocks the spell")
	void owningTheRunesUnlocks()
	{
		assertTrue(SpellRunes.premiumRunesOwned("Fire Wave", bank(BLOOD)));
		assertFalse(SpellRunes.premiumRunesOwned("Ice Barrage", bank(BLOOD)),
			"Ice Barrage also needs death runes");
		assertTrue(SpellRunes.premiumRunesOwned("Ice Barrage", bank(BLOOD, DEATH)));
		assertTrue(SpellRunes.premiumRunesOwned("Fire Surge", bank(WRATH)));
		assertTrue(SpellRunes.premiumRunesOwned("Death Charge", bank(BLOOD, DEATH, SOUL)));
	}

	@Test
	@DisplayName("unknown spells and a null bank fail open")
	void failsOpen()
	{
		assertTrue(SpellRunes.premiumRunesOwned("Some Future Spell", bank()));
		assertTrue(SpellRunes.premiumRunesOwned("Fire Wave", null));
		assertTrue(SpellRunes.premiumRunesOwned(null, bank()));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.StatBlock;
import java.util.HashMap;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class PvpRiskTest
{
	/** The retired risksRebuild() overloads: the friction-only case
	 * of risksUnprotected(), i.e. no protect-only flags. They had no
	 * production callers, so they live here as delegates instead. */
	private static boolean risksRebuild(Loadout loadout, GearItem carriedSpecWeapon, int keptSlots)
	{
		return risksRebuild(loadout, carriedSpecWeapon, keptSlots, java.util.Collections.emptySet());
	}

	private static boolean risksRebuild(Loadout loadout, GearItem carriedSpecWeapon, int keptSlots,
		java.util.Set<Integer> pinnedIds)
	{
		return PvpRisk.risksUnprotected(loadout, carriedSpecWeapon, keptSlots, pinnedIds,
			java.util.Collections.emptySet());
	}

	private static GearItem item(int id, GearSlot slot, boolean tradeable, int price)
	{
		return new GearItem(id, "Item" + id, "", slot, "", 0, false, true,
			tradeable, true, price, StatBlock.ZERO, StatBlock.ZERO, StatBlock.ZERO, null);
	}

	private static final StatBlock SOME_DEFENCE =
		new StatBlock(0, 0, 0, 0, 0, 0, 0, 0, 2);

	private static GearItem untradeable(int id, String name, GearSlot slot, StatBlock bonuses)
	{
		return new GearItem(id, name, "", slot, "", 0, false, true,
			false, true, null, StatBlock.ZERO, StatBlock.ZERO, bonuses, null);
	}

	private static Loadout worn(GearItem... items)
	{
		Map<GearSlot, GearItem> gear = new HashMap<>();
		for (GearItem g : items)
		{
			gear.put(g.getSlot(), g);
		}
		return new Loadout(gear);
	}

	@Test
	public void tradeablesBeyondTheKeptSlotsAreTheRisk()
	{
		Loadout loadout = worn(
			item(1, GearSlot.WEAPON, true, 100),
			item(2, GearSlot.BODY, true, 80),
			item(3, GearSlot.LEGS, true, 60),
			item(4, GearSlot.HEAD, true, 40),
			item(5, GearSlot.FEET, true, 20));
		PvpRisk.Assessment three = PvpRisk.assess(loadout, null, 3);
		Assert.assertEquals(60, three.riskGp);
		Assert.assertEquals(3, three.kept.size());
		Assert.assertEquals(2, three.lost.size());
		Assert.assertEquals(20, PvpRisk.assess(loadout, null, 4).riskGp);
	}

	@Test
	public void avariceSkullsTheWearerSoDefaultProtectionVanishes()
	{
		// The amulet of avarice keeps the wearer permanently skulled:
		// keep-3 becomes keep-0, keep-4 (Protect Item) becomes keep-1.
		GearItem avarice = new GearItem(9, "Amulet of avarice", "", GearSlot.NECK, "", 0,
			false, true, true, true, 500_000, StatBlock.ZERO, StatBlock.ZERO, StatBlock.ZERO, null);
		Loadout loadout = worn(
			item(1, GearSlot.WEAPON, true, 100),
			item(2, GearSlot.BODY, true, 80),
			avarice);

		PvpRisk.Assessment skulled = PvpRisk.assess(loadout, null, 3);
		Assert.assertEquals(0, skulled.kept.size());
		Assert.assertEquals(100 + 80 + 500_000, skulled.riskGp);

		PvpRisk.Assessment protect = PvpRisk.assess(loadout, null, 4);
		Assert.assertEquals(1, protect.kept.size());
		Assert.assertEquals("the amulet itself is the most valuable piece",
			9, protect.kept.get(0).getId());
	}

	@Test
	public void costFreeBreakersChargeTheirRebuildFriction()
	{
		// Salve amulet(ei): gp cost 0 (free tomb re-obtain, imbue points
		// refunded) but the death still costs the rebuild errand - the
		// curated 150k friction charges into the risk total and the risk
		// cap, so it can never ride into a low-risk set as "safe".
		Loadout loadout = worn(
			item(1, GearSlot.WEAPON, true, 100),
			untradeable(2, "salve amulet(ei)", GearSlot.NECK, SOME_DEFENCE));
		PvpRisk.Assessment fates = PvpRisk.assess(loadout, null, 3);
		Assert.assertEquals(1, fates.untradeableCharges.size());
		Assert.assertEquals(2, fates.untradeableCharges.get(0).item.getId());
		Assert.assertEquals(150_000, fates.untradeableCharges.get(0).costGp);
		Assert.assertEquals(150_000, fates.riskGp);
	}

	@Test
	public void risksRebuildFlagsUnprotectedFrictionItemsOnly()
	{
		// Salve: unprotectable in the model - always a risked rebuild.
		Loadout salve = worn(
			item(1, GearSlot.WEAPON, true, 100),
			untradeable(2, "salve amulet(ei)", GearSlot.NECK, SOME_DEFENCE));
		Assert.assertTrue(risksRebuild(salve, null, 3));

		// Warrior ring (i) with cheap tradeables: it ranks into the kept
		// slots - protected, so no risked rebuild.
		Loadout protectedRing = worn(
			item(1, GearSlot.WEAPON, true, 100),
			untradeable(3, "warrior ring (i)", GearSlot.RING, SOME_DEFENCE));
		Assert.assertFalse(risksRebuild(protectedRing, null, 3));

		// The same ring displaced from the kept slots by pricier gear IS
		// a risked rebuild.
		Loadout displacedRing = worn(
			item(1, GearSlot.WEAPON, true, 100_000_000),
			item(2, GearSlot.BODY, true, 50_000_000),
			item(4, GearSlot.LEGS, true, 20_000_000),
			untradeable(3, "warrior ring (i)", GearSlot.RING, SOME_DEFENCE));
		Assert.assertTrue(risksRebuild(displacedRing, null, 3));

		// No friction anywhere: cheap early exit, never flagged.
		Loadout plain = worn(item(1, GearSlot.WEAPON, true, 100));
		Assert.assertFalse(risksRebuild(plain, null, 3));
	}

	@Test
	public void imbuedConvertsCarryTheirReimbueFrictionInThePool()
	{
		// Warrior ring (i): the killer gets the 60k base ring and the
		// victim owes a re-imbue visit - loss price is 60k + 50k friction.
		Loadout loadout = worn(
			untradeable(3, "warrior ring (i)", GearSlot.RING, SOME_DEFENCE));
		PvpRisk.Assessment fates = PvpRisk.assess(loadout, null, 0);
		Assert.assertEquals(110_000, fates.riskGp);
		Assert.assertEquals(110_000, fates.valueOf(
			loadout.get(GearSlot.RING)));
	}

	@Test
	public void untradeablesAreKeptOutsideTheSlotRanking()
	{
		Loadout loadout = worn(
			item(1, GearSlot.WEAPON, true, 100),
			item(2, GearSlot.BODY, false, 999_999),
			item(3, GearSlot.LEGS, false, 999_999));
		PvpRisk.Assessment risk = PvpRisk.assess(loadout, null, 3);
		Assert.assertEquals(0, risk.riskGp);
		Assert.assertEquals(1, risk.kept.size());
	}

	@Test
	public void theCarriedSpecWeaponCompetesForKeptSlotsAndCanDisplaceCheaperGear()
