		// Unknowns must not smuggle into "low-risk" sets for free.
		Loadout loadout = worn(
			untradeable(2, "Some future combat relic", GearSlot.BODY, SOME_DEFENCE));
		PvpRisk.Assessment risk = PvpRisk.assess(loadout, null, 3);
