package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.Map;
import java.util.Set;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Quest rewards join the candidate pool ONLY when the upgrade budget is on
 * (OWNED_OR_BUDGET) - the budget is the "show me obtainable gear" switch -
 * and they never charge the budget: they cost effort, not gp.
 */
public class QuestRewardPoolTest
{
	private static final int WHIP = 4151;
	private static final int BARROWS_GLOVES = 7462;

	private static LoadoutData data;
	private static MonsterStats graardor;

	@BeforeClass
	public static void load()
	{
		data = new DataService().load();
		// A meleeable monster where barrows gloves' offensive bonuses matter.
		graardor = data.searchMonsters("graardor", 1).get(0);
	}

	private static OptimizationRequest owned(Map<Integer, Integer> owned, int budgetGp)
	{
		return TestRequests.of(graardor, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, budgetGp,
			budgetGp > 0 ? CandidateMode.OWNED_OR_BUDGET : CandidateMode.OWNED_ONLY,
			true, false, new OwnedItems(data.canonicalizeOwned(owned), true), 1);
	}

	private static String handsName(DpsResult result)
	{
		GearItem hands = result.getLoadout().get(GearSlot.HANDS);
		return hands == null ? "" : hands.getName();
	}

	@Test
	public void barrowsGlovesJoinTheBudgetSearchWithoutBeingOwned()
	{
		// Owned: just a whip. With a budget on, the untradeable barrows
		// gloves (Recipe for Disaster) are obtainable and dominate the
		// hands slot for melee.
		DpsResult best = new LoadoutOptimizer()
			.optimize(data, owned(Map.of(WHIP, 1), 100_000)).get(0);
		Assert.assertEquals("Barrows gloves", handsName(best));
	}

	@Test
	public void withoutABudgetQuestRewardsStayOutOfAnOwnedOnlySearch()
	{
		DpsResult best = new LoadoutOptimizer()
			.optimize(data, owned(Map.of(WHIP, 1), 0)).get(0);
		Assert.assertNotEquals("Barrows gloves", handsName(best));
	}

	@Test
	public void questRewardsNeverChargeTheUpgradeBudget()
	{
		// A 1 gp budget cannot BUY anything real, but quest rewards are
		// free against it: the tradeable helm of neitiznot (The Fremennik
		// Isles, ~50k on the GE) must still surface, and the total
		// purchase cost must stay within the 1 gp budget - proof its
		// price was never charged.
		DpsResult best = new LoadoutOptimizer()
			.optimize(data, owned(Map.of(WHIP, 1), 1)).get(0);
		GearItem head = best.getLoadout().get(GearSlot.HEAD);
		Assert.assertNotNull(head);
		Assert.assertEquals("Helm of Neitiznot", head.getName());
		Assert.assertTrue("spent " + best.getPurchaseCost(), best.getPurchaseCost() <= 1);
	}

	@Test
	public void anExcludedQuestRewardStaysOut()
	{
		OptimizationRequest req = owned(Map.of(WHIP, 1), 100_000)
			.withExcludedItems(Set.of(BARROWS_GLOVES));
		DpsResult best = new LoadoutOptimizer().optimize(data, req).get(0);
		Assert.assertNotEquals("Barrows gloves", handsName(best));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Dizana's quiver carries the arrows, freeing the ammo slot for a
 * blessing - the blowpipe treatment (field report 2026-08-07). Wiki
 * rule: with a non-ammunition item in the ammo slot, the quiver's
 * stored ammunition fires at full ranged strength.
 */
class QuiverAmmoTest
{
	private static LoadoutData data;
	private static MonsterStats target;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
		target = data.searchMonsters("general graardor", 1).get(0);
	}

	private static GearItem byName(String nameLower)
	{
		for (GearItem g : data.getGearItems())
		{
			if (g.getNameLower().equals(nameLower) && g.isStandardGear())
			{
				return g;
			}
		}
		throw new AssertionError("corpus is missing: " + nameLower);
	}

	private static OptimizationRequest req()
	{
		return TestRequests.of(target, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
	}

	private static Loadout worn(String weapon, String ammo, String cape)
	{
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byName(weapon));
		if (ammo != null)
		{
			gear.put(GearSlot.AMMO, byName(ammo));
		}
		if (cape != null)
		{
			gear.put(GearSlot.CAPE, byName(cape));
		}
		return new Loadout(gear);
	}

	@Test
	@DisplayName("the fill pass moves a bow's arrows into the quiver and frees the slot")
	void bowArrowsRelocate()
	{
		OptimizationRequest request = req();
		Loadout start = worn("magic shortbow (i)", "amethyst arrow", "blessed dizana's quiver");
		DpsResult base = new DpsCalculator().calculate(request, start);
		assertNotNull(base);

		DpsResult filled = new LoadoutOptimizer().fillDpsNeutralSlots(data, request, base);
		GearItem carried = filled.getLoadout().getQuiverAmmo();
		assertNotNull(carried, "the arrows must ride the quiver");
		assertEquals("Amethyst arrow", carried.getName());
		GearItem slot = filled.getLoadout().get(GearSlot.AMMO);
		assertTrue(slot == null || slot.getBonuses().getRangedStrength() == 0,
			"the freed slot holds a passive item (blessing), never firing ammo: "
				+ (slot == null ? "empty" : slot.label()));
		assertTrue(filled.getDps() >= base.getDps() - 1e-9,
			"the relocation is dps-neutral or better");
		assertTrue(filled.getMaxHit() >= base.getMaxHit(),
			"the arrows' ranged strength still counts from the quiver");
	}

	@Test
	@DisplayName("the roster relocation helper frees the ammo slot on its own")
	void rosterRelocationHelper()
	{
		// The roster path calls relocateQuiverAmmo (not the full sweep) on
		// each shown set (field report 2026-08-09: a roster BiS kept the
		// arrow in the ammo slot instead of Rada's). It relocates AND fills
		// the freed slot, exactly like the sweep's quiver branch, with no
		// other slot touched.
		OptimizationRequest request = req();
		Loadout start = worn("magic shortbow (i)", "amethyst arrow", "blessed dizana's quiver");
		DpsResult base = new DpsCalculator().calculate(request, start);
		assertNotNull(base);

		DpsResult moved = new LoadoutOptimizer().relocateQuiverAmmo(data, request, base);
		assertEquals("Amethyst arrow", moved.getLoadout().getQuiverAmmo().getName(),
			"the arrows must ride the quiver");
		GearItem slot = moved.getLoadout().get(GearSlot.AMMO);
		assertTrue(slot == null || slot.getBonuses().getRangedStrength() == 0,
			"the freed slot holds a passive, never firing ammo: "
				+ (slot == null ? "empty" : slot.label()));
		assertTrue(moved.getDps() >= base.getDps() - 1e-9, "relocation is dps-neutral");
		assertTrue(moved.getMaxHit() >= base.getMaxHit(), "the quiver still fires the arrows");
	}

	@Test
	@DisplayName("the roster helper no-ops on a set without a relocatable quiver")
	void rosterRelocationNoOp()
	{
		OptimizationRequest request = req();
		Loadout plain = worn("twisted bow", "dragon arrow", "ava's assembler");
		DpsResult base = new DpsCalculator().calculate(request, plain);
		DpsResult moved = new LoadoutOptimizer().relocateQuiverAmmo(data, request, base);
		assertSame(base, moved, "no quiver, no change - same object back");
		assertNull(new LoadoutOptimizer().relocateQuiverAmmo(data, request, null));
	}

	@Test
	@DisplayName("a re-show prices the relocated set identically")
	void reShowParity()
	{
		OptimizationRequest request = req();
		Loadout start = worn("magic shortbow (i)", "amethyst arrow", "blessed dizana's quiver");
		DpsResult base = new DpsCalculator().calculate(request, start);

		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(start.getGear());
		GearItem arrows = gear.remove(GearSlot.AMMO);
		Loadout relocated = Loadout.adopting(gear).withQuiverAmmo(arrows);
		DpsResult reShown = new DpsCalculator().calculate(request, relocated);
		assertNotNull(reShown);
		assertEquals(base.getDps(), reShown.getDps(), 1e-9,
			"quiver-carried arrows must price exactly like slot arrows");
		assertEquals(base.getMaxHit(), reShown.getMaxHit());
	}

	@Test
	@DisplayName("accuracy-bearing arrows keep their bonus from the quiver")
	void accuracyParity()
	{
		// Field report 2026-08-09: Seeking dragon arrows carry +20 ranged
		// ACCURACY; pricing only the strength made the relocation
		// dps-negative and the ammo slot never freed for a blessing. The
		// quiver's extra slot is worn equipment - full stats count.
		OptimizationRequest request = req();
		Loadout start = worn("twisted bow", "seeking dragon arrow", "blessed dizana's quiver");
		DpsResult base = new DpsCalculator().calculate(request, start);
		assertNotNull(base);

		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(start.getGear());
		GearItem arrows = gear.remove(GearSlot.AMMO);
		Loadout relocated = Loadout.adopting(gear).withQuiverAmmo(arrows);
		DpsResult reShown = new DpsCalculator().calculate(request, relocated);
		assertNotNull(reShown);
		assertEquals(base.getDps(), reShown.getDps(), 1e-9,
			"the +20 accuracy must survive the relocation");
		assertEquals(base.getAccuracy(), reShown.getAccuracy(), 1e-9);
	}

	@Test
	@DisplayName("crossbow bolts relocate; a ballista's javelins and a plain cape do not")
	void scoping()
	{
		assertTrue(QuiverAmmo.relocatable(
			worn("dragon crossbow", "ruby dragon bolts (e)", "blessed dizana's quiver")));
		assertFalse(QuiverAmmo.relocatable(
			worn("heavy ballista", "dragon javelin", "blessed dizana's quiver")),
			"the quiver holds arrows and bolts, not javelins");
		assertFalse(QuiverAmmo.relocatable(
			worn("magic shortbow (i)", "amethyst arrow", "ava's assembler")),
			"no quiver, no relocation");
		assertFalse(QuiverAmmo.relocatable(
			worn("toxic blowpipe", null, "blessed dizana's quiver")),
			"a blowpipe's darts are its own business");
	}
}

