package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class RatBoneRulesTest
{
	private static LoadoutData data;

	private static LoadoutData data()
	{
		if (data == null)
		{
			data = new DataService().load();
		}
		return data;
	}

	private static OptimizationRequest request(MonsterStats monster, CombatStyle style)
	{
		return new OptimizationRequest(
			monster, style, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
	}

	private static DpsResult calculate(MonsterStats monster, CombatStyle style, int weaponId)
	{
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, data().getGear(weaponId));
		return new DpsCalculator().calculate(request(monster, style), new Loadout(gear));
	}

	@Test
	public void boneStaffCannotBeUsedAgainstNonRats()
	{
		MonsterStats goblin = data().searchMonsters("goblin", 1).get(0);
		Assert.assertNull(calculate(goblin, CombatStyle.MAGIC, 28796));
		// And a player who owns one is never told to bring it.
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(28796, 1);
		OptimizationRequest ownedMagic = new OptimizationRequest(
			goblin, CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 5);
		for (DpsResult result : new LoadoutOptimizer().optimize(data(), ownedMagic))
		{
			Assert.assertNotEquals(28796, result.getLoadout().getWeapon().getId());
		}
	}

	@Test
	public void boneStaffHitsThirtyEightAgainstScurriusAtMaxed()
	{
		MonsterStats scurrius = data().searchMonsters("scurrius", 1).get(0);
		Assert.assertTrue(scurrius.hasAttribute("rat"));
		// Prayer-less, to match the wiki's max-hit table exactly.
		OptimizationRequest request = new OptimizationRequest(
			scurrius, CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, data().getGear(28796));
		DpsResult result = new DpsCalculator().calculate(request, new Loadout(gear));
		Assert.assertNotNull(result);
		// Wiki max-hit table: 38 at 99 Magic (trident scaling + rat bonus).
		Assert.assertEquals(38, result.getMaxHit());
	}

	@Test
	public void boneMaceGetsTheRatBonusOnlyAgainstRats()
	{
		MonsterStats scurrius = data().searchMonsters("scurrius", 1).get(0);
		MonsterStats goblin = data().searchMonsters("goblin", 1).get(0);
		Assert.assertEquals(10, RatBoneRules.flatMaxHitBonus(scurrius, data().getGear(28792)));
		Assert.assertEquals(0, RatBoneRules.flatMaxHitBonus(goblin, data().getGear(28792)));
		Assert.assertFalse(RatBoneRules.canUse(goblin, data().getGear(28792)));
	}

	@Test
	public void gameBestMagicAgainstNonRatsIsNeverTheBoneStaff()
	{
		MonsterStats goblin = data().searchMonsters("goblin", 1).get(0);
		List<DpsResult> results = new LoadoutOptimizer().optimize(data(), request(goblin, CombatStyle.MAGIC));
		Assert.assertFalse(results.isEmpty());
		Assert.assertNotEquals(28796, results.get(0).getLoadout().getWeapon().getId());
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;

/** Zulrah demands a recoil source; the optimizer must actually bring one. */
public class RequiredUtilityTest
{
	private static LoadoutData data;
	private static MonsterStats zulrah;
	private static final java.util.Set<Integer> RECOIL_IDS =
		java.util.Set.of(2550, 20655, 20657, 28945);

	@BeforeClass
	public static void load()
	{
		data = new DataService().load();
		zulrah = data.searchMonsters("zulrah", 1).get(0);
	}

	private static DpsResult best(OptimizationRequest request)
	{
		LoadoutOptimizer optimizer = new LoadoutOptimizer();
		DpsResult result = optimizer.optimize(data, request).get(0);
		result = optimizer.fillDpsNeutralSlots(data, request, result);
		return optimizer.ensureRequiredUtility(data, request, result);
	}

	private static boolean hasRecoil(DpsResult result)
	{
		for (GearItem item : result.getLoadout().getGear().values())
		{
			if (item != null && RECOIL_IDS.contains(item.getId()))
			{
				return true;
			}
		}
		return false;
	}

	@Test
	public void theGameBestZulrahSetCarriesARecoilSource()
	{
		OptimizationRequest req = TestRequests.of(zulrah, CombatStyle.RANGED,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, 0, CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		Assert.assertTrue(hasRecoil(best(req)));
	}

	@Test
	public void anUnchargedSufferingCountsAsAccessToTheRecoilForm()
	{
		// Own tbow + arrows + an UNCHARGED suffering (i): the set must show
		// the Recoil-charged form (20657) in the ring slot.
		OptimizationRequest req = TestRequests.of(zulrah, CombatStyle.RANGED,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, 0, CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(data.canonicalizeOwned(Map.of(20997, 1, 11212, 200, 19710, 1)), true), 1);
		DpsResult result = best(req);
		GearItem ring = result.getLoadout().get(GearSlot.RING);
		Assert.assertNotNull(ring);
		Assert.assertEquals(20657, ring.getId());
	}

	@Test
	public void owningNoRecoilSourceLeavesTheSetUnchanged()
	{
		OptimizationRequest req = TestRequests.of(zulrah, CombatStyle.RANGED,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, 0, CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(data.canonicalizeOwned(Map.of(20997, 1, 11212, 200)), true), 1);
		Assert.assertFalse(hasRecoil(best(req)));
	}

	@Test
	public void nonZulrahMonstersAreUntouchedByTheRecoilRule()
	{
		MonsterStats graardor = data.searchMonsters("general graardor", 1).get(0);
		Assert.assertFalse(RequiredUtility.requiresRecoil(graardor));
		Assert.assertTrue(RequiredUtility.requiresRecoil(zulrah));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The wear-requirements backfill (2026-07 player audit A1.1): the curated
 * file's coverage stopped ~Feb 2022, so ~4 years of meta gear had no
 * requirement rows and was recommended to accounts that cannot wear it
 * (a fang at 40 Attack; a 500m budget buying Oathplate for a fresh
 * account). These lock the flagship rows - all wiki-cited, 2026-07-15.
 */
class RequirementsBackfillTest
{
	private static LoadoutData data;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
	}

	private static GearItem byName(String nameLower)
	{
		for (GearItem item : data.getGearItems())
		{
			if (item.getNameLower().equals(nameLower))
			{
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + nameLower);
	}

	private static RequirementProfile freshAccount()
	{
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.ATTACK, 40);
		levels.put(Skill.STRENGTH, 40);
		levels.put(Skill.DEFENCE, 30);
		levels.put(Skill.RANGED, 30);
		levels.put(Skill.MAGIC, 25);
		return new RequirementProfile(levels, java.util.Set.of());
	}

	@Test
	@DisplayName("post-2022 flagship gear now carries its wiki requirements")
	void flagshipRowsExist()
	{
		assertEquals(82, byName("osmumten's fang").getRequirements().getSkills().get("attack"));
		assertEquals(85, byName("tumeken's shadow").getRequirements().getSkills().get("magic"));
		assertEquals(80, byName("torva full helm").getRequirements().getSkills().get("defence"));
		assertEquals(80, byName("masori mask").getRequirements().getSkills().get("ranged"));
		assertEquals(75, byName("voidwaker").getRequirements().getSkills().get("attack"));
		assertEquals(78, byName("oathplate chest").getRequirements().getSkills().get("defence"));
		assertEquals(80, byName("zaryte crossbow").getRequirements().getSkills().get("ranged"));
		// Avernic treads gate on four skills at 80.
		Map<String, Integer> treads = byName("avernic treads").getRequirements().getSkills();
		assertEquals(80, treads.get("defence"));
		assertEquals(80, treads.get("strength"));
		assertEquals(80, treads.get("ranged"));
		assertEquals(80, treads.get("magic"));
	}

	@Test
	@DisplayName("stale rows corrected: bowfa is 80 Ranged + 70 Agility, saeldor 80 Attack")
	void staleRowsCorrected()
	{
		Map<String, Integer> bowfa = byName("bow of faerdhinen").getRequirements().getSkills();
		assertEquals(80, bowfa.get("ranged"));
		assertEquals(70, bowfa.get("agility"));
		assertEquals(80, byName("blade of saeldor").getRequirements().getSkills().get("attack"));
	}

	@Test
	@DisplayName("a 40-Attack fresh account can no longer equip the fang (the audit's headline repro)")
	void freshAccountCannotWearFang()
	{
		RequirementProfile fresh = freshAccount();
		assertFalse(fresh.canEquip(byName("osmumten's fang").getRequirements()));
		assertFalse(fresh.canEquip(byName("masori body").getRequirements()));
		assertFalse(fresh.canEquip(byName("tumeken's shadow").getRequirements()));
		assertFalse(fresh.canEquip(byName("oathplate helm").getRequirements()));
		// Sanity: gear in their bracket still fits.
		assertTrue(fresh.canEquip(byName("rune scimitar").getRequirements()));
		assertTrue(RequirementProfile.MAXED.canEquip(byName("osmumten's fang").getRequirements()));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterNotes;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The Sire's vents take "magic, ranged or a halberd" only, and a melee
 * demonbane hit destroys one outright (wiki-verified 2026-08-05). Standard
 * melee was being recommended - a whip line vs a target it cannot damage.
 */
class RespiratorySystemTest
{
	private static LoadoutData data;
	private static MonsterStats vents;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
		vents = data.searchMonsters("respiratory system", 1).get(0);
		assertEquals(5914, vents.getId(), "test premise: the corpus vent row");
	}

	private static GearItem byName(String nameLower)
	{
		for (GearItem item : data.getGearItems())
		{
			if (item.getNameLower().equals(nameLower))
			{
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + nameLower);
	}

	/** A loadout wielding just this weapon. */
	private static Loadout wielding(String nameLower)
	{
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byName(nameLower));
		return new Loadout(gear);
	}

	@Test
	@DisplayName("standard melee can never work on a vent; halberds and demonbane can")
	void meleeGating()
	{
		assertFalse(MonsterMechanics.weaponCanEverWork(vents, CombatStyle.MELEE,
			byName("abyssal whip")), "a whip cannot damage the vents");
		assertFalse(MonsterMechanics.weaponCanEverWork(vents, CombatStyle.MELEE,
			byName("osmumten's fang")), "a stab sword cannot damage the vents");
		assertTrue(MonsterMechanics.weaponCanEverWork(vents, CombatStyle.MELEE,
			byName("crystal halberd")), "halberds are the melee exception");
		assertTrue(MonsterMechanics.weaponCanEverWork(vents, CombatStyle.MELEE,
			byName("arclight")), "melee demonbane one-shots a vent");
		assertTrue(MonsterMechanics.weaponCanEverWork(vents, CombatStyle.RANGED,
			byName("toxic blowpipe")), "ranged is unaffected by the melee gate");
	}

	@Test
	@DisplayName("the melee pick vs a vent is a halberd or demonbane, never a whip line")
	void optimizerRespectsTheGate()
	{
		OptimizationRequest request = TestRequests.of(vents,
			CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		List<DpsResult> out = new LoadoutOptimizer().optimize(data, request);
		assertFalse(out.isEmpty());
		GearItem weapon = out.get(0).getLoadout().getWeapon();
		assertTrue("Polearm".equals(weapon.getCategory()) || weapon.isMeleeDemonbane(),
			"melee pick must be a halberd or demonbane, was: " + weapon.label());
	}

	@Test
	@DisplayName("the math agrees with the pool: a whip does ZERO dps to a vent")
	void calculateAgreesWithTheGate()
	{
		// The candidate pool filters standard melee out, but re-show paths
		// (the roster kit pass, shared-set evaluation) call calculate()
		// directly - without the damageFactor rule a whip line rendered a
		// phantom 6.97 dps against the vents (found 2026-08-05 while
		// chasing the roster dashes).
		DpsResult whip = new DpsCalculator().calculate(req(vents), wielding("abyssal whip"));
		assertTrue(whip == null || whip.getDps() == 0.0,
			"a whip must deal zero to the vents, got "
				+ (whip == null ? "null" : whip.getDps()));

		DpsResult halberd = new DpsCalculator().calculate(req(vents), wielding("crystal halberd"));
		assertTrue(halberd != null && halberd.getDps() > 0,
			"a halberd must still land");
	}

	@Test
	@DisplayName("a demonbane hit is modeled as the one-shot it is, in every style")
	void demonbaneOneShotMath()
	{
		DpsResult arclight = new DpsCalculator().calculate(req(vents), wielding("arclight"));
		assertNotNull(arclight);
		assertEquals(vents.getHitpoints(), arclight.getMaxHit(),
			"a demonbane max hit vs a vent is the vent's whole hp bar");
		assertEquals(arclight.getAccuracy() * vents.getHitpoints(),
			arclight.getExpectedHit(), 1e-6);
	}

	@Test
	@DisplayName("the bow beats melee demonbane at the vents: no walking between them")
	void rangedDemonbaneOutranksMeleeDemonbane()
	{
		DpsResult bow = new DpsCalculator().calculate(
			TestRequests.of(vents, CombatStyle.RANGED, PlayerLevels.MAXED,
				PrayerBonuses.NONE, null, 0, CandidateMode.ALL_STANDARD, true, false,
				OwnedItems.EMPTY, 1), wielding("scorching bow"));

		DpsResult ember = new DpsCalculator().calculate(req(vents), wielding("emberlight"));

		assertNotNull(bow);
		assertNotNull(ember);
		assertTrue(bow.getDps() > ember.getDps() * 1.5,
			"one spot vs four walks: the bow must lead decisively, got bow="
				+ bow.getDps() + " vs melee=" + ember.getDps());

		// The melee interval carries exactly the published walk penalty.
		int reach = MonsterMechanics.meleeReachPenaltyTicks(vents);
		assertTrue(reach > 0, "the vents must publish a melee reach penalty");
		assertEquals(
			ember.getAccuracy() * vents.getHitpoints()
				/ ((ember.getAttackSpeed() + reach) * 0.6),
			ember.getDps(), 1e-6);
	}

	@Test
	@DisplayName("the ranged pick vs a vent is the Scorching bow, not a blowpipe")
	void scorchingBowBeatsTheBlowpipe()
	{
		OptimizationRequest request = TestRequests.of(vents,
			CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		List<DpsResult> out = new LoadoutOptimizer().optimize(data, request);
		assertFalse(out.isEmpty());
		assertTrue(out.get(0).getLoadout().getWeapon().getNameLower().startsWith("scorching bow"),
			"the one-shot must out-rank ordinary ranged dps, was: "
				+ out.get(0).getLoadout().getWeapon().label());
	}

	@Test
	@DisplayName("every other landed hit deals at least half its max (1.5x expectation)")
	void minHitScalesTheExpectation()
	{
		// Compare mean damage PER LANDED HIT (expected/accuracy) against the
		// same weapon at a plain target: gear and levels identical, so the
		// only difference is the vents' min-hit rule. Asserting against a
		// reconstructed acc*max*0.75 was ~0.2% off - the base roll model has
		// its own subtleties; the 1.5x scaling is the contract.
		Loadout halberd = wielding("crystal halberd");

		MonsterStats goblin = data.searchMonsters("goblin", 1).get(0);
		DpsResult atVents = new DpsCalculator().calculate(req(vents), halberd);
		DpsResult atGoblin = new DpsCalculator().calculate(req(goblin), halberd);
		assertNotNull(atVents);
		assertNotNull(atGoblin);
		double meanVents = atVents.getExpectedHit() / atVents.getAccuracy();
		double meanPlain = atGoblin.getExpectedHit() / atGoblin.getAccuracy();
		assertEquals(1.5, meanVents / meanPlain, 1e-9,
			"the vents' min-hit must scale the per-hit mean by exactly 1.5");
	}

	private static OptimizationRequest req(MonsterStats monster)
	{
		return TestRequests.of(monster,
			CombatStyle.MELEE, PlayerLevels.MAXED, PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
	}

	@Test
	@DisplayName("the vents and Sire phase 1 carry their mechanics notes")
	void notesPresent()
	{
		assertNotNull(MonsterNotes.noteFor(vents));
		MonsterStats phase1 = data.searchMonsters("abyssal sire", 4).stream()
			.filter(m -> m.getVersion() != null && m.getVersion().startsWith("Phase 1"))
			.findFirst().orElseThrow();
		String note = MonsterNotes.noteFor(phase1);
		assertNotNull(note);
		assertTrue(note.contains("Shadow"), "phase 1 note names the shadow-spell disorient");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Revenant / wilderness gear conditionals, mirrored from the wiki calc:
 * avarice heads the non-stacking salve/slayer chain (6/5 vs revenants),
 * charged wilderness weapons get 3/2 accuracy AND damage vs wilderness
 * monsters, and a charged bracelet of ethereum zeroes revenant damage.
 */
class RevenantConditionalsTest
{
	private static LoadoutData data;
	private static MonsterStats revDemon;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
		revDemon = data.searchMonsters("revenant demon", 1).get(0);
	}

	private static GearItem byName(String name, String version)
	{
		for (GearItem item : data.getGearItems())
		{
			if (item.getNameLower().equals(name)
				&& (version == null || version.equalsIgnoreCase(item.getVersionLower())))
			{
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + name + " (" + version + ")");
	}

	private static Loadout worn(GearItem... items)
	{
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		for (GearItem item : items)
		{
			gear.put(item.getSlot(), item);
		}
		return new Loadout(gear);
	}

	private static OptimizationRequest request(MonsterStats monster, CombatStyle style)
	{
		return new OptimizationRequest(monster, style, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
	}

	@Test
	@DisplayName("the wilderness weapon buff needs a wilderness monster AND the charged version")
	void revWeaponBuffGates()
	{
		OptimizationRequest atRevs = request(revDemon, CombatStyle.RANGED);
		OptimizationRequest atGoblin =
			request(data.searchMonsters("goblin", 1).get(0), CombatStyle.RANGED);

		Loadout charged = worn(byName("craw's bow", "charged"));
		Loadout uncharged = worn(byName("craw's bow", "uncharged"));

		assertTrue(DpsCalculator.revWeaponBuff(atRevs, charged, "craw's bow", "webweaver bow"));
		assertFalse(DpsCalculator.revWeaponBuff(atRevs, uncharged, "craw's bow", "webweaver bow"),
			"uncharged gets no buff");
		assertFalse(DpsCalculator.revWeaponBuff(atGoblin, charged, "craw's bow", "webweaver bow"),
			"no buff outside the wilderness");
		assertTrue(DpsCalculator.isRevenant(atRevs));
		assertFalse(DpsCalculator.isRevenant(atGoblin));
	}

	@Test
	@DisplayName("a charged craw's bow at revenants outputs more dps than the raw stats say")
	void crawsBowBuffShowsUpInDps()
	{
		Loadout charged = worn(byName("craw's bow", "charged"));
		DpsResult atRevs = new DpsCalculator().calculate(request(revDemon, CombatStyle.RANGED), charged);
		assertNotNull(atRevs);

		// The same loadout against the same defensive stat sheet without
		// the wilderness gate cannot be built from data (the gate IS the
		// monster), so pin the observable instead: with 3/2 on accuracy
		// and damage the charged bow must clear the strongest unbuffed
		// owned-tier bow in the corpus at revs - the meta this models.
		Loadout msb = worn(byName("magic shortbow", null), byName("amethyst arrow", null));
		DpsResult msbAtRevs = new DpsCalculator().calculate(request(revDemon, CombatStyle.RANGED), msb);
		assertNotNull(msbAtRevs);
		assertTrue(atRevs.getDps() > msbAtRevs.getDps() * 1.4,
			"buffed craw's should dominate: craws=" + atRevs.getDps() + " msb=" + msbAtRevs.getDps());
		assertTrue(atRevs.getCountedBonuses().contains("wilderness weapon: +50% accuracy, +50% damage"),
			"the counted-bonus assurance must name the buff with its exact numbers, got: "
				+ atRevs.getCountedBonuses());
	}

	@Test
	@DisplayName("avarice heads the salve chain at revenants: it beats the same neck stats unbuffed")
	void avariceBeatsFuryAtRevenants()
	{
		Loadout base = worn(byName("magic shortbow", null), byName("amethyst arrow", null),
			byName("amulet of fury", null));
		Loadout avarice = worn(byName("magic shortbow", null), byName("amethyst arrow", null),
			byName("amulet of avarice", null));

		DpsResult withFury = new DpsCalculator().calculate(request(revDemon, CombatStyle.RANGED), base);
		DpsResult withAvarice = new DpsCalculator().calculate(request(revDemon, CombatStyle.RANGED), avarice);
		assertTrue(withAvarice.getDps() > withFury.getDps(),
			"avarice=" + withAvarice.getDps() + " fury=" + withFury.getDps());
	}

	@Test
	@DisplayName("Max DPS keeps the offensive gloves over the ethereum bracelet at revenants")
	void maxDpsKeepsGloves()
	{
		// msb + amethyst arrows + barrows gloves + charged ethereum owned:
		// the small glove dps gain must beat the zero-offense bracelet.
		OwnedItems owned = new OwnedItems(java.util.Map.of(
			861, 1, 21326, 100, 7462, 1, 21816, 1), true);
		OptimizationRequest base = new OptimizationRequest(revDemon, CombatStyle.RANGED,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false, owned, RequirementProfile.MAXED, 1);

		GearItem dpsHands = new LoadoutOptimizer()
			.optimize(data, base)
			.get(0).getLoadout().get(GearSlot.HANDS);
		assertNotNull(dpsHands);
		assertEquals("barrows gloves", dpsHands.getNameLower(),
			"Max DPS must keep the offensive gloves, got: " + dpsHands.getNameLower());
	}

	@Test
	@DisplayName("a charged bracelet of ethereum zeroes revenant incoming damage")
	void ethereumZeroesIncoming()
	{
		Loadout with = worn(byName("bracelet of ethereum", "charged"));
		Loadout without = worn(byName("bracelet of ethereum", "uncharged"));

		IncomingDpsCalculator.Result blocked =
			IncomingDpsCalculator.calculate(revDemon, with, 99, 99);
		IncomingDpsCalculator.Result normal =
			IncomingDpsCalculator.calculate(revDemon, without, 99, 99);

		assertEquals(0.0, blocked.totalDps);
		assertEquals(0.0, blocked.unprayedDps);
		assertTrue(normal.unprayedDps > 0, "uncharged bracelet does not block");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * OPTIMIZER-LEVEL coverage for the revenant conditionals - the layer the
 * unit tests missed (field report: the DPS math was verified correct but
 * the candidate pool never surfaced the items, so nothing on screen
 * changed). These run the real search end to end, the same path the
 * panel and the headless query render.
 */
class RevenantPoolTest
{
	private static LoadoutData data;
	private static MonsterStats revDemon;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
		revDemon = data.searchMonsters("revenant demon", 1).get(0);
	}

	private static OptimizationRequest request(CandidateMode mode, OwnedItems owned)
	{
		return new OptimizationRequest(revDemon, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			mode, true, false, owned, RequirementProfile.MAXED, 1);
	}

	@Test
	@DisplayName("game best at revenants reaches for a charged wilderness bow")
	void gameBestFindsTheWildernessBow()
	{
		List<DpsResult> results = new LoadoutOptimizer()
			.optimize(data, request(CandidateMode.ALL_STANDARD, OwnedItems.EMPTY));
		assertFalse(results.isEmpty());

		DpsResult best = results.get(0);
		String weapon = best.getLoadout().get(GearSlot.WEAPON).getNameLower();
		String version = best.getLoadout().get(GearSlot.WEAPON).getVersionLower();
		assertTrue(weapon.contains("webweaver") || weapon.contains("craw's"),
			"expected a wilderness bow, got: " + weapon);
		assertEquals("charged", version,
			"only the charged version fires the +50% passive");
		assertTrue(best.getDps() > 12.0,
			"the buffed ceiling must clear the old 11.58 plateau, got " + best.getDps());
	}

	@Test
	@DisplayName("an owned charged craw's bow wins the owned search at revenants")
	void ownedCrawsBowGetsPicked()
	{
		// Craw's bow charged (22550) vs a magic shortbow (861) + amethyst
		// arrows (21326): without the pool fix the charged bow never even
		// reached the DPS calculator.
		OwnedItems owned = new OwnedItems(
			Map.of(22550, 1, 861, 1, 21326, 100), true);
		List<DpsResult> results = new LoadoutOptimizer()
			.optimize(data, request(CandidateMode.OWNED_ONLY, owned));
		assertFalse(results.isEmpty());
		String weapon = results.get(0).getLoadout().get(GearSlot.WEAPON).getNameLower();
		assertTrue(weapon.contains("craw's"), "expected craw's bow, got: " + weapon);
	}

	@Test
	@DisplayName("low-risk sets NEVER risk a rebuild item, no matter the cap")
	void lowRiskNeverRisksARebuildItem()
	{
		for (int cap : new int[]{25_000, 5_000_000})
		{
			OptimizationRequest constrained = request(CandidateMode.ALL_STANDARD, OwnedItems.EMPTY)
				.withMaxTradeables(3).withRiskBudgetGp(cap);
			List<DpsResult> results = new LoadoutOptimizer().optimize(data, constrained);
			assertFalse(results.isEmpty());
			com.loadoutlab.data.GearItem neck =
				results.get(0).getLoadout().get(GearSlot.NECK);
			assertTrue(neck == null || !neck.getNameLower().contains("salve"),
				"an unprotectable salve may never ride a low-risk set (cap " + cap
					+ "), got: " + (neck == null ? "empty" : neck.getNameLower()));
		}
	}

	@Test
	@DisplayName("the ethereum bracelet and avarice survive the candidate pool at revenants")
	void conditionalItemsSurviveThePool()
	{
		// Zero-stat hands (ethereum) died at the zero-score prune; the
		// score boosts must keep both alive ONLY at revenants.
		OptimizationRequest atRevs = request(CandidateMode.ALL_STANDARD, OwnedItems.EMPTY);
		OptimizationRequest atGoblin = new OptimizationRequest(
			data.searchMonsters("goblin", 1).get(0), CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, RequirementProfile.MAXED, 1);

		com.loadoutlab.data.GearItem ethereum = null;
		com.loadoutlab.data.GearItem avarice = null;
		for (com.loadoutlab.data.GearItem item : data.getGearItems())
		{
			if (item.getNameLower().equals("bracelet of ethereum")
				&& "charged".equals(item.getVersionLower()))
			{
				ethereum = item;
			}
			if (item.getNameLower().equals("amulet of avarice"))
			{
				avarice = item;
			}
		}
		assertNotNull(ethereum);
		assertNotNull(avarice);

		assertTrue(LoadoutOptimizer.candidateScoreForTest(atRevs, ethereum) > 0,
			"ethereum must survive the zero-score prune at revenants");
		assertTrue(LoadoutOptimizer.candidateScoreForTest(atRevs, avarice)
			> LoadoutOptimizer.candidateScoreForTest(atGoblin, avarice) + 4_000,
			"avarice gets its boost only at revenants");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.WildernessMonsters;
import java.util.List;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;

public class RiskConstraintTest
{
	private static LoadoutData data;
	private static MonsterStats callisto;

	@BeforeClass
	public static void load()
	{
		data = new DataService().load();
		callisto = data.searchMonsters("callisto", 1).get(0);
	}

	private static OptimizationRequest request(CombatStyle style, int maxTradeables)
	{
		return TestRequests.of(callisto, style, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, 0, CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1)
			.withMaxTradeables(maxTradeables);
	}

	@Test
