		assertEquals(before + 1, computes.get(), "other supplies only republish");

		ops.pinned = "";
		assertTrue(engine.execute("select", Map.of("query", "goblin")));
		assertEquals("", lock.get(), "no venom, no Cure Me");
		assertEquals(1, charge.get());
	}

	@Test
