package com.loadoutlab.model;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-25: "the f2p lock seems to be working but i used to be
 * able to turn that off and see what the p2p result was on my account."
 *
 * <p>The merge-back dropped the F2P chip, so the filter could be switched on by
 * the client but never off by the player. The fix splits the two facts apart:
 * {@code f2pWorld} is where the client is (chip visibility), {@code f2pOnly} is
 * what the player asked for (the filter itself). Collapsing them back into one
 * flag is what made the control hide the moment it was used.
 */
class F2pFilterTest
{
	private static LoadoutData data;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
	}

	private static CommandEngine engine(PageState state)
	{
		return new CommandEngine(data, state,
			(mob, f2p, onTask, wild, lock, tradeables, risk, antifire, dc, spec,
				boosts, prayers, budget, swaps, onDone) ->
			{
			},
			new CompanionLink());
	}

	private static boolean flag(PageState state, String param)
	{
		return Boolean.TRUE.equals(state.paramsNode().get(param));
	}

	@Test
	@DisplayName("unticking the F2P filter leaves the chip's own visibility flag alone")
	void untickingKeepsTheChipOnScreen()
	{
		PageState state = new PageState();
		CommandEngine engine = engine(state);

		// Logging in to a non-members world: both flags go up.
		engine.execute("set-param", Map.of("param", "f2pWorld", "value", true));
		engine.execute("set-param", Map.of("param", "f2pOnly", "value", true));
		assertTrue(flag(state, "f2pWorld"));
		assertTrue(flag(state, "f2pOnly"));

		// The player unticks it to preview members gear. The chip renders from
		// f2pWorld, so it must survive - otherwise there is no way back.
		engine.execute("set-param", Map.of("param", "f2pOnly", "value", false));
		assertFalse(flag(state, "f2pOnly"), "the filter did not come off");
		assertTrue(flag(state, "f2pWorld"),
			"unticking the filter hid the chip that unticks it");

		// ...and it can be turned back on.
		engine.execute("set-param", Map.of("param", "f2pOnly", "value", true));
		assertTrue(flag(state, "f2pOnly"), "the filter could not be restored");
	}

	@Test
	@DisplayName("a members world reports neither flag")
	void membersWorldHidesTheChip()
	{
		PageState state = new PageState();
		assertFalse(flag(state, "f2pWorld"), "the chip would show on a members world");
		assertFalse(flag(state, "f2pOnly"));
	}
}

package com.loadoutlab.model;

import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field ask 2026-08-27: D charge, thralls and the slayer-task chip have no
 * meaning under the F2P lock. The lock VETOES them in the compute args
 * without clearing their params - so undo history stays coherent and
 * unticking F2P brings the old setup straight back.
 *
 * <p>computeArgs() is the single funnel into the optimizer, so the veto is
 * asserted there: position 1 = onTask, position 7 = deathCharge.
 */
class F2pVetoTest
{
	private static PageState configured()
	{
		PageState state = new PageState();
		state.setParam("onTask", true);
		state.setParam("deathCharge", 2);
		state.setParam("thralls", true);
		return state;
	}

	@Test
	@DisplayName("the F2P lock silences task and Death Charge in the compute args")
	void lockVetoesComputeArgs()
	{
		PageState state = configured();

		Object[] unlocked = state.computeArgs();
		assertEquals(Boolean.TRUE, unlocked[1], "onTask should pass through unlocked");
		assertEquals(2, unlocked[7], "deathCharge should pass through unlocked");

		state.setParam("f2pOnly", true);
		Object[] locked = state.computeArgs();
		assertEquals(Boolean.FALSE, locked[1], "the lock did not veto onTask");
		assertEquals(0, locked[7], "the lock did not veto deathCharge");
	}

	@Test
	@DisplayName("the veto never clears the params - unticking restores the setup")
	void untickRestoresEverything()
	{
		PageState state = configured();
		state.setParam("f2pOnly", true);

		Map<String, Object> params = state.paramsNode();
		assertEquals(Boolean.TRUE, params.get("onTask"),
			"the lock CLEARED onTask instead of vetoing it");
		assertEquals(2, params.get("deathCharge"),
			"the lock CLEARED deathCharge instead of vetoing it");
		assertEquals(Boolean.TRUE, params.get("thralls"),
			"the lock CLEARED thralls instead of vetoing it");

		state.setParam("f2pOnly", false);
		Object[] restored = state.computeArgs();
		assertEquals(Boolean.TRUE, restored[1], "onTask did not come back");
		assertEquals(2, restored[7], "deathCharge did not come back");
	}
}

package com.loadoutlab.model;

import java.util.List;
import java.util.Map;

/**
 * Canonical JSON for the Companion contract (docs/COMPANION_CONTRACT.md):
 * insertion-order maps, Double.toString numbers, strict escaping - the
 * same input always serializes to the same bytes, so model-snapshot
 * goldens diff like the engine goldens do. Values must be JSON-safe
 * (String, Number, Boolean, List, Map, null); anything else is a bug in
 * the model builder and fails loudly.
 */
public final class Json
{
	private Json()
	{
	}

	public static String write(Object value)
	{
		StringBuilder sb = new StringBuilder();
		append(sb, value);
		return sb.toString();
	}

	private static void append(StringBuilder sb, Object v)
	{
		if (v == null)
		{
			sb.append("null");
		}
		else if (v instanceof String)
		{
			string(sb, (String) v);
		}
		else if (v instanceof Boolean || v instanceof Integer || v instanceof Long)
		{
			sb.append(v);
		}
		else if (v instanceof Double || v instanceof Float)
		{
			double d = ((Number) v).doubleValue();
			if (Double.isNaN(d) || Double.isInfinite(d))
			{
				throw new IllegalArgumentException("non-finite number in model");
			}
			sb.append(d);
		}
		else if (v instanceof Map)
		{
			sb.append('{');
			boolean first = true;
			for (Map.Entry<?, ?> e : ((Map<?, ?>) v).entrySet())
			{
				if (!first)
				{
					sb.append(',');
				}
				first = false;
				string(sb, String.valueOf(e.getKey()));
				sb.append(':');
				append(sb, e.getValue());
			}
			sb.append('}');
		}
		else if (v instanceof List)
		{
			sb.append('[');
			boolean first = true;
			for (Object item : (List<?>) v)
			{
				if (!first)
				{
					sb.append(',');
				}
				first = false;
				append(sb, item);
			}
			sb.append(']');
		}
		else
		{
			throw new IllegalArgumentException("not JSON-safe: " + v.getClass().getName());
		}
	}

	private static void string(StringBuilder sb, String s)
	{
		sb.append('"');
		for (int i = 0; i < s.length(); i++)
		{
			char c = s.charAt(i);
			switch (c)
			{
				case '"':
					sb.append("\\\"");
					break;
				case '\\':
					sb.append("\\\\");
					break;
				case '\n':
					sb.append("\\n");
					break;
				case '\r':
					sb.append("\\r");
					break;
				case '\t':
					sb.append("\\t");
					break;
				default:
					if (c < 0x20)
					{
						sb.append(String.format("\\u%04x", (int) c));
					}
					else
					{
						sb.append(c);
					}
			}
		}
		sb.append('"');
	}
}

package com.loadoutlab.model;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterGroups;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.optimizer.OptimizerService;
import com.loadoutlab.optimizer.ServiceCalls;
import com.loadoutlab.profile.FixtureBank;
import com.loadoutlab.profile.PlayerProfile;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Model-snapshot golden (ADR-0008): the serialized render-model for a
 * scenario matrix, canonical-JSON per line. Byte-identical output is
 * the contract the Companion renders against - this locks the seam the
 * way golden/rosterGolden lock the engine, and the captured lines
 * double as the Companion repo's renderer fixtures.
 *
 *   ./gradlew -q modelGolden > model-golden.txt
 */
public final class ModelGolden
{
	/** Single mobs chosen for card-shape coverage: tri-style + spec
	 * (Graardor), recoil/venom + magic-led (Zulrah), antifire +
	 * required-gear (Vorkath), incoming-override boss (Muspah). */
	private static final String[] MOBS = {
		"general graardor", "zulrah", "vorkath", "phantom muspah",
	};

	private static final String ROSTER_GROUP = "Dagannoth Kings";
	private static final int ROSTER_BENCH = 3;

	/** A wilderness boss under the kept-on-death cap, so the risk node
	 * (and the "Kept on death:" tooltip built on it) is exercised - the
	 * gap the render baseline measured as uncovered. */
	private static final String WILDERNESS_MOB = "callisto";
	private static final int LOW_RISK_TRADEABLES = 3;

	private ModelGolden()
	{
	}

	public static void main(String[] args) throws Exception
	{
		LoadoutData data = new DataService().load();
		PlayerProfile profile = FixtureBank.profile(data);
		for (String name : MOBS)
		{
			MonsterStats mob = data.searchMonsters(name, 1).get(0);
			System.out.println("##### " + mob.label());
			System.out.println(Json.write(RenderModel.page(List.of(single(data, profile, mob)))));
		}
		MonsterStats wildy = data.searchMonsters(WILDERNESS_MOB, 1).get(0);
		System.out.println("##### " + wildy.label() + " | low-risk");
		System.out.println(Json.write(RenderModel.page(
			List.of(single(data, profile, wildy, LOW_RISK_TRADEABLES)))));

		MonsterGroups.MonsterGroup group = null;
		for (MonsterGroups.MonsterGroup candidate : MonsterGroups.load(data))
		{
			if (candidate.getName().equalsIgnoreCase(ROSTER_GROUP))
			{
				group = candidate;
			}
		}
		if (group == null)
		{
			throw new IllegalStateException("group gone: " + ROSTER_GROUP);
		}
		System.out.println("##### " + group.label() + " | bench=" + ROSTER_BENCH);
		System.out.println(Json.write(RenderModel.page(
			List.of(roster(data, profile, group.getMobs(), ROSTER_BENCH)))));
	}

	private static Map<String, Object> single(LoadoutData data, PlayerProfile profile,
		MonsterStats mob) throws Exception
	{
		return single(data, profile, mob, -1);
	}

	private static Map<String, Object> single(LoadoutData data, PlayerProfile profile,
		MonsterStats mob, int maxTradeables) throws Exception
	{
		OptimizerService service = new OptimizerService(data);
		try
		{
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			ServiceCalls.bestPerStyle(service, mob,
				profile.realLevels, profile.boostedLevels, profile.prayerUnlocks,
				profile.requirements, profile.ownedItems(), profile.owned.hashCode(),
				false, false, "", new EnumMap<>(CombatStyle.class), maxTradeables,
				OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, false,
				Collections.emptySet(), 0,
				Collections.emptyMap(), null, 0, Collections.emptySet(),
				r ->
				{
					out.set(r);
					done.countDown();
				});
			if (!done.await(300, TimeUnit.SECONDS))
			{
				throw new IllegalStateException("query timed out: " + mob.label());
			}
			// riskKeptSlots >= 0 is what emits the wilderness risk node
			// (and with it the "Kept on death:" tooltip).
			return RenderModel.entry(List.of(mob), List.of(out.get()),
				maxTradeables >= 0 ? maxTradeables : -1, null,
				java.util.Collections.emptySet(), null);
		}
		finally
		{
			service.shutdown();
		}
	}

	private static Map<String, Object> roster(LoadoutData data, PlayerProfile profile,
		List<MonsterStats> mobs, int bench) throws Exception
	{
		OptimizerService service = new OptimizerService(data);
		try
		{
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<OptimizerService.RosterResult> out = new AtomicReference<>();
			ServiceCalls.bestPerStyleAcross(service, mobs,
				profile.realLevels, profile.boostedLevels, profile.prayerUnlocks,
				profile.requirements, profile.ownedItems(), profile.owned.hashCode(),
				false, false, "", Collections.emptyMap(), -1,
				OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, false,
				Collections.emptySet(), 0, bench,
				Collections.emptyMap(), null, Collections.emptySet(),
				roster ->
				{
					out.set(roster);
					done.countDown();
				});
			if (!done.await(300, TimeUnit.SECONDS))
			{
				throw new IllegalStateException("roster query timed out");
			}
			return RenderModel.entry(out.get().mobs, out.get().perMob);
		}
		finally
		{
			service.shutdown();
		}
	}
}

package com.loadoutlab.model;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The contract's transport rules (docs/COMPANION_CONTRACT.md): pages
 * are versioned, serialization is canonical and deterministic, and
 * non-JSON-safe values fail loudly instead of leaking classes across
 * the classloader seam.
 */
class ModelShapeTest
{
	@Test
	@DisplayName("every page carries the contract version")
	void pageCarriesVersion()
	{
		Map<String, Object> page = RenderModel.page(List.of());
		assertEquals(RenderModel.VERSION, page.get("v"));
		assertTrue(Json.write(page).startsWith("{\"v\":" + RenderModel.VERSION));
	}

	@Test
	@DisplayName("canonical JSON is byte-stable and escapes strictly")
	void canonicalAndEscaped()
	{
		Map<String, Object> node = new LinkedHashMap<>();
		node.put("name", "Rada's \"blessing\"\n4\\");
		node.put("dps", 9.196969696969697d);
		node.put("hp", 240);
		node.put("none", null);
		node.put("flag", true);
		String once = Json.write(node);
		assertEquals(once, Json.write(node), "same input, same bytes");
		assertEquals("{\"name\":\"Rada's \\\"blessing\\\"\\n4\\\\\","
			+ "\"dps\":9.196969696969697,\"hp\":240,\"none\":null,\"flag\":true}", once);
	}

	@Test
	@DisplayName("non-JSON-safe values fail loudly, never cross the seam")
	void unsafeValuesRejected()
	{
		assertThrows(IllegalArgumentException.class,
			() -> Json.write(Map.of("bad", new Object())));
		assertThrows(IllegalArgumentException.class,
			() -> Json.write(Map.of("bad", Double.NaN)));
	}
}

