package com.loadoutlab.model;

import com.google.gson.Gson;
import com.loadoutlab.collection.DreamStore;
import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.testsupport.InMemoryConfigManager;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-27: "when i add things to my sim the counter is not
 * going up."
 *
 * <p>The green "+N" pill reads counts.simmedItems off the PUBLISHED page, not
 * off the store, so a toggle that persists correctly can still leave the pill
 * stale if the page is not rebuilt from the live counts. This wires the real
 * DreamStore behind the engine and asserts the number the pill would draw.
 */
class SimCounterTest
{
	private static LoadoutData data;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
	}

	/** The count the "+N" pill renders, straight off the published page. */
	private static int pillCount(CompanionLink link, String listKey)
	{
		drainEdt();
		Map<String, Object> page = link.lastPage();
		assertNotNull(page, "nothing was published");
		Map<?, ?> counts = (Map<?, ?>) page.get("counts");
		assertNotNull(counts, "the page carried no counts node");
		return ((List<?>) counts.get(listKey)).size();
	}

	/** republish() hops to the EDT, so the page lands after execute() returns. */
	private static void drainEdt()
	{
		try
		{
			javax.swing.SwingUtilities.invokeAndWait(() ->
			{
			});
		}
		catch (Exception e)
		{
			throw new IllegalStateException(e);
		}
	}

	@Test
	@DisplayName("the sim pill counts up as items are simmed")
	void simPillTracksTheStore()
	{
		DreamStore dreams = new DreamStore(InMemoryConfigManager.create(), new Gson());
		dreams.loadScope("std.1111");

		PageState state = new PageState();
		CompanionLink link = new CompanionLink();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, f2p, onTask, wild, lock, tradeables, risk, antifire, dc, spec,
				boosts, prayers, budget, swaps, onDone) ->
			{
			},
			link);
		engine.setCounts(() ->
		{
			List<Map<String, Object>> simmed = new ArrayList<>();
			for (int id : dreams.snapshot())
			{
				simmed.add(Map.of("id", id, "name", "item " + id));
			}
			Map<String, Object> counts = new LinkedHashMap<>();
			counts.put("simmed", simmed.size());
			counts.put("simmedItems", simmed);
			return counts;
		});
		engine.setStoreOps(new TestStoreOps()
		{
			@Override
			public boolean toggleSim(int itemId)
			{
				dreams.toggle(itemId);
				return true;
			}
		});

		engine.execute("toggle-sim", Map.of("itemId", 22325, "label", "item"));
		assertTrue(dreams.isDreamed(22325), "the store did not take the sim");
		assertEquals(1, pillCount(link, "simmedItems"),
			"the sim pill did not count up after the first sim");

		engine.execute("toggle-sim", Map.of("itemId", 25975, "label", "item"));
		assertEquals(2, pillCount(link, "simmedItems"),
			"the sim pill did not count up after the second sim");

		// ...and back down, since the command is self-inverse.
		engine.execute("toggle-sim", Map.of("itemId", 22325, "label", "item"));
		assertEquals(1, pillCount(link, "simmedItems"),
			"unsimming did not count the pill back down");
	}
}

package com.loadoutlab.model;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Spellbook Swap + Vengeance as a SUPPLIES option (field ask
 * 2026-08-22): it changes which runes the trip carries and nothing
 * else - the damage Vengeance returns is deliberately unmodelled.
 */
class SpellbookSwapTest
{
	private static LoadoutData data;

	@BeforeAll
	static void load()
	{
		data = new DataService().load();
	}

	private static CommandEngine engine(PageState state, CaptureLink link, int magic)
	{
		CommandEngine engine = new CommandEngine(data, state,
			(mob, f2p, onTask, wild, lock, tradeables, risk, antifire, dc, spec,
				boosts, prayers, budget, swaps, onDone) ->
			{
			},
			link);
		engine.setMagicLevel(magic);
		// utilityRunes ride the page only when stores are wired.
		engine.setStoreOps(new TestStoreOps());
		return engine;
	}

	private static List<Map<String, Object>> runesOf(Map<String, Object> page)
	{
		List<?> entries = (List<?>) page.get("entries");
		Map<?, ?> entry = (Map<?, ?>) entries.get(0);
		List<?> mobs = (List<?>) entry.get("mobs");
		Object runes = ((Map<?, ?>) mobs.get(0)).get("utilityRunes");
		return runes instanceof List ? (List<Map<String, Object>>) runes
			: java.util.Collections.emptyList();
	}

	private static void flushEdt()
	{
		try
		{
			javax.swing.SwingUtilities.invokeAndWait(() ->
			{
			});
		}
		catch (Exception ex)
		{
			throw new AssertionError(ex);
		}
	}

	@Test
	@DisplayName("the option is offered only when 96 Magic is reachable")
	void offeredOnlyWhenReachable()
	{
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine high = engine(state, link, 91);
		high.execute("select", Map.of("query", "abyssal demon"));
		high.onResults(data.searchMonsters("abyssal demon", 1).get(0), Map.of());
		flushEdt();
		assertEquals(Boolean.TRUE,
			((Map<?, ?>) link.published.get("assumeOptions")).get("spellbookSwapAvailable"),
			"91 + a boost reaches 96");

		PageState low = new PageState();
		CaptureLink lowLink = new CaptureLink();
		CommandEngine weak = engine(low, lowLink, 80);
		weak.execute("select", Map.of("query", "abyssal demon"));
		weak.onResults(data.searchMonsters("abyssal demon", 1).get(0), Map.of());
		flushEdt();
		assertEquals(Boolean.FALSE,
			((Map<?, ?>) lowLink.published.get("assumeOptions")).get("spellbookSwapAvailable"),
			"80 Magic cannot reach 96");
	}

	@Test
	@DisplayName("switching it on brings the swap and Vengeance runes")
	void bringsTheRunes()
	{
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine engine = engine(state, link, 99);
		assertTrue(engine.execute("select", Map.of("query", "abyssal demon")));
		engine.onResults(data.searchMonsters("abyssal demon", 1).get(0), Map.of());
		flushEdt();
		assertTrue(runesOf(link.published).stream()
			.noneMatch(r -> String.valueOf(r.get("why")).contains("Vengeance")),
			"off by default");

		// Thralls live on Arceuus, so this trip genuinely swaps books.
		assertTrue(engine.execute("set-param", Map.of("param", "thralls", "value", true)));
		assertTrue(engine.execute("set-param",
