/** Andrew, 2026-09-09 (Discord: gold rune gloves at the crab): "the quest
 * gating shouldn't stop barrows gloves from appearing in the bis sheet".
 * The ceiling honours the player's LEVELS (2026-08-27 ruling) but never
 * their quest log. */
class GameBestIgnoresQuestsTest
{
	@Test
	@DisplayName("game-best hands at 70/70/70 with no quests done are Barrows gloves, not a quest-free fallback")
	void barrowsGlovesInTheCeiling() throws Exception
	{
		LoadoutData data = new DataService().load();
		MonsterStats goblin = data.searchMonsters("Goblin", 1).get(0);
		EnumMap<Skill, Integer> levels = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			levels.put(skill, 99);
		}
		levels.put(Skill.ATTACK, 70);
		levels.put(Skill.STRENGTH, 70);
		levels.put(Skill.DEFENCE, 70);
		RequirementProfile noQuests = new RequirementProfile(levels, Collections.emptySet());
		PlayerLevels player = new PlayerLevels(70, 70, 70, 99, 99, 99, 99);
		Map<Integer, Integer> owned = Map.of(4151, 1); // abyssal whip
		OptimizerService service = new OptimizerService(data);
		try
		{
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			ServiceCalls.bestPerStyle(service, goblin, player, player, PrayerUnlocks.ALL, noQuests,
				new OwnedItems(owned, true), 1, false, false, "", Collections.emptySet(), -1,
				OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, Collections.emptySet(), 0, results ->
				{
					out.set(results);
					done.countDown();
				});
			assertTrue(done.await(120, TimeUnit.SECONDS));
			assertEquals(7462, out.get().get(CombatStyle.MELEE).overallBest.getLoadout().get(GearSlot.HANDS).getId(),
				"Barrows gloves: RFD is not a wall on the ceiling; Ferocious stays out on levels");
		}
		finally
		{
			service.shutdown();
		}
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearSearchTestSupport;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Assert;
import org.junit.Test;

/** Per-mob sims scope to their mob (field bug 2026-07-18): "Sim here"
 * on one group member must equip that mob's answer WITHOUT leaking the
 * pretend-owned item into the rest of the roster's shared answers. */
public class GroupSimScopingTest
{
	@Test
	public void perMobSimReachesTheRosterAnswer() throws Exception
	{
		LoadoutData data = new DataService().load();
		MonsterStats vorkath = data.searchMonsters("vorkath", 1).get(0);
		MonsterStats goblin = data.searchMonsters("goblin", 1).get(0);
		int whip = 4151;
		int rapier = GearSearchTestSupport.searchGear(data, "ghrazi rapier", 1).get(0).getId();
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(whip, 1);
		// Sim the rapier for the GOBLIN only.
		Map<Integer, java.util.Set<Integer>> dreamsByMob =
			Collections.singletonMap(goblin.profileId(), Collections.singleton(rapier));
		OptimizerService service = new OptimizerService(data);
		try
		{
			for (int maxSwaps : new int[]{1, 3})
			{
				CountDownLatch done = new CountDownLatch(1);
				AtomicReference<OptimizerService.RosterResult> out = new AtomicReference<>();
				service.bestPerStyleAcross(
					Arrays.asList(vorkath, goblin), PlayerLevels.MAXED, PlayerLevels.MAXED,
					PrayerUnlocks.ALL, RequirementProfile.MAXED,
					new OwnedItems(owned, true), 1, false, false, "",
					Collections.emptyMap(), -1, OptimizationRequest.DEFAULT_RISK_BUDGET_GP,
					false, 0, true, Collections.emptyMap(), Collections.emptyMap(), false, Collections.emptySet(), 0, 					maxSwaps, Collections.emptyMap(), dreamsByMob,
					Collections.emptyMap(), null, 0, Collections.emptySet(),
					roster -> { out.set(roster); done.countDown(); });
				Assert.assertTrue("timed out", done.await(90, TimeUnit.SECONDS));
				List<Map<CombatStyle, OptimizerService.StyleResult>> perMob = out.get().perMob;
				OptimizerService.StyleResult vsGoblin = perMob.get(1).get(CombatStyle.MELEE);
				OptimizerService.StyleResult vsVorkath = perMob.get(0).get(CombatStyle.MELEE);
				System.out.println("maxSwaps=" + maxSwaps
					+ " goblin weapon=" + name(vsGoblin)
					+ " vorkath weapon=" + name(vsVorkath));
				Assert.assertEquals("the simmed rapier answers the goblin (maxSwaps=" + maxSwaps + ")",
					rapier, vsGoblin.owned.get(0).getLoadout().get(GearSlot.WEAPON).getId());
				Assert.assertEquals("vorkath stays on the real bank",
					whip, vsVorkath.owned.get(0).getLoadout().get(GearSlot.WEAPON).getId());
			}
		}
		finally
		{
			service.shutdown();
		}
	}

	private static String name(OptimizerService.StyleResult r)
	{
		if (r == null || r.owned == null || r.owned.isEmpty())
		{
			return "EMPTY";
		}
		return r.owned.get(0).getLoadout().get(GearSlot.WEAPON) == null ? "none"
			: r.owned.get(0).getLoadout().get(GearSlot.WEAPON).getNameLower();
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.MonsterMechanics;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Assert;
import org.junit.Test;

/**
 * The single-mob cache key must carry the ToA invocation level (found
 * by a token-diet agent 2026-08-09: optimizeKey had it, baseKeyFor did
 * not - so flipping the Invocation chip on a Warden card served the
 * PREVIOUS level's cached results). The defence scaling
 * (x(250+invo)/250) guarantees the two levels' numbers must differ.
 */
public class InvocationCacheKeyTest
{
	private static Map<CombatStyle, OptimizerService.StyleResult> best(
		OptimizerService service, MonsterStats monster) throws Exception
	{
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out =
			new AtomicReference<>();
		ServiceCalls.bestPerStyle(service, monster,
			PlayerLevels.MAXED, PlayerLevels.MAXED, PrayerUnlocks.ALL,
			RequirementProfile.MAXED, OwnedItems.EMPTY, 1,
			false, false, "", new EnumMap<>(CombatStyle.class), -1,
			com.loadoutlab.engine.OptimizationRequest.DEFAULT_RISK_BUDGET_GP,
			false, false, Collections.emptySet(), 0,
			Collections.emptyMap(), null, Collections.emptySet(),
			r -> { out.set(r); done.countDown(); });
		Assert.assertTrue("compute timed out", done.await(120, TimeUnit.SECONDS));
		return out.get();
	}

	@Test
	public void flippingTheInvocationLevelNeverServesStaleResults() throws Exception
	{
		LoadoutData data = new DataService().load();
		MonsterStats warden = data.searchMonsters("tumeken's warden", 6).stream()
			.filter(m -> MonsterMechanics.isToaInvocationScaled(m))
			.findFirst().orElseThrow();
		OptimizerService service = new OptimizerService(data);
		try
		{
			double atZero = best(service, MonsterMechanics.atToaInvocation(warden, 0))
				.get(CombatStyle.RANGED).overallBest.getDps();
			double at300 = best(service, MonsterMechanics.atToaInvocation(warden, 300))
				.get(CombatStyle.RANGED).overallBest.getDps();
			Assert.assertNotEquals("invocation 300 must not serve the cached"
					+ " invocation-0 numbers (defence x2.2 has to move the dps)",
				atZero, at300, 1e-9);
			Assert.assertTrue("higher invocation means lower dps",
				at300 < atZero);
		}
		finally
		{
			service.shutdown();
		}
	}
}

package com.loadoutlab.optimizer;

