		reqLevels.put(Skill.THIEVING, 70);
		reqLevels.put(Skill.MINING, 70);
		reqLevels.put(Skill.SMITHING, 70);
		reqLevels.put(Skill.FISHING, 70);
		reqLevels.put(Skill.COOKING, 70);
		reqLevels.put(Skill.FIREMAKING, 70);
		reqLevels.put(Skill.WOODCUTTING, 70);
		reqLevels.put(Skill.RUNECRAFT, 60);
		RequirementProfile requirements = new RequirementProfile(
			reqLevels, RequirementProfile.MAXED.getCompletedQuests());
		return new PlayerProfile(levels, levels, unlocks, requirements, bank(data), true);
	}

	/** Item ids for the fixture bank, resolved by name; fails loudly on a miss. */
	public static Map<Integer, Integer> bank(LoadoutData data)
	{
		Map<Integer, Integer> owned = new LinkedHashMap<>();
		// Potions are consumables, not gear, so they cannot be resolved by name
		// from the equipment corpus - they go in by id.
		//
		// These are EXACTLY what the pre-0.4.1 rule assumed for free ("tradeable
		// potions are always assumed"). Boosts now gate on ownership, so a
		// fixture with tbow-tier gear and an empty potion shelf would have
		// silently dropped every golden to unboosted numbers. Stocking it keeps
		// the goldens exercising the boosted math AND makes the diff prove the
		// point: for a bank that HAS the potions, 0.4.1 changes nothing.
		owned.put(12695, 1);  // super combat potion(4)
		owned.put(2444, 1);   // ranging potion(4)
		owned.put(3040, 1);   // magic potion(4)
		// The premium combat runes, for the same reason - the spell gate (also
		// 0.4.1) drops blood/death/soul/wrath spells from a bank without
		// them, and a runeless fixture would quietly narrow the goldens to
		// strike spells. Stocked, they prove the gate changes nothing for a
		// player who HAS the runes.
		owned.put(565, 10000);   // blood rune
		owned.put(560, 10000);   // death rune
		owned.put(566, 10000);   // soul rune
		owned.put(21880, 10000); // wrath rune
		List<String> missing = new ArrayList<>();
		for (String name : BANK_NAMES)
		{
			GearItem item = firstByName(data, name);
			if (item == null)
			{
				missing.add(name);
			}
			else
			{
				owned.put(item.getId(), 1);
			}
		}
		if (!missing.isEmpty())
		{
			throw new IllegalStateException("Fixture bank items not in dataset: " + missing);
		}
		return owned;
	}

	private static GearItem firstByName(LoadoutData data, String name)
	{
		GearItem fallback = null;
		for (GearItem item : data.getGearItems())
		{
			if (!item.getName().equalsIgnoreCase(name) || !item.isStandardGear()
				|| data.isVariant(item.getId()))
			{
				continue;
			}
			if (item.getVersion().isEmpty())
			{
				return item;
			}
			if (fallback == null)
			{
				fallback = item;
			}
		}
		return fallback;
	}
}

package com.loadoutlab.profile;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.DpsResult;
import com.loadoutlab.engine.PvpRisk;
import com.loadoutlab.optimizer.OptimizerService;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

/**
 * The mock environment: run any Loadout Lab query from the command line
 * against a PlayerProfile - no client, no game login.
 *
 *   ./gradlew query -Pargs="vorkath"
 *   ./gradlew query -Pargs="callisto --low-risk 3 --slayer"
 *   ./gradlew query -Pargs="callisto --low-risk 3 --risk-budget 25000"
 *   ./gradlew query -Pargs="green dragon --profile /path/to/profile.json"
 *   ./gradlew query -Pargs="zulrah --maxed"
 *
 * Default profile: ~/.runelite/loadout-lab/profile.json (the plugin
 * exports your real account there on every in-game query). --maxed uses
 * a maxed account owning nothing (game-best only).
 */
public final class HeadlessQuery
{
	private HeadlessQuery()
	{
	}

	public static void main(String[] args) throws Exception
	{
		System.out.println(run(args));
	}

	public static String run(String[] args) throws Exception
	{
		StringBuilder monsterName = new StringBuilder();
		Path profilePath = Path.of(System.getProperty("user.home"),
			".runelite", "loadout-lab", "profile.json");
		boolean maxed = false;
		boolean slayer = false;
		boolean f2p = false;
		boolean antifirePotion = false;
		boolean wilderness = false;
		String spellbook = "";
		int lowRisk = -1;
		int riskBudget = com.loadoutlab.engine.OptimizationRequest.DEFAULT_RISK_BUDGET_GP;
		int upgradeBudget = 0;
		java.util.Set<Integer> excluded = new java.util.HashSet<>();
		for (int i = 0; i < args.length; i++)
		{
			switch (args[i])
			{
				case "--profile": profilePath = Path.of(args[++i]); break;
				case "--maxed": maxed = true; break;
				case "--slayer": slayer = true; break;
				case "--f2p": f2p = true; break;
				case "--antifire-potion": antifirePotion = true; break;
				case "--wilderness": wilderness = true; break;
				case "--spellbook": spellbook = args[++i]; break;
				case "--low-risk": lowRisk = Integer.parseInt(args[++i]); break;
				case "--risk-budget": riskBudget = Integer.parseInt(args[++i]); break;
				case "--budget": upgradeBudget = Integer.parseInt(args[++i]); break;
				// Comma-separated item ids - reproduce a client report with
				// the player's exclusion list (config: loadoutlab.excludedItems).
				case "--exclude":
					for (String id : args[++i].split(","))
					{
						excluded.add(Integer.parseInt(id.trim()));
					}
					break;
				default: monsterName.append(monsterName.length() > 0 ? " " : "").append(args[i]);
			}
		}
		PlayerProfile profile = maxed ? PlayerProfileTestSupport.maxed()
			: PlayerProfile.fromJson(Files.readString(profilePath));

		LoadoutData data = new DataService().load();
		java.util.List<MonsterStats> hits = data.searchMonsters(monsterName.toString(), 1);
		if (hits.isEmpty())
		{
			return "No monster matches '" + monsterName + "'";
		}
		MonsterStats monster = hits.get(0);

		OptimizerService service = new OptimizerService(data);
		try
		{
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			java.util.Map<CombatStyle, java.util.Set<Integer>> excludedByStyle =
				new java.util.EnumMap<>(CombatStyle.class);
			for (CombatStyle style : CombatStyle.concreteValues())
			{
				excludedByStyle.put(style, excluded);
			}
			boolean inWilderness = wilderness
				|| com.loadoutlab.data.WildernessMonsters.isExclusive(monster);
			com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, monster, profile.realLevels, profile.boostedLevels,
				profile.prayerUnlocks, profile.requirements, profile.ownedItems(),
				profile.owned.hashCode(), f2p, slayer, spellbook,
				excludedByStyle, lowRisk, riskBudget, antifirePotion, inWilderness,
				java.util.Collections.emptySet(), upgradeBudget,
				java.util.Collections.emptyMap(), null, java.util.Collections.emptySet(),
				results ->
				{
					out.set(results);
					done.countDown();
				});
			if (!done.await(180, TimeUnit.SECONDS))
			{
				return "Query timed out";
			}
			return render(monster, out.get(), lowRisk);
		}
		finally
		{
			service.shutdown();
		}
	}

	private static String render(MonsterStats monster,
		Map<CombatStyle, OptimizerService.StyleResult> results, int lowRisk)
	{
		StringBuilder sb = new StringBuilder("=== vs ").append(monster.label()).append(" ===\n");
		for (CombatStyle style : new CombatStyle[]{CombatStyle.MELEE, CombatStyle.RANGED, CombatStyle.MAGIC})
		{
			OptimizerService.StyleResult result = results.get(style);
			sb.append("\n[").append(style).append("]\n");
			if (result == null || result.owned.isEmpty())
			{
				sb.append("  yours: no usable set\n");
			}
			else
			{
				DpsResult best = result.owned.get(0);
				sb.append(String.format("  yours: %.2f dps (max %d, %.0f%% acc)  assumes: %s%n",
					best.getDps(), best.getMaxHit(), best.getAccuracy() * 100, result.boostLabel));
				for (GearSlot slot : GearSlot.values())
				{
					GearItem item = best.getLoadout().get(slot);
					if (item != null)
					{
						sb.append(String.format("    %-7s %s%n", slot, item.label()));
					}
				}
				if (best.getSpellName() != null)
				{
					sb.append("    spell   ").append(best.getSpellName()).append('\n');
				}
				if (result.specWeapon != null)
				{
					sb.append(String.format("    spec    %s (adds ~%.2f dps, avg %.0f dmg)%n",
						result.specWeapon.label(), result.specDpsAdded, result.specExpectedDamage));
				}
				if (result.incoming != null && result.incoming.protectPrayer != null)
				{
					sb.append(String.format("    incoming ~%.2f dps praying %s (~%.2f unprayed)%n",
						result.incoming.totalDps, result.incoming.protectPrayer,
						result.incoming.unprayedDps));
				}
				if (lowRisk >= 0)
				{
					PvpRisk.Assessment risk = PvpRisk.assess(best.getLoadout(), result.specWeapon, lowRisk);
					sb.append(String.format("    risk    %s gp (%d kept)%n",
						formatGp(risk.riskGp), lowRisk));
				}
			}
			if (result != null && result.overallBest != null)
			{
				sb.append(String.format("  game best: %.2f dps  assumes: %s%n",
					result.overallBest.getDps(), result.gameBoostLabel));
			}
		}
		return sb.toString();
	}

	/** Compact gp: 1.20B / 45.3M / 820k / 950. */
	private static String formatGp(long gp)
	{
		if (gp >= 1_000_000_000L)
		{
			return String.format("%.2fB", gp / 1_000_000_000.0);
		}
		if (gp >= 1_000_000L)
		{
			return String.format("%.1fM", gp / 1_000_000.0);
		}
		return gp >= 1_000L ? gp / 1_000L + "k" : String.valueOf(gp);
	}
}

package com.loadoutlab.profile;

import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;
import org.junit.Assert;
import org.junit.Test;

public class PlayerProfileTest
{
	@Test
	public void aProfileSurvivesTheJsonRoundTripExactly()
	{
		PlayerProfile original = new PlayerProfile(
			new PlayerLevels(75, 80, 70, 85, 77, 52, 82),
			new PlayerLevels(80, 85, 70, 89, 77, 52, 82),
			new PrayerUnlocks(true, false, true, false, false),
			new RequirementProfile(Map.of(Skill.ATTACK, 75, Skill.SLAYER, 60),
				Set.of("Dragon Slayer I", "Monkey Madness I")),
			Map.of(4151, 1, 11832, 1, 12934, 5000),
			true);
		PlayerProfile copy = PlayerProfile.fromJson(original.toJson());
		Assert.assertEquals(75, copy.realLevels.getAttack());
		Assert.assertEquals(89, copy.boostedLevels.getRanged());
		Assert.assertTrue(copy.prayerUnlocks.piety());
		Assert.assertFalse(copy.prayerUnlocks.rigour());
		Assert.assertTrue(copy.prayerUnlocks.augury());
		Assert.assertEquals(Integer.valueOf(60), copy.requirements.getLevels().get(Skill.SLAYER));
		Assert.assertTrue(copy.requirements.getCompletedQuests().contains("Monkey Madness I"));
		Assert.assertEquals(Integer.valueOf(5000), copy.owned.get(12934));
		Assert.assertTrue(copy.bankScanned);
	}

	@Test
	public void theHeadlessRunnerAnswersAQueryWithoutAClient() throws Exception
	{
		String out = HeadlessQuery.run(new String[]{"vorkath", "--maxed"});
		Assert.assertTrue(out, out.contains("vs Vorkath"));
		Assert.assertTrue(out, out.contains("game best:"));
		Assert.assertTrue(out, out.contains("[Ranged]"));
	}

	@Test
	public void aMockUserWithABankDrivesOwnedResults() throws Exception
	{
		PlayerProfile mock = new PlayerProfile(PlayerLevels.MAXED, PlayerLevels.MAXED,
			PrayerUnlocks.ALL, RequirementProfile.MAXED,
			Map.of(4151, 1, 1712, 1), true);
		java.nio.file.Path file = java.nio.file.Files.createTempFile("profile", ".json");
		java.nio.file.Files.writeString(file, mock.toJson());
		String out = HeadlessQuery.run(new String[]{"goblin", "--profile", file.toString()});
		Assert.assertTrue(out, out.contains("Abyssal whip"));
		Assert.assertTrue(out, out.contains("Amulet of glory"));
	}

	/** Field report 2026-09-01: a 45-prayer account saw Piety after logging
	 * out - the snapshot was dropped and the MAXED fallback priced a
	 * stranger wearing its bank. Logout keeps the last character; only a
	 * different character replaces it. */
	@Test
	public void theLastCharactersSnapshotSurvivesLogoutButNotASwitch()
	{
		long me = 1234L;
		Assert.assertTrue("logout keeps the last character",
			PlayerProfile.snapshotSurvives(me, -1));
		Assert.assertTrue("same character re-login keeps it",
			PlayerProfile.snapshotSurvives(me, me));
		Assert.assertFalse("a different character replaces it",
			PlayerProfile.snapshotSurvives(me, 5678L));
		Assert.assertFalse("a hashless snapshot is replaced once the hash arrives",
			PlayerProfile.snapshotSurvives(-1, me));
	}
}

