/**
 * A ConfigManager test double whose get/set/unsetConfiguration methods are
 * backed by an in-memory map - the same fake pattern proven on goal-planner:
 * real stores run against this instead of parallel fake store classes.
 */
public final class InMemoryConfigManager
{
	private InMemoryConfigManager()
	{
	}

	public static ConfigManager create()
	{
		ConfigManager mock = Mockito.mock(ConfigManager.class);
		Map<String, String> store = new HashMap<>();

		Mockito.when(mock.getConfiguration(Mockito.anyString(), Mockito.anyString()))
			.thenAnswer(inv -> store.get(inv.getArgument(0) + "." + inv.getArgument(1)));
		// Stub the STRING overload specifically: javac resolves
		// setConfiguration(group, key, someString) to (String,String,String),
		// and a stub on the (String,String,Object) overload would not match it.
		Mockito.doAnswer(inv ->
		{
			store.put(inv.getArgument(0) + "." + inv.getArgument(1), inv.getArgument(2));
			return null;
		}).when(mock).setConfiguration(Mockito.anyString(), Mockito.anyString(), Mockito.anyString());
		Mockito.doAnswer(inv ->
		{
			store.remove(inv.getArgument(0) + "." + inv.getArgument(1));
			return null;
		}).when(mock).unsetConfiguration(Mockito.anyString(), Mockito.anyString());

		return mock;
	}
}

package com.loadoutlab.ui;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The thumbnail's wiki file name comes from the bundled corpus, never
 * from guessing at the wiki's naming conventions - that is what keeps a
 * monster picture to exactly ONE request. These exercise the resolution
 * against the real corpus; none of them touch the network.
 */
class MonsterIconsTest
{
	private final MonsterIcons icons = new MonsterIcons(null);

	@Test
	@DisplayName("a versioned mob resolves to its own per-form picture")
	void perFormImage()
	{
		assertEquals("Abyssal demon (Catacombs of Kourend).png",
			icons.wikiFile("Abyssal demon", "Catacombs of Kourend"));
		assertEquals("Zulrah (magma).png", icons.wikiFile("Zulrah", "Magma"));
		assertEquals("Zulrah (tanzanite).png", icons.wikiFile("Zulrah", "Tanzanite"));
	}

	@Test
	@DisplayName("no version falls back to the plain picture when the mob has one")
	void plainPreferredForBareName()
	{
		// The corpus lists the Catacombs form FIRST, so first-wins would
		// hand a plain "abyssal demon" search the wrong picture.
		assertEquals("Abyssal demon.png", icons.wikiFile("Abyssal demon", ""));
		assertEquals("Vorkath.png", icons.wikiFile("Vorkath", ""));
	}

	@Test
	@DisplayName("no version and no plain picture falls back to a form")
	void formFallbackWhenNoPlainImage()
	{
		// Zulrah is only ever a coloured form - any of them beats no icon.
		assertTrue(icons.wikiFile("Zulrah", "").startsWith("Zulrah ("),
			"expected a Zulrah form image");
	}

	@Test
	@DisplayName("an unknown version falls back to the mob's picture")
	void unknownVersionFallsBack()
	{
		assertEquals("Vorkath.png", icons.wikiFile("Vorkath", "Not a real form"));
	}

	@Test
	@DisplayName("lookup is case-insensitive")
	void caseInsensitive()
	{
		assertEquals("Vorkath.png", icons.wikiFile("vORKATH", ""));
	}

	@Test
	@DisplayName("a mob the corpus does not name gets no request at all")
	void missResolvesToNull()
	{
		assertNull(icons.wikiFile("Definitely not a monster", ""));
	}
}

package com.loadoutlab.ui;

import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.assertFalse;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Properties;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The issue report's version is build-stamped from build.gradle via
 * processResources; runelite-plugin.properties is still hand-bumped at
 * release. This pins the two together so the desync class that shipped
 * "v0.3.3" reports from a 0.3.4 client (field report 2026-08-07) fails
 * the gate instead of reaching users.
 */
class VersionStampTest
{
	@Test
	@DisplayName("the report's stamped version matches runelite-plugin.properties")
	void stampMatchesPluginProperties() throws Exception
	{
		Properties plugin = new Properties();
		plugin.load(Files.newInputStream(Path.of("runelite-plugin.properties")));
		String released = plugin.getProperty("version");
		assertNotNull(released, "runelite-plugin.properties must declare a version");
		assertEquals(released, com.loadoutlab.PluginVersion.VERSION,
			"build.gradle's version (the stamp) and runelite-plugin.properties"
				+ " have drifted - bump them together");
		assertNotEquals("unknown", com.loadoutlab.PluginVersion.VERSION,
			"the stamped resource must be readable at runtime");
	}

	@Test
	@DisplayName("hub builds never show ${version}: the source fallback matches build.gradle and the stamp is never a placeholder")
	void fallbackMatchesBuild() throws Exception
	{
		String gradle = java.nio.file.Files.readString(java.nio.file.Path.of("build.gradle"));
		java.util.regex.Matcher m = java.util.regex.Pattern.compile("version = '([^']+)'").matcher(gradle);
		assertTrue(m.find(), "build.gradle declares the version");
		assertEquals(m.group(1), com.loadoutlab.PluginVersion.FALLBACK, "bump FALLBACK with the release");
		assertFalse(com.loadoutlab.PluginVersion.VERSION.contains("${"), com.loadoutlab.PluginVersion.VERSION);
		assertEquals(com.loadoutlab.PluginVersion.FALLBACK, com.loadoutlab.PluginVersion.stamp("version=${version}"));
		assertEquals("9.9.9", com.loadoutlab.PluginVersion.stamp("version=9.9.9"));
	}
}
